  const [posUseLoyaltyPoints, setPosUseLoyaltyPoints] = useState(false);
  const [posLoyaltyPointsToRedeem, setPosLoyaltyPointsToRedeem] = useState(0);


  // មុខងារគណនាស្ថិតិកុម្ម៉ង់ទិញ និងទឹកប្រាក់ជាក់ស្តែងរបស់អតិថិជនម្នាក់ៗ
  const getCustomerMetrics = (c) => {
    const cleanCPhone = c.phone ? c.phone.replace(/\D/g, '') : '';

    const matchedOrders = (realOrders || []).filter(o => {
      // មិនរាប់ Orders ដែល Cancelled ឡើយ
      if (o.status === 'Cancelled') return false;

      // ១. បើ Order មានភ្ជាប់ Customer ID ជាក់លាក់
      if (o.customer_id && o.customer_id === c.id) return true;

      // ២. ផ្គូផ្គងតាមលេខទូរស័ព្ទ (ត្រូវមានលេខទូរស័ព្ទត្រឹមត្រូវយ៉ាងតិច ៨ ខ្ទង់)
      const cleanOPhone = o.phone ? o.phone.replace(/\D/g, '') : (o.phone_number ? o.phone_number.replace(/\D/g, '') : '');
      const phoneMatches = cleanCPhone.length >= 8 && cleanCPhone === cleanOPhone;

      // ៣. ផ្គូផ្គងតាមឈ្មោះ (មិនរាប់ឈ្មោះទូទៅដូចជា 'អតិថិជនទូទៅ')
      const isNotGeneral = c.name && c.name.trim() !== 'អតិថិជនទូទៅ' && o.customer && o.customer.trim() !== 'អតិថិជនទូទៅ';
      const nameMatches = isNotGeneral && c.name.trim().toLowerCase() === o.customer.trim().toLowerCase();

      // ៤. ⭐️ លក្ខខណ្ឌកាលបរិច្ឆេទស្តង់ដារ៖ អតិថិជនទើបបង្កើតថ្មី មិនត្រូវរាប់បញ្ចូល Orders ចាស់ៗមុនថ្ងៃចុះឈ្មោះឡើយ ⭐️
      const orderDateStr = (o.created_at || o.date || '').slice(0, 10);
      const joinedDateStr = c.joined ? c.joined.slice(0, 10) : '';
      const isOrderAfterJoined = !joinedDateStr || !orderDateStr || orderDateStr >= joinedDateStr;

      return (phoneMatches || nameMatches) && isOrderAfterJoined;
    });

    const realSpent = matchedOrders.reduce((sum, o) => sum + (parseFloat(o.total || o.total_amount) || 0), 0);
    const totalSpent = (c.baseSpent || 0) + realSpent;
    const totalOrders = (c.baseOrderCount || 0) + matchedOrders.length;
    const lastOrderDate = matchedOrders[0]?.created_at || matchedOrders[0]?.date || c.joined;

    // ⭐️ Debt & Loyalty Metrics ⭐️
    const debtBalance = parseFloat(c.debt_balance) || 0;
    const debtLimit = parseFloat(c.debt_limit) || 200;
    const debtDueDate = c.debt_due_date || null;
    const isOverdue = debtBalance > 0 && debtDueDate && new Date(debtDueDate).getTime() < Date.now();
    const loyaltyPoints = c.loyalty_points != null ? Number(c.loyalty_points) : Math.floor(totalSpent);

    let calculatedTier = c.tier || 'REGULAR';
    if (c.tier !== 'WHOLESALE') {
      if (totalSpent >= 800 || loyaltyPoints >= 800) calculatedTier = 'DIAMOND';
      else if (totalSpent >= 300 || loyaltyPoints >= 300) calculatedTier = 'VIP';
      else if (totalSpent >= 100 || loyaltyPoints >= 100) calculatedTier = 'LOYAL';
    }

    return {
      orders: matchedOrders,
      totalOrders,
      totalSpent,
      lastOrderDate,
      debtBalance,
      debtLimit,
      debtDueDate,
      isOverdue,
      loyaltyPoints,
      calculatedTier
    };
  };

  // បើក Modal បង្កើតអតិថិជនថ្មី
  const openCreateCustomerModal = () => {
    setEditingCustomer(null);
    setCustFormName('');
    setCustFormPhone('');
    setCustFormTelegram('');
    setCustFormAddress('');
    setCustFormTier('REGULAR');
    setCustFormDiscount('0');
    setCustFormNotes('');
    setCustFormDebtLimit('200');
    setCustFormDueDate('');
    setCustFormInitialPoints('0');
    setCustomerModalOpen(true);
  };

  // បើក Modal កែប្រែអតិថិជនចាស់
  const openEditCustomerModal = (c) => {
    setEditingCustomer(c);
    setCustFormName(c.name || '');
    setCustFormPhone(c.phone || '');
    setCustFormTelegram(c.telegram || '');
    setCustFormAddress(c.address || '');
    setCustFormTier(c.tier || 'REGULAR');
    setCustFormDiscount(c.discount_percent != null ? c.discount_percent.toString() : '0');
    setCustFormNotes(c.notes || '');
    setCustFormDebtLimit(c.debt_limit != null ? c.debt_limit.toString() : '200');
    setCustFormDueDate(c.debt_due_date || '');
    setCustFormInitialPoints(c.loyalty_points != null ? c.loyalty_points.toString() : '0');
    setCustomerModalOpen(true);
  };

  // រក្សាទុកអតិថិជន (Save / Update Customer)
  const handleSaveCustomer = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (guardDemoAction("កែប្រែព័ត៌មានអតិថិជន")) return;
    e.preventDefault();
    if (!custFormName.trim()) {
      alert('សូមបញ្ចូលឈ្មោះអតិថិជន!');
      return;
    }
    if (!custFormPhone.trim()) {
      alert('សូមបញ្ចូលលេខទូរស័ព្ទអតិថិជន!');
      return;
    }

    if (editingCustomer) {
      // កែប្រែអតិថិជន
      setCustomers(prev => prev.map(c => {
        if (c.id === editingCustomer.id) {
          return {
            ...c,
            name: custFormName.trim(),
            phone: custFormPhone.trim(),
            telegram: custFormTelegram.trim().replace(/^@/, ''),
            address: custFormAddress.trim(),
            tier: custFormTier,
            discount_percent: parseFloat(custFormDiscount) || 0,
            notes: custFormNotes.trim(),
            debt_limit: parseFloat(custFormDebtLimit) || 200,
            debt_due_date: custFormDueDate || null,
            loyalty_points: Number(custFormInitialPoints) || (c.loyalty_points || 0)
          };
        }
        return c;
      }));
      alert('✅ កែប្រែព័ត៌មានអតិថិជនជោគជ័យ!');
    } else {
      // បង្កើតអតិថិជនថ្មី
      const newCustomer = {
        id: `CUS-${Math.floor(1000 + Math.random() * 9000)}`,
        name: custFormName.trim(),
        phone: custFormPhone.trim(),
        telegram: custFormTelegram.trim().replace(/^@/, ''),
        address: custFormAddress.trim(),
        tier: custFormTier,
        discount_percent: parseFloat(custFormDiscount) || 0,
        notes: custFormNotes.trim(),
        joined: new Date().toISOString().split('T')[0],
        baseSpent: 0,
        baseOrderCount: 0,
        store_id: activeStore?.id || 'store_default_sabayluk',
        debt_balance: 0,
        debt_limit: parseFloat(custFormDebtLimit) || 200,
        debt_due_date: custFormDueDate || null,
        debt_history: [],
        loyalty_points: Number(custFormInitialPoints) || 0,
        points_history: []
      };
      setCustomers(prev => [newCustomer, ...prev]);
      alert('🎉 បង្កើតអតិថិជនថ្មីបានជោគជ័យ!');
    }

    setCustomerModalOpen(false);
  };

  // ⭐️ មុខងារសងបំណុលអតិថិជន (RECORD DEBT REPAYMENT) ⭐️
  const handleDebtRepaySubmit = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (guardDemoAction("កត់ត្រាសងបំណុល")) return;

    if (!debtRepayCustomer) return;
    const repayVal = parseFloat(debtRepayAmount);
    const currentBalance = parseFloat(debtRepayCustomer.debt_balance) || 0;

    if (isNaN(repayVal) || repayVal <= 0) {
      alert('សូមបញ្ចូលចំនួនទឹកប្រាក់សងឱ្យបានត្រឹមត្រូវ!');
      return;
    }
    if (repayVal > currentBalance) {
      alert(`ចំនួនទឹកប្រាក់សង ($${repayVal.toFixed(2)}) លើសពីបំណុលជាក់ស្តែង ($${currentBalance.toFixed(2)})!`);
      return;
    }

    setIsSavingDebtRepay(true);
    const newBalance = Math.max(0, currentBalance - repayVal);
    const nowIso = new Date().toISOString();
    const receiptId = `DBT-${Date.now().toString().slice(-6)}`;

    const newHistoryEntry = {
      id: `DH-${Date.now()}`,
      receipt_id: receiptId,
      date: nowIso,
      type: 'REPAYMENT',
      amount: repayVal,
      prev_balance: currentBalance,
      remaining_balance: newBalance,
      payment_method: debtRepayMethod,
      note: debtRepayNote.trim() || 'សងបំណុល',
      recorded_by: currentStaff?.name || 'Staff'
    };

    setCustomers(prev => prev.map(c => {
      if (c.id === debtRepayCustomer.id) {
        return {
          ...c,
          debt_balance: newBalance,
          debt_history: [newHistoryEntry, ...(c.debt_history || [])]
        };
      }
      return c;
    }));

    const receiptObj = {
      id: receiptId,
      date: nowIso,
      customer: debtRepayCustomer,
      amount: repayVal,
      prevBalance: currentBalance,
      remainingBalance: newBalance,
      paymentMethod: debtRepayMethod,
      note: debtRepayNote.trim(),
      cashier: currentStaff?.name || 'Staff',
      storeName: activeStore?.name || storeSettings?.storeName || 'SABAY LUK'
    };

    setLastDebtReceiptData(receiptObj);
    setIsSavingDebtRepay(false);
    setDebtRepayModalOpen(false);
    setDebtReceiptModalOpen(true);
    setToastNotification(`🎉 បានកត់ត្រាការសងបំណុល $${repayVal.toFixed(2)} របស់ "${debtRepayCustomer.name}" ជោគជ័យ!`);
    setTimeout(() => setToastNotification(null), 4000);
  };

  // ⭐️ មុខងារកែសម្រួលពិន្ទុ LOYALTY (ADJUST LOYALTY POINTS) ⭐️
  const handleLoyaltyAdjustSubmit = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!loyaltyAdjustCustomer) return;

    const delta = parseInt(loyaltyPointsDelta, 10);
    if (isNaN(delta) || delta <= 0) {
      alert('សូមបញ្ចូលចំនួនពិន្ទុឱ្យបានត្រឹមត្រូវ!');
      return;
    }

    const currentPts = loyaltyAdjustCustomer.loyalty_points != null ? Number(loyaltyAdjustCustomer.loyalty_points) : 0;
    const finalDelta = loyaltyAdjustType === 'DEDUCT' ? -delta : delta;
    const newPts = Math.max(0, currentPts + finalDelta);

    const historyEntry = {
      id: `LP-${Date.now()}`,
      date: new Date().toISOString(),
      type: loyaltyAdjustType === 'DEDUCT' ? 'REDEEMED' : 'BONUS',
      points: finalDelta,
      prev_points: currentPts,
      remaining_points: newPts,
      reason: loyaltyAdjustReason.trim() || (loyaltyAdjustType === 'DEDUCT' ? 'ដកពិន្ទុប្តូររង្វាន់' : 'បន្ថែមពិន្ទុលើកទឹកចិត្ត'),
      recorded_by: currentStaff?.name || 'Staff'
    };

    setCustomers(prev => prev.map(c => {
      if (c.id === loyaltyAdjustCustomer.id) {
        return {
          ...c,
          loyalty_points: newPts,
          points_history: [historyEntry, ...(c.points_history || [])]
        };
      }
      return c;
    }));

    setLoyaltyAdjustModalOpen(false);
    setToastNotification(`🎉 បានកែសម្រួលពិន្ទុ Loyalty របស់ "${loyaltyAdjustCustomer.name}" ជោគជ័យ! ពិន្ទុសរុប: ${newPts} pts`);
    setTimeout(() => setToastNotification(null), 4000);
  };

  // លុបអតិថិជន
  const handleDeleteCustomer = async (id) => {
    if (guardDemoAction("លុបអតិថិជន")) return;
    const ok = await showConfirmModal({
      title: 'លុបអតិថិជន (Delete Customer)',
      message: 'តើបងពិតជាចង់លុបអតិថិជននេះចេញពីប្រព័ន្ធមែនទេ?',
      confirmText: 'យល់ព្រមលុប',
      cancelText: 'បោះបង់',
      type: 'danger',
      icon: '👤'
    });
    if (ok) {
      setCustomers(prev => prev.filter(c => c.id !== id));
    }
  };

  // ⭐️ មុខងារកត់ត្រាជំពាក់ដោយដៃ (MANUAL ADD DEBT CHARGE) ⭐️
  const handleManualAddDebtSubmit = (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (!manualDebtCustomerId) {
      alert('⚠️ សូមជ្រើសរើសអតិថិជនដែលត្រូវកត់ត្រាជំពាក់!');
      return;
    }
    const amountVal = parseFloat(manualDebtAmount);
    if (isNaN(amountVal) || amountVal <= 0) {
      alert('⚠️ សូមបញ្ចូលចំនួនទឹកប្រាក់ជំពាក់ឱ្យបានត្រឹមត្រូវ!');
      return;
    }
    const targetCust = (currentStoreCustomers || []).find(c => c.id === manualDebtCustomerId);
    if (!targetCust) return;

    const currentBalance = parseFloat(targetCust.debt_balance || 0);
    const newBalance = currentBalance + amountVal;
    const nowIso = new Date().toISOString();
    const historyEntry = {
      id: `DH-${Date.now()}`,
      date: nowIso,
      type: 'CHARGE',
      amount: amountVal,
      prev_balance: currentBalance,
      remaining_balance: newBalance,
      due_date: manualDebtDueDate || targetCust.debt_due_date || null,
      note: manualDebtNote.trim() || 'កត់ត្រាជំពាក់ដោយដៃ (Manual Charge)',
      recorded_by: currentStaff?.name || 'Admin / Cashier'
    };

    setCustomers(prev => prev.map(c => {
      if (c.id === targetCust.id) {
        return {
          ...c,
          debt_balance: newBalance,
          debt_due_date: manualDebtDueDate || c.debt_due_date,
          debt_history: [historyEntry, ...(c.debt_history || [])]
        };
      }
      return c;
    }));

    setManualDebtModalOpen(false);
    setManualDebtCustomerId('');
    setManualDebtAmount('');
    setManualDebtDueDate('');
    setManualDebtNote('');
    setToastNotification(`✅ បានកត់ត្រាការជំពាក់ $${amountVal.toFixed(2)} លើ "${targetCust.name}" ជោគជ័យ! បំណុលសរុប: $${newBalance.toFixed(2)}`);
    setTimeout(() => setToastNotification(null), 4000);
  };

  // ⭐️ មុខងារបោះពុម្ពរបាយការណ៍បំណុលអតិថិជន (PRINT DEBT STATEMENT SLIP) ⭐️
  const handlePrintDebtLedgerSlip = (customer) => {
    if (!customer || typeof window === 'undefined') return;
    const store = getActiveStore();
    const storeName = store?.name || storeSettings.storeName || 'SABAY LUK';
    const storePhone = store?.phone || storeSettings.phone || '096 720 5522';
    const storeAddress = store?.address || storeSettings.address || 'ភ្នំពេញ, កម្ពុជា';
    const curBalance = parseFloat(customer.debt_balance || 0);
    const history = customer.debt_history || [];

    const printWin = window.open('', '_blank', 'width=500,height=700');
    if (!printWin) {
      window.print();
      return;
    }

    const rowsHtml = history.length === 0 ? `
      <tr><td colspan="4" style="text-align:center; padding:10px; color:#888;">មិនមានប្រវត្តិប្រតិបត្តិការឡើយ</td></tr>
    ` : history.map(h => `
      <tr style="border-bottom: 1px dashed #ddd; font-size: 10px;">
        <td style="padding: 4px 0;">${new Date(h.date).toLocaleDateString('km-KH')}</td>
        <td style="padding: 4px 0;">${h.type === 'CHARGE' ? '📦 ជំពាក់' : '💵 សង'} (${h.note || ''})</td>
        <td style="padding: 4px 0; text-align: right; color: ${h.type === 'CHARGE' ? '#dc2626' : '#16a34a'}; font-weight: bold;">
          ${h.type === 'CHARGE' ? '+' : '-'}$${parseFloat(h.amount || 0).toFixed(2)}
        </td>
        <td style="padding: 4px 0; text-align: right; font-weight: bold;">$${parseFloat(h.remaining_balance || 0).toFixed(2)}</td>
      </tr>
    `).join('');

    printWin.document.write(`
      <html>
        <head>
          <title>Debt Statement - ${customer.name}</title>
          <style>
            @page { size: 80mm auto; margin: 0; }
            body { font-family: monospace; width: 76mm; margin: 0 auto; padding: 5mm 2mm; font-size: 11px; line-height: 1.3; color: #000; }
            .center { text-align: center; }
            .bold { font-weight: bold; }
            .dashed { border-bottom: 1px dashed #000; margin: 6px 0; }
            table { width: 100%; border-collapse: collapse; }
          </style>
        </head>
        <body>
          <div class="center">
            <h2 style="margin: 0; font-size: 16px;">${storeName}</h2>
            <p style="margin: 2px 0; font-size: 10px;">${storePhone} • ${storeAddress}</p>
            <div class="dashed"></div>
            <h3 style="margin: 4px 0; font-size: 13px;">*** របាយការណ៍បំណុលអតិថិជន ***</h3>
            <div style="font-size: 10px; font-weight: bold; color: #333;">STATEMENT OF ACCOUNT</div>
            <div class="dashed"></div>
          </div>

          <div style="font-size: 10px; margin-bottom: 6px;">
            <div><b>អតិថិជន:</b> ${customer.name}</div>
            <div><b>ទូរស័ព្ទ:</b> ${customer.phone || 'មិនមាន'}</div>
            ${customer.address ? `<div><b>អាសយដ្ឋាន:</b> ${customer.address}</div>` : ''}
            <div><b>កាលបរិច្ឆេទចេញ:</b> ${new Date().toLocaleString('km-KH')}</div>
            ${customer.debt_due_date ? `<div><b>កាលកំណត់សង:</b> ${customer.debt_due_date}</div>` : ''}
          </div>

          <div class="dashed"></div>

          <table>
            <thead>
              <tr style="border-bottom: 1px solid #000; font-size: 10px;">
                <th style="text-align: left; padding: 2px 0;">កាលបរិច្ឆេទ</th>
                <th style="text-align: left; padding: 2px 0;">ប្រតិបត្តិការ</th>
                <th style="text-align: right; padding: 2px 0;">ទឹកប្រាក់</th>
                <th style="text-align: right; padding: 2px 0;">នៅសល់</th>
              </tr>
            </thead>
            <tbody>
              ${rowsHtml}
            </tbody>
          </table>

          <div class="dashed"></div>

          <div style="margin: 6px 0; font-size: 12px;">
            <div style="display: flex; justify-content: space-between; font-weight: bold; font-size: 14px; color: #dc2626;">
              <span>បំណុលនៅសល់សរុប:</span>
              <span>$${curBalance.toFixed(2)}</span>
            </div>
            <div style="display: flex; justify-content: space-between; font-size: 11px; color: #444;">
              <span>ជាប្រាក់រៀល:</span>
              <span class="bold">${Math.round(curBalance * (storeSettings.exchangeRate || 4100)).toLocaleString()} ៛</span>
            </div>
          </div>

          <div class="dashed"></div>

          <div style="font-size: 9px; margin-top: 15px; text-align: center; color: #555;">
            សូមពិនិត្យ និងទូទាត់ប្រាក់ឱ្យបានទាន់ពេលវេលា។ សូមអរគុណ!
          </div>

          <script>
            window.onload = function() { window.focus(); window.print(); };
            window.onafterprint = function() { window.close(); };
          </script>
        </body>
      </html>
    `);
    printWin.document.close();
  };

  // លក់ជូនអតិថិជននេះផ្ទាល់ក្នុង POS (Quick Sell)
  const handleQuickSellToCustomer = (c) => {
    setCustomerName(c.name);
    setCustomerPhone(c.phone);
    if (c.tier === 'WHOLESALE') {
      handleSwitchPriceMode('wholesale');
    } else {
      handleSwitchPriceMode('retail');
    }
    if (c.discount_percent > 0) {
      setDiscount(c.discount_percent);
    } else {
      setDiscount(0);
    }
    setActiveTab('pos');
  };

  // បើកមើលប្រវត្តិទិញទំនិញ
  const openCustomerHistory = (c) => {
    setSelectedCustomerForHistory(c);
    setCustomerHistoryModalOpen(true);
  };

  // នាំចេញបញ្ជីអតិថិជនជា Excel / CSV
  const exportCustomersToCSV = () => {
    if (customers.length === 0) {
      alert('មិនមានទិន្នន័យអតិថិជនសម្រាប់នាំចេញទេ!');
      return;
    }

    const headers = ['ID', 'ឈ្មោះអតិថិជន', 'លេខទូរស័ព្ទ', 'Telegram', 'ប្រភេទអតិថិជន', 'ពិន្ទុ Loyalty (pts)', 'បំណុលបច្ចុប្បន្ន ($)', 'ថ្ងៃកំណត់សង', 'ទំហំឥណទាន ($)', 'បញ្ចុះតម្លៃ (%)', 'ចំនួនកុម្ម៉ង់', 'ចំណាយសរុប ($)', 'អាសយដ្ឋាន', 'កំណត់ចំណាំ', 'កាលបរិច្ឆេទចុះឈ្មោះ'];
    
    const rows = customers.map(c => {
      const metric = getCustomerMetrics(c);
      const tierLabel = c.tier === 'VIP' ? 'VIP' : c.tier === 'WHOLESALE' ? 'បោះដុំ' : c.tier === 'LOYAL' ? 'ស្មោះត្រង់' : 'ទូទៅ';
      return [
        `"${c.id}"`,
        `"${(c.name || '').replace(/"/g, '""')}"`,
        `"${(c.phone || '').replace(/"/g, '""')}"`,
        `"${(c.telegram ? '@' + c.telegram : '').replace(/"/g, '""')}"`,
        `"${tierLabel}"`,
        `"${metric.loyaltyPoints || 0}"`,
        `"${metric.debtBalance ? metric.debtBalance.toFixed(2) : '0.00'}"`,
        `"${metric.debtDueDate || ''}"`,
        `"${metric.debtLimit || 200}"`,
        `"${c.discount_percent || 0}%"`,
        `"${metric.totalOrders}"`,
        `"${metric.totalSpent.toFixed(2)}"`,
        `"${(c.address || '').replace(/"/g, '""')}"`,
        `"${(c.notes || '').replace(/"/g, '""')}"`,
        `"${c.joined || ''}"`
      ].join(',');
    });

    const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `SabayLuk_Customers_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // ================= ផ្នែកគ្រប់គ្រងទិន្នន័យស្តុក (INVENTORY STATES) =================
  const [products, setProducts] = useState([]);
  const [categories, setCategories] = useState([]);

  // ⭐️ ទិន្នន័យទំនិញ និង Categories ត្រូវទាញយកតាម Store ID នីមួយៗក្នុង Unified Store Switch Effect ខាងក្រោម ⭐️
  const [loading, setLoading] = useState(true);

  // States សម្រាប់ Search និង Filter ក្នុងផ្ទាំង Inventory
  const [invSearch, setInvSearch] = useState('');
  const [invCategory, setInvCategory] = useState('all');
  const [invViewMode, setInvViewMode] = useState(() => {
    if (typeof window !== 'undefined') {
      return localStorage.getItem('sabay_inv_view_mode') || 'table';
    }
    return 'table';
  });
  const [invSortBy, setInvSortBy] = useState('newest');
  const [selectedInvProductIds, setSelectedInvProductIds] = useState([]);
  const [quickStockUpdatingId, setQuickStockUpdatingId] = useState(null);

  useEffect(() => {
    fetchProducts();
    fetchCategories();

    // ⭐️ ធ្វើបច្ចុប្បន្នភាពបញ្ជីហាងពី Supabase ពេលបើក Dashboard ដំបូង ⭐️
    fetchAllStores().then(synced => {
      if (Array.isArray(synced)) {
        setRegisteredStores(synced);

        // 🚨 ត្រួតពិនិត្យប្រសិនបើហាងដែលកំពុងបើកត្រូវបានលុបចេញពី Cloud Database
        const currentActive = getActiveStore();
        if (currentActive && currentActive.id !== 'store_default_sabayluk') {
          const stillExists = synced.some(s => s.id === currentActive.id || s.slug === currentActive.slug);
          if (!stillExists) {
            console.warn(`🚨 ហាង "${currentActive.name}" ត្រូវបានលុបចេញពីប្រព័ន្ធ! បញ្ជូនទៅហាងមេវិញ...`);
            setActiveStore(DEFAULT_FLAGSHIP_STORE);
            setActiveStoreState(DEFAULT_FLAGSHIP_STORE);
            try {
              localStorage.removeItem('sabay_admin_active_store');
              localStorage.setItem('sabay_active_store', JSON.stringify(DEFAULT_FLAGSHIP_STORE));
              localStorage.removeItem(`sabay_active_staff_${currentActive.id}`);
              localStorage.removeItem(`sabay_staff_list_${currentActive.id}`);
              const url = new URL(window.location.href);
              url.searchParams.delete('store');
              window.history.replaceState({}, '', url.toString());
            } catch (_) {}
            setToastNotification(`⚠️ ហាង "${currentActive.name}" ត្រូវបានលុបចេញពីប្រព័ន្ធរួចរាល់ហើយ! ប្រព័ន្ធបានបញ្ជូនលោកអ្នកមកកាន់ហាងមេវិញ។`);
            setTimeout(() => setToastNotification(null), 4000);
          } else {
            // ⭐️ Sync ហាងសកម្ម និង Staff List ចេញពី Cloud Database ⭐️
            const syncedActive = synced.find(s => s.id === currentActive.id || s.slug === currentActive.slug);
            if (syncedActive) {
              setActiveStoreState(syncedActive);
              const freshStaff = getStoreStaffList(syncedActive);
              setStaffList(prev => {
                if (!prev || prev.length === 0) return freshStaff;
                if (JSON.stringify(prev) === JSON.stringify(freshStaff)) return prev;
                return freshStaff;
              });
            }
          }
        } else if (currentActive) {
          const flagshipSynced = synced.find(s => s.id === 'store_default_sabayluk');
          if (flagshipSynced) {
            setActiveStoreState(flagshipSynced);
            const freshStaff = getStoreStaffList(flagshipSynced);
            setStaffList(prev => {
              if (!prev || prev.length === 0) return freshStaff;
              if (JSON.stringify(prev) === JSON.stringify(freshStaff)) return prev;
              return freshStaff;
            });
          }
        }
      }
    }).catch(() => {});

    // ⭐️ ត្រួតពិនិត្យ Offline / Online Event ស្វ័យប្រវត្តិ & Sync វិក្កយបត្រពេលមាន Internet ឡើងវិញ ⭐️
    const handleBackOnline = async () => {
      setToastNotification('🟢 អ៊ីនធឺណិតបានភ្ជាប់ឡើងវិញ! កំពុង Sync វិក្កយបត្រក្រៅបណ្តាញចូលប្រព័ន្ធ...');
      const res = await syncOfflineOrdersToCloud();
      if (res.synced > 0) {
        setToastNotification(`🎉 បាន Sync វិក្កយបត្រក្រៅបណ្តាញ ${res.synced} ដោយជោគជ័យ!`);
        fetchProducts();
        fetchRealOrders();
      }
      setTimeout(() => setToastNotification(null), 4000);
    };

    const handleWentOffline = () => {
      setToastNotification('📡 កំពុងប្រើប្រាស់ក្រៅបណ្តាញ (Offline Mode) • អាចលក់ POS បានធម្មតា!');
      setTimeout(() => setToastNotification(null), 5000);
    };

    if (typeof window !== 'undefined') {
      window.addEventListener('online', handleBackOnline);
      window.addEventListener('offline', handleWentOffline);
      // Run once on mount if there are pending offline orders
      if (navigator.onLine) {
        syncOfflineOrdersToCloud().then(res => {
          if (res.synced > 0) {
            fetchRealOrders();
            fetchProducts();
          }
        });
      }
    }

    return () => {
      if (typeof window !== 'undefined') {
        window.removeEventListener('online', handleBackOnline);
        window.removeEventListener('offline', handleWentOffline);
      }
    };
  }, []);

  async function fetchProducts(targetStoreId) {
    setLoading(true);
    const storeId = targetStoreId || activeStore?.id || 'store_default_sabayluk';
    let data = null;
    let error = null;
    try {
      let query = supabase.from('products').select('*, product_variants(id, size, color, stock_qty)');
      if (storeId === 'store_default_sabayluk') {
        query = query.or(`store_id.eq.${storeId},store_id.is.null`);
      } else {
        query = query.eq('store_id', storeId);
      }
      const res = await query.order('created_at', { ascending: false });
      data = res.data;
      error = res.error;
    } catch (err) {
      error = err;
    }

    // 📡 ប្រសិនបើគ្មាន Internet ឬ Error បណ្តាញ៖ ទាញយកទំនិញពី Offline Cache មកប្រើប្រាស់
    if (error || !data) {
      const cached = getCachedProductsOffline(activeStore?.id);
      if (cached && cached.length > 0) {
        setProducts(cached);
        setLoading(false);
        return;
      }
    }

    if (!error && data) {
      const mapped = data.map(p => {
        const parsed = parseProductMeta(p);
        // ⭐️ សុវត្ថិភាពស្តុកតឹងតែង៖ បើទំនិញមាន Variants ត្រូវគណនាស្តុកសរុបស្មើផលបូក Variants ជានិច្ច
        if (p.product_variants && Array.isArray(p.product_variants) && p.product_variants.length > 0) {
          const variantStockSum = p.product_variants.reduce((sum, v) => sum + (Number(v.stock_qty) || 0), 0);
          parsed.stock_qty = variantStockSum;
        }
        return parsed;
      });
      setProducts(mapped);
      // រក្សាទុក Cache ទំនិញក្នុង LocalStorage ដើម្បីលក់បានពេលគ្មាន Internet (Offline Mode)
      cacheProductsOffline(activeStore?.id, mapped);
      // កំណត់ SKU ជាប់លេខចុងក្រោយបង្អស់ដោយស្វ័យប្រវត្តិតាមហាងនីមួយៗ
      if (!editingProductId) {
        const sid = activeStore?.id || 'store_default_sabayluk';
        const storePrefix = getStoreSkuPrefix(activeStore);
        const currentSavedSku = typeof window !== 'undefined' ? (localStorage.getItem(`sabay_current_sku_${sid}`) || localStorage.getItem(`sabay_last_saved_sku_${sid}`)) : null;
        if (currentSavedSku && currentSavedSku.startsWith(storePrefix)) {
          setSku(currentSavedSku);
        } else {
          const nextSku = computeNextSku(mapped, activeStore);
          setSku(nextSku);
          if (typeof window !== 'undefined') {
            localStorage.setItem(`sabay_current_sku_${sid}`, nextSku);
            localStorage.setItem(`sabay_last_saved_sku_${sid}`, nextSku);
          }
        }
      }
    }
    setLoading(false);
  }

  async function fetchCategories(targetStoreId) {
    const storeId = targetStoreId || activeStore?.id || 'store_default_sabayluk';
    try {
      let query = supabase.from('categories').select('*');
      if (storeId === 'store_default_sabayluk') {
        query = query.or(`store_id.eq.${storeId},store_id.is.null`);
      } else {
        query = query.eq('store_id', storeId);
      }
      const { data, error } = await query.order('created_at', { ascending: true });
      if (!error && data) {
        setCategories(data);
        if (data.length > 0) {
          setCategory(prev => data.find(c => c.name === prev) ? prev : data[0].name);
        } else {
          const defaultCats = [
            { id: '1', name: 'ស្បែកជើងបុរស', icon: 'shoe', store_id: storeId },
            { id: '2', name: 'ស្បែកជើងនារី', icon: 'heel', store_id: storeId },
            { id: '3', name: 'កាបូប & ខ្សែក្រវាត់', icon: 'bag', store_id: storeId },
            { id: '4', name: 'សម្លៀកបំពាក់', icon: 'shirt', store_id: storeId },
            { id: '5', name: 'ទូទៅ', icon: 'box', store_id: storeId }
          ];
          setCategories(defaultCats);
          setCategory('ស្បែកជើងបុរស');
        }
      } else {
        const defaultCats = [
          { id: '1', name: 'ស្បែកជើងបុរស', icon: 'shoe', store_id: storeId },
          { id: '2', name: 'ស្បែកជើងនារី', icon: 'heel', store_id: storeId },
          { id: '3', name: 'កាបូប & ខ្សែក្រវាត់', icon: 'bag', store_id: storeId },
          { id: '4', name: 'សម្លៀកបំពាក់', icon: 'shirt', store_id: storeId },
          { id: '5', name: 'ទូទៅ', icon: 'box', store_id: storeId }
        ];
        setCategories(defaultCats);
        setCategory('ស្បែកជើងបុរស');
      }
    } catch (e) {
      const defaultCats = [
        { id: '1', name: 'ស្បែកជើងបុរស', icon: 'shoe', store_id: storeId },
        { id: '2', name: 'ស្បែកជើងនារី', icon: 'heel', store_id: storeId },
        { id: '3', name: 'កាបូប & ខ្សែក្រវាត់', icon: 'bag', store_id: storeId },
        { id: '4', name: 'សម្លៀកបំពាក់', icon: 'shirt', store_id: storeId }
      ];
      setCategories(defaultCats);
      setCategory('ស្បែកជើងបុរស');
    }
  }

    // ================= ប្រព័ន្ធ POS STATES កម្រិតស្តង់ដារ =================
  const [posCart, setPosCart] = useState([]);
