  // Function ទាញយកទិន្នន័យ Orders ពិតពី Supabase (Scoped Per Store)
  const fetchRealOrders = async (targetStoreId) => {
    setLoadingOrders(true);
    const storeId = targetStoreId || activeStore?.id || 'store_default_sabayluk';
    let query = supabase.from('orders').select('*');
    if (storeId === 'store_default_sabayluk') {
      query = query.or(`store_id.eq.${storeId},store_id.is.null`);
    } else {
      query = query.eq('store_id', storeId);
    }
    const { data, error } = await query.order('created_at', { ascending: false });

    if (!error && data) {
      let localRefunds = [];
      if (typeof window !== 'undefined') {
        try {
          localRefunds = JSON.parse(localStorage.getItem(`sabay_refunds_${storeId}`) || '[]');
        } catch (_) {}
      }
      const refundMap = new Map();
      localRefunds.forEach(r => {
        if (r.order_id) refundMap.set(String(r.order_id), r);
        if (r.order_display_id) refundMap.set(String(r.order_display_id), r);
      });

      const mapped = data.map(o => {
        const ref = refundMap.get(String(o.id)) || refundMap.get(String(o.order_id));
        return {
          ...o,
          status: ref ? (ref.is_full ? 'Refunded' : (o.status === 'Refunded' ? 'Refunded' : 'Partially Refunded')) : o.status,
          refunded_amount: ref ? (parseFloat(ref.refunded_amount) || 0) : (parseFloat(o.refunded_amount) || 0),
          refund_details: ref || o.refund_details || null,
          customer: o.customer_name || o.customer || 'អតិថិជនទូទៅ',
          total: o.total_amount != null ? o.total_amount : (o.total || 0),
          payment: o.payment_method || o.payment || 'Cash',
          phone: o.phone_number || o.phone || '',
          address: o.delivery_address || o.address || ''
        };
      });

      // Merge queued offline orders waiting to sync for this store
      try {
        const offlineQueue = getOfflineOrdersQueue();
        const pendingForStore = offlineQueue
          .filter(q => (q.orderPayload?.store_id || 'store_default_sabayluk') === storeId)
          .map(q => ({
            ...q.orderPayload,
            id: q.id || `offline_${q.orderPayload?.order_id}`,
            customer: q.orderPayload?.customer_name || 'អតិថិជនទូទៅ',
            total: q.orderPayload?.total_amount != null ? q.orderPayload.total_amount : (q.orderPayload?.total || 0),
            payment: q.orderPayload?.payment_method || 'Cash',
            phone: q.orderPayload?.phone_number || q.orderPayload?.phone || '',
            address: q.orderPayload?.delivery_address || q.orderPayload?.address || 'POS មុខហាង',
            created_at: q.orderPayload?.created_at || q.queued_at || new Date().toISOString(),
            is_offline_pending: true
          }));

        const existingOrderIds = new Set(mapped.map(m => String(m.order_id || m.id).trim()));
        pendingForStore.forEach(po => {
          const poKey = String(po.order_id || po.id).trim();
          if (poKey && !existingOrderIds.has(poKey)) {
            mapped.unshift(po);
            existingOrderIds.add(poKey);
          }
        });
      } catch (_) {}

      // Strict deduplication & sort newest first by created_at DESC
      const seenOrderIds = new Set();
      const uniqueOrders = [];
      for (const order of mapped) {
        const key = String(order.order_id || order.id || '').trim();
        if (key && !seenOrderIds.has(key)) {
          seenOrderIds.add(key);
          uniqueOrders.push(order);
        } else if (!key) {
          uniqueOrders.push(order);
        }
      }
      uniqueOrders.sort((a, b) => {
        const timeA = new Date(a.created_at || a.date || 0).getTime();
        const timeB = new Date(b.created_at || b.date || 0).getTime();
        return timeB - timeA;
      });

      setRealOrders(uniqueOrders);
    }
    setLoadingOrders(false);
  };

  // ⭐️ MULTI-TENANT ISOLATED DATA SLICES (ធានាមិនឆ្លងទិន្នន័យគ្នា ១០០%) ⭐️
  const currentStoreProducts = useMemo(() => {
    const storeId = activeStore?.id || 'store_default_sabayluk';
    return products.filter(p => {
      const pStore = p.store_id || 'store_default_sabayluk';
      return pStore === storeId;
    });
  }, [products, activeStore?.id]);

  // ⭐️ Filtered out-of-stock and low-stock items for current store ⭐️
  const stockAlertData = useMemo(() => {
    return filterLowAndOutOfStock(currentStoreProducts);
  }, [currentStoreProducts]);

  // ⭐️ Auto Check & Trigger Daily 8:00 AM Telegram Stock Alert & Sync Snooze State ⭐️
  useEffect(() => {
    if (!activeStore) return;
    const snoozed = isStockAlertSnoozedToday(activeStore.id);
    setStockAlertSnoozed(snoozed);

    const runStockTgCheck = async () => {
      if (!currentStoreProducts || currentStoreProducts.length === 0) return;
      try {
        await sendDailyTelegramStockAlert(activeStore, currentStoreProducts);
      } catch (err) {
        console.warn('Auto stock alert check error:', err);
      }
    };

    runStockTgCheck();
    const timer = setInterval(runStockTgCheck, 15 * 60 * 1000);
    return () => clearInterval(timer);
  }, [activeStore?.id, currentStoreProducts?.length]);

  const jumpIndexRef = useRef(0);
  const handleJumpToOutOfStock = (product) => {
    const list = stockAlertData.allAlertItems || [];
    if (list.length === 0) return;

    let target = product;
    if (!target) {
      const idx = jumpIndexRef.current % list.length;
      target = list[idx];
      jumpIndexRef.current = (idx + 1) % list.length;
    }

    setStockAlertDrawerOpen(false);
    // User request 163: Scroll directly to product without opening any popup modal!
    jumpToProductInInventory(target, {
      setActiveTab,
      setInventorySubTab,
      setFilterStatus,
      setInvSearch
    });
  };

  const handleSnoozeAlertToday = (e) => {
    if (e && e.stopPropagation) e.stopPropagation();
    snoozeStockAlertForToday(activeStore?.id);
    setStockAlertSnoozed(true);
    setStockAlertDrawerOpen(false);
    setToastNotification('💤 បានលាក់ការ Alert សម្រាប់ថ្ងៃនេះ! ប្រសិនបើមិនទាន់ដោះស្រាយ វានឹងលោតជូនដំណឹងឡើងវិញនៅថ្ងៃស្អែក។');
    setTimeout(() => setToastNotification(null), 4000);
  };

  const handleSendManualStockTgAlert = async () => {
    setSendingManualStockAlert(true);
    try {
      const res = await sendDailyTelegramStockAlert(activeStore, currentStoreProducts, { force: true });
      if (res.sent) {
        setToastNotification(`✅ បានផ្ញើដំណឹងស្តុក ${res.count} មុខ ទៅកាន់ Telegram រួចរាល់!`);
      } else {
        const reasonText = res.reason === 'no_low_stock_items' 
          ? 'ទំនិញទាំងអស់មានស្តុកគ្រប់គ្រាន់ គ្មានទំនិញអស់ស្តុកទេ!' 
          : (res.error || res.reason || 'បរាជ័យ');
        setToastNotification(`⚠️ មិនអាចផ្ញើបាន: ${reasonText}`);
      }
    } catch (err) {
      setToastNotification(`❌ កំហុសបណ្តាញ: ${err.message}`);
    } finally {
      setSendingManualStockAlert(false);
      setTimeout(() => setToastNotification(null), 4500);
    }
  };

  const currentStoreOrders = useMemo(() => {
    const storeId = activeStore?.id || 'store_default_sabayluk';
    return realOrders.filter(o => {
      const oStore = o.store_id || 'store_default_sabayluk';
      return oStore === storeId;
    }).sort((a, b) => {
      const timeA = new Date(a.created_at || a.date || 0).getTime();
      const timeB = new Date(b.created_at || b.date || 0).getTime();
      return timeB - timeA;
    });
  }, [realOrders, activeStore?.id]);

  const currentStoreExpenses = useMemo(() => {
    const storeId = activeStore?.id || 'store_default_sabayluk';
    return expenses.filter(e => {
      const eStore = e.store_id || 'store_default_sabayluk';
      return eStore === storeId;
    });
  }, [expenses, activeStore?.id]);

  const currentStoreCategories = useMemo(() => {
    const storeId = activeStore?.id || 'store_default_sabayluk';
    return categories.filter(c => {
      if (storeId === 'store_default_sabayluk') {
        return !c.store_id || c.store_id === 'store_default_sabayluk';
      }
      return c.store_id === storeId;
    });
  }, [categories, activeStore?.id]);

  const currentStoreCustomers = useMemo(() => {
    const storeId = activeStore?.id || 'store_default_sabayluk';
    return customers.filter(c => {
      const cStore = c.store_id || 'store_default_sabayluk';
      return cStore === storeId;
    });
  }, [customers, activeStore?.id]);

  const debtorsCountGlobal = useMemo(() => {
    return (currentStoreCustomers || []).filter(c => (parseFloat(c.debt_balance) || 0) > 0).length;
  }, [currentStoreCustomers]);

  const overdueDebtorsCountGlobal = useMemo(() => {
    const now = Date.now();
    return (currentStoreCustomers || []).filter(c => {
      const bal = parseFloat(c.debt_balance) || 0;
      return bal > 0 && c.debt_due_date && new Date(c.debt_due_date).getTime() < now;
    }).length;
  }, [currentStoreCustomers]);

  // ⭐️ States & Realtime Alert សម្រាប់គ្រប់គ្រងការកុម្ម៉ង់ថ្មី (ADMIN & SALES ALERT) ⭐️
  const [newOrderAlert, setNewOrderAlert] = useState(null);
  const [newStoreAlert, setNewStoreAlert] = useState(null);
  const [highlightedOrderId, setHighlightedOrderId] = useState(null);

  // សំឡេងកណ្ដឹងជូនដំណឹងពេលមានការកុម្ម៉ង់ថ្មី (Notification Chime)
  const playNewOrderSound = () => {
    try {
      const AudioCtx = window.AudioContext || window.webkitAudioContext;
      if (!AudioCtx) return;
      const ctx = new AudioCtx();
      const osc = ctx.createOscillator();
      const gain = ctx.createGain();
      osc.connect(gain);
      gain.connect(ctx.destination);
      osc.type = 'sine';
      osc.frequency.setValueAtTime(587.33, ctx.currentTime); // D5
      osc.frequency.setValueAtTime(880, ctx.currentTime + 0.15); // A5
      gain.gain.setValueAtTime(0.3, ctx.currentTime);
      gain.gain.exponentialRampToValueAtTime(0.01, ctx.currentTime + 0.5);
      osc.start(ctx.currentTime);
      osc.stop(ctx.currentTime + 0.5);
    } catch (e) {}
  };

  useEffect(() => {
    fetchRealOrders();

    // 1. Supabase Realtime Channels (Orders, Stores, Subscriptions)
    let channel;
    let storesChannel;
    let subChannel;
    try {
      channel = supabase
        .channel('admin_orders_channel')
        .on('postgres_changes', { event: 'INSERT', schema: 'public', table: 'orders' }, (payload) => {
          playNewOrderSound();
          fetchRealOrders();
          setNewOrderAlert({
            id: payload.new?.id,
            order_id: payload.new?.order_id || 'ថ្មី',
            customer_name: payload.new?.customer_name || 'អតិថិជន',
            phone: payload.new?.phone || payload.new?.phone_number || '',
            total: payload.new?.total_amount || 0,
            store_id: payload.new?.store_id || 'store_default_sabayluk'
          });
        })
        .subscribe();

      storesChannel = supabase
        .channel('admin_stores_realtime')
        .on('postgres_changes', { event: '*', schema: 'public', table: 'stores' }, (payload) => {
          if (payload?.eventType === 'INSERT') {
            playNewOrderSound();
            fetchAllStores().then(stores => setRegisteredStores(stores));
            setPaymentAlertDismissed(false);
            setNewStoreAlert({
              action: payload.new?.status === 'PENDING_APPROVAL' ? 'new_store_registered_pending_approval' : 'new_store_registered',
              store: payload.new,
              plan: payload.new?.plan || 'FREE',
              slipUrl: payload.new?.settings?.slip_url || payload.new?.slip_url || '',
              timestamp: Date.now()
            });
            setToastNotification('🔔 ទទួលបានការចុះឈ្មោះហាងថ្មីលើប្រព័ន្ធ!');
            setTimeout(() => setToastNotification(null), 4000);
          } else if (payload?.eventType === 'DELETE') {
            fetchAllStores().then(stores => setRegisteredStores(stores));
          }
        })
        .subscribe();

      subChannel = supabase
        .channel('admin_sub_payments_realtime')
        .on('postgres_changes', { event: '*', schema: 'public', table: 'subscription_payments' }, (payload) => {
          playNewOrderSound();
          if (typeof getSubscriptionPayments === 'function') {
            setAllSubscriptionPayments(getSubscriptionPayments());
          }
          setPaymentAlertDismissed(false);
          if (payload?.eventType === 'INSERT') {
            setNewStoreAlert({
              action: 'new_subscription_payment',
              store: { id: payload.new?.store_id, name: payload.new?.store_name, phone: payload.new?.customer_phone },
              plan: payload.new?.plan_name || payload.new?.plan_key,
              price: `$${payload.new?.amount || 0}`,
              slipUrl: payload.new?.slip_url || '',
              ref: payload.new?.notes || '',
              timestamp: Date.now()
            });
          }
          setToastNotification('💳 ទទួលបានបង្កាន់ដៃបង់ប្រាក់កញ្ចប់សេវា (Slip) ថ្មី!');
          setTimeout(() => setToastNotification(null), 4000);
        })
        .subscribe();
    } catch (e) {}

    // 2. Storage event listener (multi-tab sync)
    const handleStorageOrder = (e) => {
      if (e && e.key === 'sabay_new_order_alert' && e.newValue) {
        try {
          const parsed = JSON.parse(e.newValue);
          playNewOrderSound();
          fetchRealOrders();
          setNewOrderAlert(parsed);
        } catch (err) {}
      }
      if (e && (e.key === 'sabay_new_store_alert' || e.key === 'sabay_subscription_alert') && e.newValue) {
        try {
          const parsed = JSON.parse(e.newValue);
          playNewOrderSound();
          setRegisteredStores(getLocalStores());
          if (typeof getSubscriptionPayments === 'function') {
            setAllSubscriptionPayments(getSubscriptionPayments());
          }
          setPaymentAlertDismissed(false);
          setNewStoreAlert(parsed);
          setToastNotification('🔔 ទទួលបានការចុះឈ្មោះហាងថ្មី / បង់ប្រាក់ Slip ថ្មី!');
          setTimeout(() => setToastNotification(null), 4000);
        } catch (err) {}
      }
    };
    window.addEventListener('storage', handleStorageOrder);

    // 3. BroadcastChannel listener (instant cross-tab sync for Admin & Sales)
    let bc = null;
    let bcStores = null;
    let bcSubs = null;
    if (typeof window !== 'undefined' && 'BroadcastChannel' in window) {
      bc = new BroadcastChannel('sabay_orders_sync');
      bc.onmessage = (event) => {
        if (event.data && event.data.type === 'NEW_ORDER') {
          playNewOrderSound();
          fetchRealOrders();
          setNewOrderAlert(event.data);
        }
      };

      bcStores = new BroadcastChannel('sabay_stores_sync');
      bcStores.onmessage = (event) => {
        playNewOrderSound();
        setRegisteredStores(getLocalStores());
        fetchAllStores().then(stores => setRegisteredStores(stores));
        setPaymentAlertDismissed(false);
        if (event.data) {
          setNewStoreAlert(event.data);
        }
        setToastNotification('🔔 ទទួលបានការចុះឈ្មោះហាងថ្មីលើប្រព័ន្ធ!');
        setTimeout(() => setToastNotification(null), 4000);
      };

      bcSubs = new BroadcastChannel('sabay_subscription_sync');
      bcSubs.onmessage = (event) => {
        playNewOrderSound();
        if (typeof getSubscriptionPayments === 'function') {
          setAllSubscriptionPayments(getSubscriptionPayments());
        }
        setPaymentAlertDismissed(false);
        if (event.data) {
          setNewStoreAlert(event.data);
        }
        setToastNotification('💳 ទទួលបានបង្កាន់ដៃបង់ប្រាក់កញ្ចប់សេវា (Slip) ថ្មី!');
        setTimeout(() => setToastNotification(null), 4000);
      };
    }

    return () => {
      if (channel) supabase.removeChannel(channel);
      if (storesChannel) supabase.removeChannel(storesChannel);
      if (subChannel) supabase.removeChannel(subChannel);
      window.removeEventListener('storage', handleStorageOrder);
      if (bc) bc.close();
      if (bcStores) bcStores.close();
      if (bcSubs) bcSubs.close();
    };
  }, []);

  // Function ប្តូរ Status នៃការកុម្ម៉ង់ (Pending ➔ Preparing ➔ Shipped ➔ Completed)
  const handleUpdateOrderStatus = async (orderId, newStatus) => {
    if (guardDemoAction("កែប្រែស្ថានភាព Order")) return;
    try {
      const { error } = await supabase
        .from('orders')
        .update({ status: newStatus })
        .eq('id', orderId);

      if (error) throw error;
      // Update លើ UI ភ្លាមៗ
      setRealOrders(prev => prev.map(o => o.id === orderId ? { ...o, status: newStatus } : o));

      const statusLabels = {
        'Pending': '🟡 រង់ចាំការបញ្ជាក់',
        'Preparing': '🔵 កំពុងរៀបចំវេចខ្ចប់',
        'Shipped': '🚚 កំពុងដឹកជញ្ជូន',
        'Completed': '🟢 ដឹកជញ្ជូនជោគជ័យ',
        'Cancelled': '❌ បានបោះបង់',
        'Refunded': '🔄 បានបង្វិលប្រាក់ (Refunded)',
        'Partially Refunded': '🔄 បង្វិលប្រាក់ខ្លះ (Partially Refunded)'
      };
      setToastNotification(`✅ បានប្តូរស្ថានភាពទៅជា "${statusLabels[newStatus] || newStatus}" រួចរាល់!`);
      setTimeout(() => setToastNotification(null), 3000);
    } catch (err) {
      alert('❌ មិនអាចប្តូរស្ថានភាពបានទេ: ' + err.message);
    }
  };

  // គណនាស្ថិតិពិតប្រាកដចេញពី orders (Real Analytics Calculation with Automated Refund Deductions)
  const realTotalRevenue = realOrders
    .filter(o => o.status !== 'Cancelled')
    .reduce((sum, o) => {
      if (o.status === 'Refunded') return sum;
      const refAmt = parseFloat(o.refunded_amount || o.refund_details?.refunded_amount || 0);
      return sum + Math.max(0, (parseFloat(o.total) || 0) - refAmt);
    }, 0);

  const todayStr = new Date().toISOString().slice(0, 10);
  const realDailySales = realOrders
    .filter(o => o.status !== 'Cancelled' && (o.created_at ? o.created_at.startsWith(todayStr) : true))
    .reduce((sum, o) => {
      if (o.status === 'Refunded') return sum;
      const refAmt = parseFloat(o.refunded_amount || o.refund_details?.refunded_amount || 0);
      return sum + Math.max(0, (parseFloat(o.total) || 0) - refAmt);
    }, 0);

  const realTotalOrdersCount = realOrders.length;

  // ⭐️ Helper Function គណនាសេវាដឹកជញ្ជូនលើ Order (Delivery Fee calculation) ⭐️
  const getOrderDeliveryFee = (order) => {
    if (!order) return 0;
    if (order.delivery_fee != null) return parseFloat(order.delivery_fee) || 0;
    if (order.deliveryFee != null) return parseFloat(order.deliveryFee) || 0;
    if (order.shipping_fee != null) return parseFloat(order.shipping_fee) || 0;
    if (order.shippingFee != null) return parseFloat(order.shippingFee) || 0;
    const items = Array.isArray(order.items) ? order.items : [];
    const delItem = items.find(it => it && (it.is_delivery_meta || it.is_delivery || it.name?.includes('ដឹក') || it.name?.toLowerCase().includes('delivery') || it.name?.toLowerCase().includes('shipping')));
    if (delItem) return parseFloat(delItem.price || delItem.delivery_fee || 0) || 0;
    return 0;
  };

  // ⭐️ Helper Function គណនាពន្ធអាករលើ Order មួយៗ (Tax VAT calculation for any order) ⭐️
  const getOrderTax = (order) => {
    if (!order) return 0;
    if (order.tax_amount != null) return parseFloat(order.tax_amount) || 0;
    if (order.tax != null) return parseFloat(order.tax) || 0;
    if (order.taxAmount != null) return parseFloat(order.taxAmount) || 0;
    const items = Array.isArray(order.items) ? order.items : [];
    const taxMeta = items.find(it => it && (it.is_tax_meta || it.tax_amount != null || it.name?.toLowerCase().includes('vat') || it.name?.includes('ពន្ធ')));
    if (taxMeta && taxMeta.tax_amount != null) return parseFloat(taxMeta.tax_amount) || 0;
    if (taxMeta && taxMeta.price != null) return parseFloat(taxMeta.price) || 0;
    return 0;
  };

  // Helper គណនាទឹកប្រាក់ Refund សរុបស្វ័យប្រវត្ត រួមទាំងថ្លៃដឹក & ពន្ធ
  const recalcRefundTotal = (items, withDel, delAmt, withTx, txAmt) => {
    const itemsSum = (items || refundItemsState)
      .filter(it => it.selected && it.returnQty > 0)
      .reduce((s, it) => s + (it.price * it.returnQty), 0);
    const delPart = withDel ? (parseFloat(delAmt) || 0) : 0;
    const taxPart = withTx ? (parseFloat(txAmt) || 0) : 0;
    const total = itemsSum + delPart + taxPart;
    setRefundCustomAmount(total.toFixed(2));
  };

  // ⭐️ មុខងារបើកផ្ទាំងស្នើសុំបង្វិលទំនិញ & សងប្រាក់វិញ (OPEN PRODUCT REFUND MODAL) ⭐️
  const handleOpenRefundModal = (order) => {
    if (!order) return;
    const items = (Array.isArray(order.items) ? order.items : []).filter(it => !it.is_tax_meta && !it.is_delivery_meta);
    const initialItems = items.map((it, idx) => {
      const q = parseInt(it.qty || it.quantity || 1) || 1;
      const p = parseFloat(it.price || 0) || 0;
      return {
        key: `${it.id || idx}_${it.size || ''}_${it.color || ''}`,
        id: it.id || it.product_id,
        variant_id: it.variant_id || it.variantId || null,
        name: it.name || 'ទំនិញ',
        size: it.size || '',
        color: it.color || '',
        image_url: it.image_url || it.image || '',
        price: p,
        originalQty: q,
        returnQty: q,
        selected: true,
        restock: true
      };
    });
    setRefundOrder(order);
    setRefundItemsState(initialItems);
    setRefundReason('WRONG_SIZE');
    setRefundCustomReason('');
    const payMeth = order.payment === 'KHQR' ? 'BANK' : (order.payment === 'COD' ? 'CASH' : (order.payment || 'CASH'));
    setRefundMethod(payMeth === 'BANK' ? 'BANK' : (payMeth === 'Store Credit' ? 'STORE_CREDIT' : 'CASH'));

    // ពិនិត្យថ្លៃដឹកជញ្ជូន និងពន្ធលើវិក្កយបត្រ (Delivery Fee & Tax)
    const existingDelFee = getOrderDeliveryFee(order);
    const existingTaxAmt = getOrderTax(order);

    setRefundDeliveryFee(false);
    setRefundDeliveryAmount(existingDelFee > 0 ? existingDelFee.toFixed(2) : (storeSettings.deliveryPhnomPenh || '1.50'));
    setRefundTax(false);
    setRefundTaxAmount(existingTaxAmt > 0 ? existingTaxAmt.toFixed(2) : '0.00');

    const initialTotal = initialItems.reduce((s, it) => s + (it.price * it.returnQty), 0);
    setRefundCustomAmount(initialTotal.toFixed(2));
    setRefundModalOpen(true);
  };

  // ⭐️ មុខងារដំណើរការ REFUND ស្វ័យប្រវត្ត (AUTO RESTOCK INVENTORY & DEDUCT REVENUE & CREDIT NOTE) ⭐️
  const handleProcessRefund = async () => {
    if (!refundOrder) return;
    const selectedItems = refundItemsState.filter(it => it.selected && it.returnQty > 0);
    if (selectedItems.length === 0) {
      alert('⚠️ សូមជ្រើសរើសយ៉ាងហោចណាស់ ១ មុខទំនិញដែលត្រូវបង្វិល (Please select at least 1 item to return)');
      return;
    }

    const delFeeRefunded = refundDeliveryFee ? (parseFloat(refundDeliveryAmount) || 0) : 0;
    const taxRefunded = refundTax ? (parseFloat(refundTaxAmount) || 0) : 0;
    const itemsTotal = selectedItems.reduce((s, it) => s + (it.price * it.returnQty), 0);
    const finalAmount = parseFloat(refundCustomAmount) >= 0 ? parseFloat(refundCustomAmount) : (itemsTotal + delFeeRefunded + taxRefunded);
    const storeId = activeStore?.id || 'store_default_sabayluk';
    const orderDisplayId = refundOrder.order_id || refundOrder.id;

    // Reason labels
    const reasonLabels = {
      'WRONG_SIZE': '👟 ខុសទំហំ / Size មិនត្រូវ (Wrong Size)',
      'DEFECTIVE': '⚠️ ទំនិញមានបញ្ហា / ខូចគុណភាព (Defective / Damaged)',
      'CHANGED_MIND': '🔄 ភ្ញៀវប្តូរចិត្ត (Customer Changed Mind)',
      'WRONG_ITEM': '📦 ដឹកខុសទំនិញ / ខុសពណ៌ (Wrong Item Delivered)',
      'NOT_AS_DESCRIBED': '🏷️ មិនត្រូវតាមការពិពណ៌នា (Not as Described)',
      'OTHER': refundCustomReason ? `✍️ ${refundCustomReason}` : '✍️ មូលហេតុផ្សេងៗ (Other Reason)'
    };
    const finalReason = reasonLabels[refundReason] || refundReason;

    // Is full refund?
    const totalOriginalQty = (Array.isArray(refundOrder.items) ? refundOrder.items : [])
      .filter(it => it && !it.is_tax_meta && !it.is_delivery_meta && (it.name || it.title))
      .reduce((s, it) => s + (parseInt(it.qty || it.quantity || 1) || 1), 0);
    const totalReturnedQty = selectedItems.reduce((s, it) => s + it.returnQty, 0);
    const isFullRefund = totalReturnedQty >= totalOriginalQty;
    const newStatus = isFullRefund ? 'Refunded' : 'Partially Refunded';

    setRefundProcessing(true);

    try {
      // ១. បញ្ចូលស្តុកស្វ័យប្រវត្តិ (AUTO RESTOCK TO PRODUCTS & AUDIT LOGS)
      const restockItems = selectedItems.filter(it => it.restock && it.returnQty > 0);
      for (const item of restockItems) {
        if (!item.id) continue;
        try {
          const { data: curP } = await supabase.from('products').select('stock_qty').eq('id', item.id).single();
          const prevStock = curP ? (curP.stock_qty || 0) : 0;
          const newStock = prevStock + item.returnQty;

          await supabase.from('products').update({
            stock_qty: newStock,
            status: 'In Stock'
          }).eq('id', item.id);

          if (item.variant_id) {
            const { data: curV } = await supabase.from('product_variants').select('stock_qty').eq('id', item.variant_id).single();
            if (curV) {
              await supabase.from('product_variants').update({
                stock_qty: (curV.stock_qty || 0) + item.returnQty
              }).eq('id', item.variant_id);
            }
          }

          await supabase.from('stock_movements').insert([{
            product_id: item.id,
            variant_id: item.variant_id || null,
            type: 'IN',
            qty_change: item.returnQty,
            previous_qty: prevStock,
            new_qty: newStock,
            reason: `[បង្វិលទំនិញចូលស្តុក (Refund)] #${orderDisplayId} - ${finalReason}`,
            store_id: storeId
          }]);
        } catch (stockErr) {
          console.warn('Could not restock item via cloud:', item.name, stockErr);
        }
      }

      // ២. Update State products ភ្លាមៗ (Optimistic Stock Update)
      const restockMap = new Map();
      restockItems.forEach(it => {
        restockMap.set(it.id, (restockMap.get(it.id) || 0) + it.returnQty);
      });
      if (restockMap.size > 0) {
        setProducts(prev => prev.map(p => {
          if (restockMap.has(p.id)) {
            const newQ = (p.stock_qty || 0) + restockMap.get(p.id);
            return { ...p, stock_qty: newQ, status: 'In Stock' };
          }
          return p;
        }));
      }

      // ៣. បង្កើតទិន្នន័យ Refund Record (Credit Note)
      const refundRecord = {
        refund_id: `REF-${Date.now().toString().slice(-6)}`,
        order_id: refundOrder.id,
        order_display_id: orderDisplayId,
        refunded_at: new Date().toISOString(),
        refunded_amount: finalAmount,
        refunded_amount_khr: Math.round(finalAmount * (storeSettings.exchangeRate || 4100)),
        refund_delivery_fee: delFeeRefunded,
        refund_tax_amount: taxRefunded,
        reason: finalReason,
        reason_notes: refundCustomReason,
        payment_method: refundMethod === 'BANK' ? 'ABA / Bank Transfer' : (refundMethod === 'STORE_CREDIT' ? 'Store Credit' : 'Cash (សាច់ប្រាក់)'),
        processed_by: currentStaff?.name || 'Admin / Cashier',
        is_full: isFullRefund,
        customer_name: refundOrder.customer || refundOrder.customer_name || 'អតិថិជនទូទៅ',
        customer_phone: refundOrder.phone || refundOrder.phone_number || '',
        items: selectedItems.map(it => ({
          id: it.id,
          name: it.name,
          size: it.size,
          color: it.color,
          qty: it.returnQty,
          price: it.price,
          restocked: it.restock
        }))
      };

      // ៤. Update Status ក្នុង Supabase orders
      try {
        await supabase.from('orders').update({
          status: newStatus
        }).eq('id', refundOrder.id);
      } catch (orderErr) {
        console.warn('Could not update order status in Supabase:', orderErr);
      }

      // ៥. រក្សាទុកក្នុង localStorage (Store Scoped Persistence)
      if (typeof window !== 'undefined') {
        try {
          const existing = JSON.parse(localStorage.getItem(`sabay_refunds_${storeId}`) || '[]');
          const updated = [refundRecord, ...existing.filter(r => r.order_id !== refundOrder.id)];
          localStorage.setItem(`sabay_refunds_${storeId}`, JSON.stringify(updated));
        } catch (_) {}
      }

      // ៦. Update realOrders state ភ្លាមៗ (Optimistic Orders State)
      setRealOrders(prev => prev.map(o => {
        if (o.id === refundOrder.id) {
          return {
            ...o,
            status: newStatus,
            refunded_amount: (parseFloat(o.refunded_amount || 0) + finalAmount),
            refund_details: refundRecord
          };
        }
        return o;
      }));

      // ៧. Update selectedOrderDetails បើកំពុងបើក
      if (selectedOrderDetails && selectedOrderDetails.id === refundOrder.id) {
        setSelectedOrderDetails(prev => ({
          ...prev,
          status: newStatus,
          refunded_amount: (parseFloat(prev.refunded_amount || 0) + finalAmount),
          refund_details: refundRecord
        }));
      }

      // ៨. Fetch stock movements ឡើងវិញ
      fetchStockMovements(storeId);

      // ៩. បង្ហាញ Toast Notification & បើក Credit Note Slip
      setRefundModalOpen(false);
      setCreditNoteData(refundRecord);
      const addonNotes = [
        delFeeRefunded > 0 ? `ថ្លៃដឹក $${delFeeRefunded.toFixed(2)}` : null,
        taxRefunded > 0 ? `ពន្ធ $${taxRefunded.toFixed(2)}` : null
      ].filter(Boolean).join(' + ');
      setToastNotification(`✅ បានដំណើរការ Refund ទឹកប្រាក់ $${finalAmount.toFixed(2)} ${addonNotes ? `(រួមបញ្ចូល ${addonNotes}) ` : ''}និងបញ្ចូលស្តុក ${restockItems.reduce((s, i) => s + i.returnQty, 0)} ឯកតាជោគជ័យ!`);
      setTimeout(() => setToastNotification(null), 4000);

    } catch (err) {
      alert('❌ មានបញ្ហាក្នុងការដំណើរការ Refund: ' + err.message);
    } finally {
      setRefundProcessing(false);
    }
  };

  // ⭐️ មុខងារបោះពុម្ពប័ណ្ណសងប្រាក់ Credit Note (PRINT CREDIT NOTE / REFUND SLIP) ⭐️
  const handlePrintCreditNoteSlip = (record) => {
    if (!record || typeof window === 'undefined') return;
    const store = getActiveStore();
    const storeName = store?.name || storeSettings.storeName || 'SABAY LUK';
    const storePhone = store?.phone || storeSettings.phone || '096 720 5522';
    const storeAddress = store?.address || storeSettings.address || 'ភ្នំពេញ, កម្ពុជា';

    const printWin = window.open('', '_blank', 'width=450,height=650');
    if (!printWin) {
      window.print();
      return;
    }

    const itemsHtml = (record.items || []).map(it => `
      <tr style="border-bottom: 1px dashed #ccc;">
        <td style="padding: 4px 0; font-size: 11px;">
          <b>${it.name}</b>
          ${it.size ? `<span style="font-size: 9px; color: #555;">(Size: ${it.size})</span>` : ''}
          ${it.restocked ? `<div style="font-size: 9px; color: #16a34a;">✓ ចូលស្តុកវិញ</div>` : `<div style="font-size: 9px; color: #dc2626;">⚠️ មិនចូលស្តុក (ខូច)</div>`}
        </td>
        <td style="padding: 4px 0; text-align: center; font-size: 11px;">${it.qty}</td>
        <td style="padding: 4px 0; text-align: right; font-size: 11px;">${it.price.toFixed(2)}</td>
        <td style="padding: 4px 0; text-align: right; font-weight: bold; font-size: 11px;">${(it.qty * it.price).toFixed(2)}</td>
      </tr>
    `).join('');

    printWin.document.write(`
      <html>
        <head>
          <title>Credit Note ${record.refund_id}</title>
          <style>
            @page { size: 80mm auto; margin: 0; }
            body { font-family: monospace; width: 76mm; margin: 0 auto; padding: 5mm 2mm; font-size: 11px; line-height: 1.3; color: #000; }
            .center { text-align: center; }
            .bold { font-weight: bold; }
            .dashed { border-bottom: 1px dashed #000; margin: 6px 0; }
            table { width: 100%; border-collapse: collapse; }
          </style>
        </head>
        <body>
          <div class="center">
            <h2 style="margin: 0; font-size: 16px;">${storeName}</h2>
            <p style="margin: 2px 0; font-size: 10px;">${storePhone} • ${storeAddress}</p>
            <div class="dashed"></div>
            <h3 style="margin: 4px 0; font-size: 13px; letter-spacing: 0.5px;">*** ប័ណ្ណឥណទានសងប្រាក់ ***</h3>
            <div style="font-size: 10px; font-weight: bold; color: #333;">CREDIT NOTE & REFUND RECEIPT</div>
            <div class="dashed"></div>
          </div>

          <div style="font-size: 10px; margin-bottom: 6px;">
            <div><b>លេខប័ណ្ណ (Slip No):</b> ${record.refund_id}</div>
            <div><b>យោងវិក្កយបត្រ (Ref Order):</b> #${record.order_display_id}</div>
            <div><b>កាលបរិច្ឆេទ (Date):</b> ${new Date(record.refunded_at).toLocaleString('km-KH')}</div>
            <div><b>អតិថិជន (Customer):</b> ${record.customer_name || 'អតិថិជនទូទៅ'} ${record.customer_phone ? '(' + record.customer_phone + ')' : ''}</div>
          </div>

          <div class="dashed"></div>

          <table>
            <thead>
              <tr style="border-bottom: 1px solid #000;">
                <th style="text-align: left; padding: 2px 0;">មុខទំនិញ</th>
                <th style="text-align: center; padding: 2px 0;">ចំនួន</th>
                <th style="text-align: right; padding: 2px 0;">តម្លៃ</th>
                <th style="text-align: right; padding: 2px 0;">សរុប</th>
              </tr>
            </thead>
            <tbody>
              ${itemsHtml}
            </tbody>
          </table>

          <div class="dashed"></div>

          <div style="margin: 6px 0; font-size: 11px;">
            <div style="display: flex; justify-content: space-between; margin: 2px 0;">
              <span>មូលហេតុ (Reason):</span>
              <span class="bold" style="text-align: right;">${record.reason}</span>
            </div>
            <div style="display: flex; justify-content: space-between; margin: 2px 0;">
              <span>វិធីសងប្រាក់ (Method):</span>
              <span class="bold">${record.payment_method}</span>
            </div>
            ${parseFloat(record.refund_delivery_fee || 0) > 0 ? `
              <div style="display: flex; justify-content: space-between; margin: 2px 0; color: #b45309;">
                <span>🚚 បង្វិលថ្លៃដឹក (Delivery):</span>
                <span class="bold">+$${parseFloat(record.refund_delivery_fee).toFixed(2)}</span>
              </div>
            ` : ''}
            ${parseFloat(record.refund_tax_amount || 0) > 0 ? `
              <div style="display: flex; justify-content: space-between; margin: 2px 0; color: #4338ca;">
                <span>🏛️ បង្វិលពន្ធអាករ (Tax/VAT):</span>
                <span class="bold">+$${parseFloat(record.refund_tax_amount).toFixed(2)}</span>
              </div>
            ` : ''}
            <div style="display: flex; justify-content: space-between; margin: 4px 0; padding-top: 4px; border-top: 1px solid #000; font-size: 13px;" class="bold">
              <span>ទឹកប្រាក់សងសរុប (REFUND):</span>
              <span>$${parseFloat(record.refunded_amount).toFixed(2)}</span>
            </div>
            <div style="display: flex; justify-content: space-between; font-size: 11px; color: #444;">
              <span>ជាប្រាក់រៀល:</span>
              <span class="bold">${record.refunded_amount_khr.toLocaleString()} ៛</span>
            </div>
          </div>

          <div class="dashed"></div>

          <div style="font-size: 9px; margin-top: 8px;">
            <div><b>បុគ្គលិកទទួលបន្ទុក (Staff):</b> ${record.processed_by}</div>
            <div style="display: flex; justify-content: space-between; margin-top: 25px; text-align: center;">
              <div>
                <div>............................</div>
                <div>ហត្ថលេខាអតិថិជន</div>
              </div>
              <div>
                <div>............................</div>
                <div>ហត្ថលេខាបុគ្គលិក</div>
              </div>
            </div>
            <div class="center" style="margin-top: 15px; font-style: italic;">
              សូមអរគុណសម្រាប់ការគាំទ្រហាងយើងខ្ញុំ!
            </div>
          </div>

          <script>
            window.onload = function() { window.focus(); window.print(); };
            window.onafterprint = function() { window.close(); };
          </script>
        </body>
      </html>
    `);
    printWin.document.close();
  };

  // ⭐️ Helper ទទួលបាន Invoice Settings តាមហាងនីមួយៗ (Per-Store Scoped Invoice Settings - 100% Strict Tenant Isolation) ⭐️
  const getStoreScopedInvoiceSettings = (store) => {
    const storeId = store?.id || 'store_default_sabayluk';
    const isDefault = storeId === 'store_default_sabayluk' || store?.slug === 'sabay-luk';
    const isTenant = !isDefault;
    const dbSettings = store?.settings || {};

    // ១. Load ពី localStorage ជាមុន (highest priority)
    let localParsed = null;
    if (typeof window !== 'undefined') {
      const scoped = localStorage.getItem(`sabay_invoice_settings_${storeId}`);
      if (scoped) {
        try { localParsed = JSON.parse(scoped); } catch (_) {}
      }
    }

    // ២. Load storeSettings localStorage (sabay_store_settings_<id>) សម្រាប់ khqrImageUrl និង logoUrl
    let storeLocalParsed = null;
    if (typeof window !== 'undefined') {
      const sk = localStorage.getItem(`sabay_store_settings_${storeId}`) || (isDefault ? localStorage.getItem('sabay_store_settings') : null);
      if (sk) { try { storeLocalParsed = JSON.parse(sk); } catch (_) {} }
    }

    // ៣. khqrImageUrl — ហាងអតិថិជន ទុកទំនេរឱ្យ Upload ផ្ទាល់ ហាមដាច់ខាតមិនឱ្យទាញ /khqr-aba.jpg ឬ Sabay Luk QR
    let khqrImageUrl = storeLocalParsed?.khqrImageUrl || localParsed?.khqrImageUrl || dbSettings?.khqrImageUrl || (isTenant ? '' : '/khqr-aba.jpg');
    if (isTenant && (khqrImageUrl === '/khqr-aba.jpg' || khqrImageUrl.includes('khqr-aba.jpg'))) {
      khqrImageUrl = ''; // ទុកឱ្យទំនេរ ១០០% ស្របតាមការចង់បានរបស់ម្ចាស់ហាង
    }

    // ៤. logoUrl — ហាងអតិថិជន ទុកទំនេរឱ្យ Upload ផ្ទាល់ ហាមទាញ Logo ពី Sabay Luk
    let logoUrl = storeLocalParsed?.logoUrl || localParsed?.logoUrl || dbSettings?.logoUrl || '';
    if (isTenant && (logoUrl === '/logo.png' || logoUrl.includes('/logo.png'))) {
      logoUrl = '';
    }

    if (localParsed) {
      const fixedName = (isTenant && (localParsed.storeName === 'SABAY LUK' || !localParsed.storeName))
        ? store?.name || 'ហាងរបស់ខ្ញុំ'
        : localParsed.storeName;
      let finalQr = localParsed.khqrImageUrl || khqrImageUrl;
      if (isTenant && (finalQr === '/khqr-aba.jpg' || finalQr.includes('khqr-aba.jpg'))) finalQr = '';
      let finalLogo = localParsed.logoUrl || logoUrl;
      if (isTenant && (finalLogo === '/logo.png' || finalLogo.includes('/logo.png'))) finalLogo = '';
      return {
        ...localParsed,
        storeName: fixedName,
        phone: (isTenant && (localParsed.phone === '096 720 5522' || !localParsed.phone)) ? store?.phone || '' : localParsed.phone,
        address: (isTenant && (!localParsed.address || localParsed.address.includes('Phnom Penh, Cambodia') || localParsed.address.includes('Street 271'))) ? store?.address || '' : localParsed.address,
        logoUrl: finalLogo,
        khqrImageUrl: finalQr
      };
    }

    if (isTenant) {
      return {
        storeName: store?.name || 'ហាងរបស់ខ្ញុំ',
        address: store?.address || dbSettings?.address || '',
        phone: store?.phone || dbSettings?.phone || '',
        title: 'OFFICIAL RECEIPT',
        exchangeRate: storeLocalParsed?.exchangeRate || dbSettings?.exchangeRate || 4100,
        cashierName: 'Admin',
        showKHR: true,
        showLogo: true,
        logoUrl: logoUrl,
        khqrImageUrl: khqrImageUrl,
        thankYouMsg: 'សូមអរគុណ! សូមអញ្ជើញមកម្តងទៀត',
        policyNote: 'ទំនិញដែលទិញរួចមិនអាចប្តូរជាប្រាក់វិញបានទេ'
      };
    }
    return {
      storeName: 'SABAY LUK',
      address: 'Phnom Penh, Cambodia',
      phone: '096 720 5522',
      title: 'OFFICIAL RECEIPT',
      exchangeRate: 4100,
      cashierName: 'Admin',
      showKHR: true,
      showLogo: true,
      logoUrl: logoUrl,
      khqrImageUrl,
      thankYouMsg: 'សូមអរគុណ! សូមអញ្ជើញមកម្តងទៀត',
      policyNote: 'ទំនិញដែលទិញរួចមិនអាចប្តូរជាប្រាក់វិញបានទេ (អាចប្តូរ Size បានក្នុងរង្វង់ ៣ ថ្ងៃ)'
    };
  };

  // State សម្រាប់កំណត់ព័ត៌មានវិក្កយបត្រ (Invoice Settings Scoped)
  const [invoiceSettings, setInvoiceSettings] = useState(() => getStoreScopedInvoiceSettings(getActiveStore()));

  const [invoiceSavedMsg, setInvoiceSavedMsg] = useState('');

  // ================= 🏪 ផ្នែកកំណត់ហាង & ម៉ាកយីហោ FULL OPTION (STORE SETTINGS & BRANDING) =================
  const DEFAULT_STORE_SETTINGS = {
    storeName: 'SABAY LUK',
    storeSlogan: 'Premium Store',
    storeDescription: 'ហាងលក់ស្បែកជើង និងម៉ូដទាន់សម័យគុណភាពខ្ពស់ ផ្ដល់ទំនុកចិត្ត និងភាពស៊ីវិល័យសម្រាប់អ្នក។',
    logoUrl: '',
    phone: '096 720 5522',
    phone2: '012 345 678',
    telegram: 'sabay_luk',
    telegramBotToken: '',
    telegramChatId: '',
    telegramBotUsername: '',
    enableLowStockAlert: true,
    lowStockThreshold: 5,
    abaMerchantId: '',
    abaApiKey: '',
    facebook: 'https://facebook.com',
    tiktok: 'https://tiktok.com',
    address: 'ភ្នំពេញ, ព្រះរាជាណាចក្រកម្ពុជា',
    businessHours: '8:00 AM - 9:00 PM',
    announcementText: '🔥 ដឹកជញ្ជូនឥតគិតថ្លៃ ២៥ ខេត្ត/ក្រុង • ធានាប្តូរ Size ក្នុងរយៈពេល ៧ ថ្ងៃ • ទំនិញម៉ាកសុទ្ធ ១០០%',
    showAnnouncement: true,
    bankAccountName: 'SENG SOVEASNA',
    bankAccountNumber: '010 723 080',
    bankAccountKhr: '004 500 394',
    bankAccountUsd: '010 723 080',
    khqrImageUrl: '/khqr-aba.jpg',
    showInvoiceLogo: true,
    showReceiptQr: true,
    enableDeliveryFee: true,
    deliveryPhnomPenh: '1.50',
    deliveryProvince: '2.50',
    freeShippingThreshold: '0',
    enableTax: false,
    taxRate: 10,
    taxMode: 'exclusive',
    vatTin: '',
    taxLabel: 'ពន្ធអាករ (VAT 10%)',
    policyNote: 'ទំនិញដែលទិញរួចមិនអាចប្តូរជាប្រាក់វិញបានទេ (អាចប្តូរ Size បានក្នុងរង្វង់ ៧ ថ្ងៃ)',
    exchangeRate: 4100,
    themeColor: '#ff6a00',
    themePreset: 'orange'
  };

  // Helper ទទួលបានការកំណត់ហាងនីមួយៗ (Store-specific Settings Isolation)
  const getStoreScopedSettings = (store) => {
    const storeId = store?.id || 'store_default_sabayluk';
    const isDefault = storeId === 'store_default_sabayluk' || store?.slug === 'sabay-luk';
    const storeSpecificKey = `sabay_store_settings_${storeId}`;
    let savedParsed = null;
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem(storeSpecificKey) || (isDefault ? localStorage.getItem('sabay_store_settings') : null);
      if (saved) {
        try { savedParsed = JSON.parse(saved); } catch (e) {}
      }
    }
    const dbSettings = store?.settings || {};
    const isTaxActive = normalizeEnableTax(dbSettings?.enableTax) || normalizeEnableTax(savedParsed?.enableTax);

    // ⭐️ STRICT TENANT ISOLATION (ហាមទាញ Logo, QR Code, ឈ្មោះហាង ឬ Brand ពី Sabay Luk មកលើហាងអតិថិជនដាច់ខាត) ⭐️
    const baseSettings = isDefault ? DEFAULT_STORE_SETTINGS : {
      storeName: store?.name || '',
      storeSlogan: '',
      storeDescription: '',
      logoUrl: '',
      phone: store?.phone || '',
      phone2: '',
      telegram: store?.telegram || '',
      address: store?.address || '',
      bankAccountName: store?.owner_name || store?.name || '',
      bankAccountNumber: '',
      bankAccountKhr: '',
      bankAccountUsd: store?.phone || '',
      khqrImageUrl: '', // ⭐️ STRICT ISOLATION: ហាម default ទៅ /khqr-aba.jpg លើហាងអតិថិជន
      showInvoiceLogo: true,
      showReceiptQr: true,
      enableDeliveryFee: true,
      deliveryPhnomPenh: '1.50',
      deliveryProvince: '2.50',
      freeShippingThreshold: '0',
      enableTax: false,
      taxRate: 10,
      taxMode: 'exclusive',
      vatTin: '',
      taxLabel: 'ពន្ធអាករ (VAT 10%)',
      policyNote: 'ទំនិញដែលទិញរួចមិនអាចប្តូរជាប្រាក់វិញបានទេ',
      exchangeRate: 4100,
      themeColor: '#ff6a00',
      themePreset: 'orange',
      announcementText: '',
      showAnnouncement: false
    };

    const merged = { ...baseSettings, ...dbSettings, ...(savedParsed || {}) };

    let finalStoreName = merged.storeName;
    if (!isDefault) {
      if (!finalStoreName || finalStoreName === 'SABAY LUK' || finalStoreName === 'ហាងថ្មី') {
        finalStoreName = store?.name || 'ហាងរបស់ខ្ញុំ';
      }
    } else {
      finalStoreName = finalStoreName || 'SABAY LUK';
    }

    let finalStoreSlogan = merged.storeSlogan;
    if (!isDefault && finalStoreSlogan === 'Premium Store') {
      finalStoreSlogan = dbSettings?.storeSlogan || '';
    }

    let finalStoreDesc = merged.storeDescription;
    if (!isDefault && (finalStoreDesc === DEFAULT_STORE_SETTINGS.storeDescription || !finalStoreDesc)) {
      finalStoreDesc = dbSettings?.storeDescription || '';
    }

    let finalPhone = merged.phone;
    if (!isDefault && finalPhone === '096 720 5522') {
      finalPhone = store?.phone || dbSettings?.phone || '';
    }

    let finalTelegram = merged.telegram;
    if (!isDefault && (finalTelegram === 'sabay_luk' || finalTelegram === 'sabayluk')) {
      finalTelegram = store?.telegram || dbSettings?.telegram || '';
    }

    let finalBankName = merged.bankAccountName;
    if (!isDefault && (finalBankName === 'SENG SOVEASNA' || finalBankName === 'សេង សុវាសនា')) {
      finalBankName = store?.owner_name || store?.name || dbSettings?.bankAccountName || '';
    }

    let finalBankUsd = merged.bankAccountUsd;
    if (!isDefault && (finalBankUsd === '010 723 080' || finalBankUsd === '010 722 280')) {
      finalBankUsd = store?.phone || dbSettings?.phone || '';
    }

    let finalBankKhr = merged.bankAccountKhr;
    if (!isDefault && (finalBankKhr === '004 500 394' || finalBankKhr === '004500394')) {
      finalBankKhr = '';
    }

    let finalKhqr = merged.khqrImageUrl;
    if (!isDefault && (finalKhqr === '/khqr-aba.jpg' || finalKhqr?.includes('khqr-aba.jpg'))) {
      finalKhqr = ''; // ⭐️ 100% Strict Store Isolation: សម្អាត QR Sabay Luk ចោលពីហាងអតិថិជន
    }

    let finalLogoUrl = merged.logoUrl;
    if (!isDefault && (finalLogoUrl === DEFAULT_STORE_SETTINGS.logoUrl || finalLogoUrl === '/logo.png' || finalLogoUrl?.includes('/logo.png'))) {
      finalLogoUrl = store?.settings?.logoUrl || dbSettings?.logoUrl || '';
    }

    merged.enableTax = isTaxActive;
    if (isTaxActive) {
      merged.taxRate = parseFloat(savedParsed?.taxRate ?? dbSettings?.taxRate ?? 10) || 10;
      merged.taxMode = savedParsed?.taxMode || dbSettings?.taxMode || 'exclusive';
      merged.vatTin = savedParsed?.vatTin || dbSettings?.vatTin || 'K001-90218821';
      merged.taxLabel = savedParsed?.taxLabel || dbSettings?.taxLabel || 'ពន្ធអាករ (VAT 10%)';
    }
    return {
      ...merged,
      storeName: finalStoreName,
      storeSlogan: finalStoreSlogan,
      storeDescription: finalStoreDesc,
      logoUrl: finalLogoUrl,
      khqrImageUrl: finalKhqr,
      bankAccountUsd: finalBankUsd,
      bankAccountKhr: finalBankKhr,
      phone: finalPhone,
      telegram: (() => {
        let tg = (finalTelegram || '').replace(/^@/, '').trim();
        if (isDefault && tg.toLowerCase() === 'sabayluk') tg = 'sabay_luk';
        return tg;
      })(),
      address: merged.address || store?.address || (isDefault ? 'Street 271, Phnom Penh, Cambodia' : ''),
      bankAccountName: finalBankName,
      // ⭐️ 100% STRICT MULTI-TENANT ISOLATION: មួយហាង ត្រូវមានតែមួយ មិនឱ្យជាន់គ្នាដាច់ខាត ⭐️
      telegramBotToken: isDefault 
        ? (savedParsed?.telegramBotToken ?? dbSettings.telegramBotToken ?? DEFAULT_STORE_SETTINGS.telegramBotToken ?? '')
        : (savedParsed?.telegramBotToken ?? dbSettings.telegramBotToken ?? ''),
      telegramChatId: isDefault 
        ? (savedParsed?.telegramChatId ?? dbSettings.telegramChatId ?? DEFAULT_STORE_SETTINGS.telegramChatId ?? '')
        : (savedParsed?.telegramChatId ?? dbSettings.telegramChatId ?? ''),
      telegramBotUsername: isDefault
        ? (savedParsed?.telegramBotUsername ?? dbSettings.telegramBotUsername ?? DEFAULT_STORE_SETTINGS.telegramBotUsername ?? '')
        : (savedParsed?.telegramBotUsername ?? dbSettings.telegramBotUsername ?? ''),
      abaMerchantId: isDefault 
        ? (savedParsed?.abaMerchantId ?? dbSettings.abaMerchantId ?? DEFAULT_STORE_SETTINGS.abaMerchantId ?? '')
        : (savedParsed?.abaMerchantId ?? dbSettings.abaMerchantId ?? ''),
      abaApiKey: isDefault 
        ? (savedParsed?.abaApiKey ?? dbSettings.abaApiKey ?? DEFAULT_STORE_SETTINGS.abaApiKey ?? '')
        : (savedParsed?.abaApiKey ?? dbSettings.abaApiKey ?? ''),
      enableLowStockAlert: savedParsed?.enableLowStockAlert ?? dbSettings.enableLowStockAlert ?? true,
      lowStockThreshold: savedParsed?.lowStockThreshold ?? dbSettings.lowStockThreshold ?? 5
    };
  };

  const [storeSettings, setStoreSettings] = useState(() => getStoreScopedSettings(getActiveStore()));

  // ⭐️ Instant Auto-Save Helper សម្រាប់ Settings (ធានាពេលប្តូរ Toggle ឬ តម្លៃ Sync ភ្លាមៗទៅ Website & LocalStorage & Supabase Cloud) ⭐️
  const updateStoreSettingsImmediate = (newPartial) => {
    const updated = { ...storeSettings, ...newPartial };
    setStoreSettings(updated);

    if (typeof window !== 'undefined') {
      const storeId = activeStore?.id || 'store_default_sabayluk';
      localStorage.setItem(`sabay_store_settings_${storeId}`, JSON.stringify(updated));
      if (storeId === 'store_default_sabayluk') {
        localStorage.setItem('sabay_store_settings', JSON.stringify(updated));
      }

      // Sync activeStore object in state and localStorage
      const updatedStores = (registeredStores || []).map(s => {
        if (s.id === storeId) {
          return { ...s, settings: { ...(s.settings || {}), ...updated } };
        }
        return s;
      });
      setRegisteredStores(updatedStores);
      saveLocalStores(updatedStores);

      // ⭐️ Cloud Sync ភ្លាមៗ ធានា localhost និង 127.0.0.1 ត្រូវគ្នា 100% ⭐️
      try {
        supabase
          .from('stores')
          .update({
            settings: updated,
            updated_at: new Date().toISOString()
          })
          .eq('id', storeId)
          .then(({ error }) => {
            if (error) console.warn('Cloud store settings auto-sync error:', error);
          });
      } catch (err) {
        console.warn('Failed cloud store auto-sync:', err);
      }

      try {
        window.dispatchEvent(new CustomEvent('sabay_store_settings_updated', { detail: updated }));
      } catch (_) {}
    }
  };

  useEffect(() => {
    if (!activeStore) return;
    setStoreSettings(getStoreScopedSettings(activeStore));
    setInvoiceSettings(getStoreScopedInvoiceSettings(activeStore));
  }, [activeStore?.id]);

  useEffect(() => {
    if (typeof window !== 'undefined' && activeStore) {
      try {
        const storeId = activeStore.id || 'store_default_sabayluk';
        localStorage.setItem(`sabay_store_settings_${storeId}`, JSON.stringify(storeSettings));
        if (storeId === 'store_default_sabayluk') {
          localStorage.setItem('sabay_store_settings', JSON.stringify(storeSettings));
        }
      } catch (err) {
        console.warn('⚠️ Quota exceeded while saving storeSettings:', err);
      }
    }
  }, [storeSettings, activeStore?.id]);

  const [storeSettingsSavedMsg, setStoreSettingsSavedMsg] = useState('');
  const [activeSettingsSubTab, setActiveSettingsSubTab] = useState('branding'); // 'branding' | 'contact' | 'announcement' | 'payment' | 'delivery'

  // ⭐️ States សម្រាប់ប្តូរ Password ហាង (Change Store Password / PIN) ⭐️
  const [currentStorePasswordInput, setCurrentStorePasswordInput] = useState('');
  const [newStorePasswordInput, setNewStorePasswordInput] = useState('');
  const [confirmStorePasswordInput, setConfirmStorePasswordInput] = useState('');
  const [showStorePassword, setShowStorePassword] = useState(false);
  const [isUpdatingStorePassword, setIsUpdatingStorePassword] = useState(false);
  const [securityTargetStaffId, setSecurityTargetStaffId] = useState('OWNER');

  // ⭐️ States សម្រាប់សាកល្បងទេសអតិថិជនបញ្ជាទិញផ្ទាល់ពី Website (Live Customer Order Simulator) ⭐️
  const [testOrderModalOpen, setTestOrderModalOpen] = useState(false);
  const [testOrderLocation, setTestOrderLocation] = useState('phnom_penh'); // 'phnom_penh' | 'province'
  const [testOrderPayment, setTestOrderPayment] = useState('KHQR'); // 'KHQR' | 'COD'
  const [testOrderSuccess, setTestOrderSuccess] = useState(false);

  // ⭐️ States សម្រាប់ Bulk Import Excel / CSV ⭐️
  const [bulkImportModalOpen, setBulkImportModalOpen] = useState(false);
  const [bulkImportFile, setBulkImportFile] = useState(null);
  const [bulkParsedRows, setBulkParsedRows] = useState([]);
  const [bulkImportMode, setBulkImportMode] = useState('upsert'); // 'upsert' | 'insert'
  const [bulkImportLoading, setBulkImportLoading] = useState(false);
  const [bulkImportProgress, setBulkImportProgress] = useState({ current: 0, total: 0, status: '' });
  const [bulkImportResult, setBulkImportResult] = useState(null);
  const bulkFileInputRef = useRef(null);

  // ⭐️ States សម្រាប់ Telegram Notifications ⭐️
  const [telegramTesting, setTelegramTesting] = useState(false);
  const [telegramStatusMsg, setTelegramStatusMsg] = useState('');
  const [paywayStatusMsg, setPaywayStatusMsg] = useState('');

  // រក្សាទុកការកំណត់ហាងទាំងអស់ (Save Store Settings)
  const handleSaveStoreSettings = async (e, sectionType = 'general') => {
    if (e && e.preventDefault) e.preventDefault();
    if (guardDemoAction("កែប្រែការកំណត់ហាង")) return;

    const cleanTg = (storeSettings.telegram || '').replace(/^@/, '').trim();
    let cleanBotUser = (storeSettings.telegramBotUsername || '').replace(/^@/, '').trim();

    // 🤖 ប្រសិនបើមាន Bot Token តែពុំទាន់បានដាក់ Username Bot: Auto-detect ពី Telegram API ស្វ័យប្រវត្តិ
    if (sectionType === 'telegram' && storeSettings.telegramBotToken && !cleanBotUser) {
      try {
        const meRes = await fetch(`https://api.telegram.org/bot${storeSettings.telegramBotToken.trim()}/getMe`);
        const meData = await meRes.json();
        if (meData?.ok && meData?.result?.username) {
          cleanBotUser = meData.result.username;
        }
      } catch (meErr) {
        console.warn('Auto-detect Telegram Bot username failed:', meErr);
      }
    }

    const updatedSettings = {
      ...storeSettings,
      telegram: cleanTg,
      telegramBotUsername: cleanBotUser
    };
    setStoreSettings(updatedSettings);

    // ⭐️ STRICT MULTI-TENANT ISOLATION: រក្សាទុកដាច់ដោយឡែកតាម storeId ហាមជាន់គ្នា ⭐️
    const storeId = activeStore?.id || 'store_default_sabayluk';
    localStorage.setItem(`sabay_store_settings_${storeId}`, JSON.stringify(updatedSettings));
    if (storeId === 'store_default_sabayluk') {
      localStorage.setItem('sabay_store_settings', JSON.stringify(updatedSettings));
    }

    const updatedStores = (registeredStores || []).map(s => {
      if (s.id === storeId) {
        return {
          ...s,
          name: updatedSettings.storeName || s.name,
          phone: updatedSettings.phone || s.phone,
          telegram: cleanTg || s.telegram,
          address: updatedSettings.address || s.address,
          settings: { ...(s.settings || {}), ...updatedSettings }
        };
      }
      return s;
    });
    setRegisteredStores(updatedStores);
    saveLocalStores(updatedStores);

    // Update activeStore state immediately
    const nextActive = {
      ...activeStore,
      name: updatedSettings.storeName || activeStore?.name,
      phone: updatedSettings.phone || activeStore?.phone,
      telegram: cleanTg || activeStore?.telegram,
      address: updatedSettings.address || activeStore?.address,
      settings: { ...(activeStore?.settings || {}), ...updatedSettings }
    };
    setActiveStore(nextActive);
    setActiveStoreState(nextActive);
    
    // Auto-sync ទៅ invoiceSettings
    const updatedInvoice = {
      ...invoiceSettings,
      storeName: updatedSettings.storeName || invoiceSettings.storeName,
      phone: updatedSettings.phone || invoiceSettings.phone,
      telegram: cleanTg || invoiceSettings.telegram,
      address: updatedSettings.address || invoiceSettings.address,
      exchangeRate: Number(updatedSettings.exchangeRate) || 4100,
      policyNote: updatedSettings.policyNote || invoiceSettings.policyNote,
      khqrImageUrl: updatedSettings.khqrImageUrl || invoiceSettings.khqrImageUrl || ''
    };
    setInvoiceSettings(updatedInvoice);
    localStorage.setItem(`sabay_invoice_settings_${storeId}`, JSON.stringify(updatedInvoice));
    if (storeId === 'store_default_sabayluk') {
      localStorage.setItem('sabay_invoice_settings', JSON.stringify(updatedInvoice));
    }
    setExchangeRate(Number(updatedSettings.exchangeRate) || 4100);

    // ⭐️ SYNC TO SUPABASE CLOUD DATABASE (stores table) ⭐️
    try {
      const { error: dbErr } = await supabase
        .from('stores')
        .update({
          name: updatedSettings.storeName || activeStore?.name || 'SABAY LUK',
          phone: updatedSettings.phone || activeStore?.phone || '',
          telegram: cleanTg || activeStore?.telegram || '',
          address: updatedSettings.address || activeStore?.address || '',
          settings: updatedSettings,
          updated_at: new Date().toISOString()
        })
        .eq('id', storeId);

      if (dbErr) {
        console.warn('Supabase store update warning:', dbErr);
      } else {
        console.log('✅ Successfully synced store settings to Supabase for store:', storeId);
      }
    } catch (err) {
      console.warn('Failed to update Supabase stores table:', err);
    }

    // Notify other windows/tabs (e.g. Storefront)
    if (typeof window !== 'undefined') {
      window.dispatchEvent(new Event('storage'));
      window.dispatchEvent(new CustomEvent('sabay_store_changed', { detail: { storeId } }));
    }

    if (sectionType === 'telegram') {
      setTelegramStatusMsg(`✅ បានរក្សាទុកការកំណត់ Telegram Bot សម្រាប់ហាង "${activeStore?.name || 'SABAY LUK'}" ជោគជ័យ!`);
      setTimeout(() => setTelegramStatusMsg(''), 4000);
    } else if (sectionType === 'payway') {
      setPaywayStatusMsg(`✅ បានរក្សាទុក ABA Payway Merchant ID សម្រាប់ហាង "${activeStore?.name || 'SABAY LUK'}" ជោគជ័យ!`);
      setTimeout(() => setPaywayStatusMsg(''), 4000);
    }

    setStoreSettingsSavedMsg('🎉 រក្សាទុកការកំណត់ហាង និងម៉ាកយីហោជោគជ័យ!');
    setTimeout(() => setStoreSettingsSavedMsg(''), 3500);
  };

  // ⭐️ មុខងារប្តូរលេខសម្ងាត់ហាង & បុគ្គលិក (Change Store Admin / Staff Password / PIN) ⭐️
  const handleUpdateStorePassword = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (guardDemoAction("ប្តូរពាក្យសម្ងាត់")) return;

    const storeId = activeStore?.id || 'store_default_sabayluk';
    const isTargetOwner = securityTargetStaffId === 'OWNER';
    const currentOwnerPin = (activeStore?.pin || activeStore?.password || '1234').toString().trim();
    const inputOld = currentStorePasswordInput.trim();
    const inputNew = newStorePasswordInput.trim();
    const inputConfirm = confirmStorePasswordInput.trim();

    // 1. Validation
    if (!inputNew) {
      alert('សូមបញ្ចូលលេខសម្ងាត់ថ្មី!');
      return;
    }
    if (inputNew.length < 4) {
      alert('លេខសម្ងាត់ថ្មីត្រូវមានយ៉ាងហោចណាស់ ៤ ខ្ទង់ឡើងទៅ!');
      return;
    }
    if (inputNew !== inputConfirm) {
      alert('ការបញ្ជាក់លេខសម្ងាត់ថ្មីមិនត្រូវគ្នាទេ! សូមពិនិត្យមើលម្តងទៀត។');
      return;
    }

    // Check old password (if updating owner and not master owner)
    if (isTargetOwner && !isMasterOwner) {
      if (!inputOld) {
        alert('សូមបញ្ចូលលេខសម្ងាត់ចាស់ដើម្បីផ្ទៀងផ្ទាត់សុវត្ថិភាព!');
        return;
      }
      const matchesOld = inputOld === currentOwnerPin || 
                         inputOld === (currentStaff?.pin || '').toString().trim() || 
                         inputOld === (currentStaff?.password || '').toString().trim() ||
                         (activeStore?.settings?.pin && inputOld === activeStore.settings.pin.toString().trim()) ||
                         (activeStore?.settings?.owner_password && inputOld === activeStore.settings.owner_password.toString().trim());
      if (!matchesOld) {
        alert('❌ លេខសម្ងាត់ចាស់មិនត្រឹមត្រូវទេ! សូមព្យាយាមម្តងទៀត។');
        return;
      }
    }

    // ⭐️ UNIQUE PIN VALIDATION: Prevent setting staff PIN identical to owner or another staff ⭐️
    if (!isTargetOwner) {
      if (inputNew === currentOwnerPin) {
        alert(`⚠️ លេខសម្ងាត់ "${inputNew}" នេះជាន់គ្នាជាមួយលេខសម្ងាត់របស់ម្ចាស់ហាង (Admin)!\n\nតាមស្តង់ដារអន្តរជាតិ បុគ្គលិកត្រូវតែមានលេខសម្ងាត់ផ្ទាល់ខ្លួនរៀងៗខ្លួន ដាច់ដោយឡែកពីម្ចាស់ហាង។ សូមជ្រើសរើសលេខផ្សេង (ឧ. 1111, 2222, 3333...)។`);
        return;
      }
      const otherStaff = staffList.find(s => s.id !== securityTargetStaffId && (s.pin === inputNew || s.password === inputNew));
      if (otherStaff) {
        alert(`⚠️ លេខសម្ងាត់ "${inputNew}" នេះត្រូវបានប្រើដោយបុគ្គលិក «${otherStaff.name}» រួចហើយ!\n\nបុគ្គលិកម្នាក់ៗត្រូវតែមានលេខសម្ងាត់រៀងខ្លួន។ សូមជ្រើសរើសលេខផ្សេង។`);
        return;
      }
    } else {
      // If changing owner PIN, make sure it doesn't collide with existing staff PINs
      const collidingStaff = staffList.find(s => s.role !== 'ADMIN' && (s.pin === inputNew || s.password === inputNew));
      if (collidingStaff) {
        alert(`⚠️ លេខសម្ងាត់ "${inputNew}" នេះជាន់គ្នាជាមួយលេខសម្ងាត់របស់បុគ្គលិក «${collidingStaff.name}»!\n\nម្ចាស់ហាងត្រូវតែមានលេខសម្ងាត់ផ្ទាល់ខ្លួនដាច់ដោយឡែកពីបុគ្គលិក។`);
        return;
      }
    }

    setIsUpdatingStorePassword(true);

    try {
      if (isTargetOwner) {
        // 2. Update activeStore object
        const updatedStore = {
          ...activeStore,
          pin: inputNew,
          password: inputNew,
          settings: {
            ...(activeStore?.settings || {}),
            pin: inputNew,
            owner_password: inputNew
          }
        };
        setActiveStore(updatedStore);
        setActiveStoreState(updatedStore);

        // 3. Update registeredStores in state & localStorage
        const allStores = getLocalStores();
        const updatedStoresList = allStores.map(s => s.id === storeId ? {
          ...s,
          pin: inputNew,
          password: inputNew,
          settings: {
            ...(s.settings || {}),
            pin: inputNew,
            owner_password: inputNew
          }
        } : s);
        setRegisteredStores(updatedStoresList);
        saveLocalStores(updatedStoresList);

        // 4. Update Staff List of this store (owner account)
        const currentStoreStaff = getStoreStaffList(activeStore);
        const updatedStaffList = currentStoreStaff.map(stf => {
          if (stf.role === 'ADMIN' || stf.id === 'STAFF-1' || stf.id === `STAFF-${storeId}-OWNER`) {
            return {
              ...stf,
              pin: inputNew,
              password: inputNew
            };
          }
          return stf;
        });
        localStorage.setItem(`sabay_staff_list_${storeId}`, JSON.stringify(updatedStaffList));
        if (storeId === 'store_default_sabayluk') {
          localStorage.setItem('sabay_staff_list', JSON.stringify(updatedStaffList));
        }
        setStaffList(updatedStaffList);
        syncStoreStaffToDatabase(storeId, updatedStaffList);

        // Update current logged-in staff if they are the owner
        if (currentStaff?.role === 'ADMIN' || currentStaff?.id === 'STAFF-1' || currentStaff?.id === `STAFF-${storeId}-OWNER`) {
          const updatedCurrentStaff = { ...currentStaff, pin: inputNew, password: inputNew };
          setCurrentStaff(updatedCurrentStaff);
          localStorage.setItem(`sabay_active_staff_${storeId}`, JSON.stringify(updatedCurrentStaff));
        }

        // 5. Sync to Supabase cloud database (stores table)
        try {
          await supabase
            .from('stores')
            .update({
              pin: inputNew,
              password: inputNew,
              settings: {
                ...(activeStore?.settings || {}),
                pin: inputNew,
                owner_password: inputNew
              },
              updated_at: new Date().toISOString()
            })
            .eq('id', storeId);
        } catch (dbErr) {
          console.warn('Stores table pin update notice:', dbErr);
        }

        setToastNotification(`🎉 បានប្តូរលេខសម្ងាត់ម្ចាស់ហាង "${activeStore?.name || storeSettings.storeName}" ជោគជ័យ!`);
      } else {
        // Update specific staff member's personal PIN
        const currentStoreStaff = getStoreStaffList(activeStore);
        const targetStaffObj = currentStoreStaff.find(s => s.id === securityTargetStaffId);
        const updatedStaffList = currentStoreStaff.map(stf => {
          if (stf.id === securityTargetStaffId) {
            return {
              ...stf,
              pin: inputNew,
              password: inputNew
            };
          }
          return stf;
        });
        localStorage.setItem(`sabay_staff_list_${storeId}`, JSON.stringify(updatedStaffList));
        if (storeId === 'store_default_sabayluk') {
          localStorage.setItem('sabay_staff_list', JSON.stringify(updatedStaffList));
        }
        setStaffList(updatedStaffList);
        syncStoreStaffToDatabase(storeId, updatedStaffList);

        if (currentStaff?.id === securityTargetStaffId) {
          const updatedCurrentStaff = { ...currentStaff, pin: inputNew, password: inputNew };
          setCurrentStaff(updatedCurrentStaff);
          localStorage.setItem(`sabay_active_staff_${storeId}`, JSON.stringify(updatedCurrentStaff));
        }

        setToastNotification(`🎉 បានប្តូរលេខសម្ងាត់ PIN ផ្ទាល់ខ្លួនរបស់បុគ្គលិក "${targetStaffObj?.name || 'បុគ្គលិក'}" ជោគជ័យ!`);
      }

      // Clear input fields
      setCurrentStorePasswordInput('');
      setNewStorePasswordInput('');
      setConfirmStorePasswordInput('');

      setTimeout(() => setToastNotification(null), 5000);
    } catch (err) {
      alert('មានបញ្ហាក្នុងការប្តូរលេខសម្ងាត់: ' + err.message);
    } finally {
      setIsUpdatingStorePassword(false);
    }
  };

  // Upload Logo
  const handleLogoUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const dataUrl = await compressImageToDataUrl(file, 'logo');
      if (dataUrl) {
        setStoreSettings(prev => ({ ...prev, logoUrl: dataUrl }));
        setInvoiceSettings(prev => ({ ...prev, logoUrl: dataUrl }));
      }
    } catch (err) {
      alert('❌ បរាជ័យក្នុងការ Upload Logo: ' + err.message);
    }
  };

  // Upload KHQR Code Image
  
  // ⭐️ State & Handlers សម្រាប់ Reset Demo Data & នាំចេញ Excel/CSV ⭐️
  const [resetModalOpen, setResetModalOpen] = useState(false);
  const [resetActionType, setResetActionType] = useState('all'); // 'all' | 'orders' | 'movements' | 'customers' | 'products'
  const [resetConfirmText, setResetConfirmText] = useState('');
  const [resetPasswordInput, setResetPasswordInput] = useState('');
  const [showResetPassword, setShowResetPassword] = useState(false);
  const [resetErrorMsg, setResetErrorMsg] = useState('');
  const [isResetting, setIsResetting] = useState(false);

  // Preset ពណ៌សម្រាប់ Brand Theme
  const THEME_PRESETS = [
    { id: 'orange', name: 'Sunset Orange (លំនាំដើម)', hex: '#ff6a00', desc: 'Streetwear, កីឡា, ថាមពល' },
    { id: 'blue', name: 'Royal Blue (ខៀវ)', hex: '#2563eb', desc: 'ទូទៅ, បច្ចេកវិទ្យា, ស្បែកជើង' },
    { id: 'purple', name: 'Luxury Purple (ស្វាយ)', hex: '#7c3aed', desc: 'Boutique, សំលៀកបំពាក់, អលង្ការ' },
    { id: 'emerald', name: 'Fresh Emerald (បៃតង)', hex: '#059669', desc: 'ធម្មជាតិ, គ្រឿងសម្អាង, Skincare' },
    { id: 'rose', name: 'Crimson Rose (ផ្កាឈូក/ក្រហម)', hex: '#e11d48', desc: 'យុវវ័យ, នារី, Trend ថ្មីៗ' },
    { id: 'dark', name: 'Dark Luxury (ខ្មៅ)', hex: '#0f172a', desc: 'Minimalist, ថ្លៃថ្នូរ, Luxury' }
  ];

  // ⭐️ មុខងារប្តូរពណ៌ Brand Theme ផ្ទាល់ភ្លាមៗ (Instant Auto-Save & Broadcast Scoped per Store) ⭐️
  const handleApplyThemeColor = (colorHex, presetId = 'custom') => {
    const updated = {
      ...storeSettings,
      themeColor: colorHex,
      themePreset: presetId
    };
    setStoreSettings(updated);
    if (typeof window !== 'undefined') {
      const storeId = activeStore?.id || 'store_default_sabayluk';
      localStorage.setItem(`sabay_store_settings_${storeId}`, JSON.stringify(updated));
      if (storeId === 'store_default_sabayluk') {
        localStorage.setItem('sabay_store_settings', JSON.stringify(updated));
      }
      document.documentElement.style.setProperty('--brand-primary', colorHex);
      window.dispatchEvent(new Event('storage'));
    }
    const matched = THEME_PRESETS.find(p => p.hex.toLowerCase() === colorHex.toLowerCase());
    setStoreSettingsSavedMsg(`🎉 បានប្តូរពណ៌ Theme ទៅជា «${matched ? matched.name : colorHex}» រួចរាល់!`);
    setTimeout(() => setStoreSettingsSavedMsg(''), 3500);
  };

  // Sync brand theme on mount
  useEffect(() => {
    if (typeof window !== 'undefined') {
      const storeId = activeStore?.id || 'store_default_sabayluk';
      const saved = localStorage.getItem(`sabay_store_settings_${storeId}`) || (storeId === 'store_default_sabayluk' ? localStorage.getItem('sabay_store_settings') : null);
      if (saved) {
        try {
          const parsed = JSON.parse(saved);
          if (parsed.themeColor) {
            document.documentElement.style.setProperty('--brand-primary', parsed.themeColor);
          }
        } catch (e) {}
      }
    }
  }, [activeStore?.id]);

  // ⭐️ មុខងារទាញយកទិន្នន័យស្តុកជា Excel/CSV (Inventory Export) ⭐️
  const exportInventoryToCSV = () => {
    if (products.length === 0) {
      alert('មិនមានទិន្នន័យទំនិញសម្រាប់នាំចេញទេ!');
      return;
    }
    const headers = [
      'ID', 'ឈ្មោះទំនិញ', 'បាកូដ_SKU', 'ប្រភេទ_Category', 'តម្លៃដើមទុន_Cost($)',
      'តម្លៃលក់រាយ_Price($)', 'បញ្ចុះតម្លៃរាយ($)', 'តម្លៃបោះដុំ_Wholesale($)', 'បញ្ចុះតម្លៃដុំ($)',
      'ស្តុកសរុប_Stock', 'កម្រិតស្តុកទាប_Alert', 'ស្ថានភាព_Status'
    ];
    const rows = products.map(p => [
      `"${p.id}"`,
      `"${(p.name || '').replace(/"/g, '""')}"`,
      `"${(p.sku || '').replace(/"/g, '""')}"`,
      `"${(p.category || '').replace(/"/g, '""')}"`,
      `"${parseFloat(p.cost_price || 0).toFixed(2)}"`,
      `"${parseFloat(p.price || 0).toFixed(2)}"`,
      `"${parseFloat(p.retail_discount || 0).toFixed(2)}"`,
      `"${parseFloat(p.wholesale_price || 0).toFixed(2)}"`,
      `"${parseFloat(p.wholesale_discount || 0).toFixed(2)}"`,
      `"${p.stock_qty || 0}"`,
      `"${p.low_stock_alert || 5}"`,
      `"${p.stock_qty <= 0 ? 'អស់ស្តុក' : p.stock_qty <= (p.low_stock_alert || 5) ? 'ស្តុកជិតអស់' : 'មានក្នុងស្តុក'}"`
    ].join(','));

    const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `Inventory_${(storeSettings.storeName || 'Store').replace(/\s+/g, '_')}_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // ⭐️ Helper: បំប្លែងជួរដេក Excel / CSV ទៅជា Product Object ⭐️
  const mapRowToProduct = (row, index) => {
    const getVal = (...keys) => {
      for (const k of keys) {
        const found = Object.keys(row).find(rk => rk.trim().toLowerCase() === k.toLowerCase());
        if (found && row[found] !== undefined && row[found] !== null && String(row[found]).trim() !== '') {
          return row[found];
        }
      }
      return '';
    };

    const name = String(getVal('ឈ្មោះទំនិញ', 'ឈ្មោះ', 'name', 'product_name', 'title')).trim();
    let sku = String(getVal('បាកូដ_sku', 'បាកូដ', 'sku', 'barcode', 'code')).trim();
    if (!sku) {
      sku = `SL-${Date.now().toString().slice(-4)}${index + 1}`;
    }

    const category = String(getVal('ប្រភេទ_category', 'ប្រភេទ', 'category', 'category_name')).trim() || 'ទូទៅ';
    const cost_price = parseFloat(getVal('តម្លៃដើមទុន_cost($)', 'តម្លៃដើមទុន', 'cost', 'cost_price', 'cost_price($)')) || 0;
    const price = parseFloat(getVal('តម្លៃលក់រាយ_price($)', 'តម្លៃលក់រាយ', 'តម្លៃលក់', 'price', 'selling_price', 'price($)')) || 0;
    const retail_discount = parseFloat(getVal('បញ្ចុះតម្លៃរាយ($)', 'បញ្ចុះតម្លៃរាយ', 'retail_discount', 'discount')) || 0;
    const wholesale_price = parseFloat(getVal('តម្លៃបោះដុំ_wholesale($)', 'តម្លៃបោះដុំ', 'តម្លៃដុំ', 'wholesale_price', 'wholesale($)')) || 0;
    const wholesale_discount = parseFloat(getVal('បញ្ចុះតម្លៃដុំ($)', 'បញ្ចុះតម្លៃដុំ', 'wholesale_discount')) || 0;
    const stock_qty = parseInt(getVal('ស្តុកសរុប_stock', 'ស្តុក', 'ស្តុកសរុប', 'stock', 'stock_qty', 'qty', 'quantity'), 10) || 0;
    const low_stock_alert = parseInt(getVal('កម្រិតស្តុកទាប_alert', 'កម្រិតស្តុកទាប', 'low_stock_alert', 'alert', 'min_stock'), 10) || 5;
    const size = String(getVal('ទំហំ', 'size', 'size_name')).trim() || 'N/A';
    const color = String(getVal('ពណ៌', 'color', 'color_name')).trim() || 'N/A';
    const image_url = String(getVal('រូបភាព', 'image', 'image_url', 'photo')).trim() || '';

    return {
      name,
      sku,
      category,
      cost_price,
      price,
      retail_discount,
      wholesale_price,
      wholesale_discount,
      stock_qty,
      low_stock_alert,
      size,
      color,
      image_url,
      isValid: !!name
    };
  };

  // ⭐️ មុខងារទាញយកទិន្នន័យស្តុកជា Excel (.xlsx) ⭐️
  const exportInventoryToExcel = async () => {
    if (products.length === 0) {
      alert('មិនមានទិន្នន័យទំនិញសម្រាប់នាំចេញទេ!');
      return;
    }
    const headers = [
      'ID', 'ឈ្មោះទំនិញ', 'បាកូដ_SKU', 'ប្រភេទ_Category', 'តម្លៃដើមទុន_Cost($)',
      'តម្លៃលក់រាយ_Price($)', 'បញ្ចុះតម្លៃរាយ($)', 'តម្លៃបោះដុំ_Wholesale($)', 'បញ្ចុះតម្លៃដុំ($)',
      'ស្តុកសរុប_Stock', 'កម្រិតស្តុកទាប_Alert', 'ស្ថានភាព_Status'
    ];
    const data = [
      headers,
      ...products.map(p => [
        p.id,
        p.name || '',
        p.sku || '',
        p.category || '',
        parseFloat(p.cost_price || 0),
        parseFloat(p.price || 0),
        parseFloat(p.retail_discount || 0),
        parseFloat(p.wholesale_price || 0),
        parseFloat(p.wholesale_discount || 0),
        parseInt(p.stock_qty || 0),
        parseInt(p.low_stock_alert || 5),
        p.stock_qty <= 0 ? 'អស់ស្តុក' : p.stock_qty <= (p.low_stock_alert || 5) ? 'ស្តុកជិតអស់' : 'មានក្នុងស្តុក'
      ])
    ];

    const wsData = [headers, ...rows];
    const XLSX = await getXlsx();
    const ws = XLSX.utils.aoa_to_sheet(wsData);
    ws['!cols'] = [
      { wch: 10 }, { wch: 32 }, { wch: 16 }, { wch: 18 }, { wch: 16 },
      { wch: 16 }, { wch: 16 }, { wch: 18 }, { wch: 16 }, { wch: 14 },
      { wch: 16 }, { wch: 16 }
    ];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Inventory');
    const storeNameClean = (storeSettings.storeName || 'Store').replace(/\s+/g, '_');
    XLSX.writeFile(wb, `Inventory_${storeNameClean}_${new Date().toISOString().slice(0, 10)}.xlsx`);
  };

  // ⭐️ មុខងារទាញយកគំរូ Excel សម្រាប់បំពេញទិន្នន័យ (Sample Excel Template) ⭐️
  const downloadInventoryTemplate = async () => {
    const headers = [
      'ឈ្មោះទំនិញ (Name)*',
      'បាកូដ_SKU (Barcode)',
      'ប្រភេទ_Category',
      'តម្លៃដើមទុន_Cost($)',
      'តម្លៃលក់រាយ_Price($)*',
      'បញ្ចុះតម្លៃរាយ($)',
      'តម្លៃបោះដុំ_Wholesale($)',
      'បញ្ចុះតម្លៃដុំ($)',
      'ស្តុកសរុប_Stock*',
      'កម្រិតស្តុកទាប_Alert',
      'ទំហំ_Size',
      'ពណ៌_Color',
      'រូបភាព_Image_URL'
    ];
    const sampleRows = [
      ['ស្បែកជើងប៉ាតា Nike Air Force 1', 'NK-1001', 'ស្បែកជើង', 25.00, 45.00, 5.00, 35.00, 0, 50, 5, '40, 41, 42, 43', 'White', 'https://images.unsplash.com/photo-1542291026-7eec264c27ff'],
      ['អាវយឺតដៃខ្លី Oversize Premium', 'TS-2002', 'សម្លៀកបំពាក់', 5.50, 12.00, 0, 8.50, 0, 40, 5, 'M, L, XL', 'Black', ''],
      ['កាបូបស្ពាយស្បែកបុរស Luxury', 'BG-3003', 'កាបូប', 14.00, 28.00, 3.00, 20.00, 0, 15, 3, 'Free Size', 'Brown', '']
    ];

    const XLSX = await getXlsx();
    const ws = XLSX.utils.aoa_to_sheet([headers, ...sampleRows]);
    ws['!cols'] = [
      { wch: 32 }, { wch: 18 }, { wch: 18 }, { wch: 16 }, { wch: 18 },
      { wch: 16 }, { wch: 20 }, { wch: 16 }, { wch: 16 }, { wch: 18 },
      { wch: 16 }, { wch: 14 }, { wch: 30 }
    ];
    const wb = XLSX.utils.book_new();
    XLSX.utils.book_append_sheet(wb, ws, 'Template');
    XLSX.writeFile(wb, `Template_Inventory_Import_${(storeSettings.storeName || 'Store').replace(/\s+/g, '_')}.xlsx`);
  };

  // ⭐️ មុខងារជ្រើសរើស និងអានឯកសារ Excel / CSV (File Reader) ⭐️
  const handleBulkExcelFileChange = (e) => {
    const file = e.target.files && e.target.files[0];
    if (!file) return;

    const reader = new FileReader();
    reader.onload = async (evt) => {
      try {
        const XLSX = await getXlsx();
        const data = new Uint8Array(evt.target.result);
        const workbook = XLSX.read(data, { type: 'array' });
        const firstSheetName = workbook.SheetNames[0];
        const worksheet = workbook.Sheets[firstSheetName];
        const rawRows = XLSX.utils.sheet_to_json(worksheet, { defval: '' });

        if (!rawRows || rawRows.length === 0) {
          alert('❌ ឯកសារនេះមិនមានទិន្នន័យទេ! សូមពិនិត្យមើលឯកសារឡើងវិញ។');
          return;
        }

        const parsed = rawRows.map((r, idx) => mapRowToProduct(r, idx)).filter(r => r.name);
        if (parsed.length === 0) {
          alert('❌ មិនអាចស្វែងរកឈ្មោះទំនិញ (Name) ក្នុងជួរឈរណាមួយឡើយ! សូមប្រាកដថាមានជួរឈរ "ឈ្មោះទំនិញ" ឬ "Name"។');
          return;
        }

        setBulkImportFile(file);
        setBulkParsedRows(parsed);
        setBulkImportResult(null);
        setBulkImportModalOpen(true);
      } catch (err) {
        console.error('Error reading excel/csv file:', err);
        alert('❌ បរាជ័យក្នុងការអានឯកសារ Excel/CSV: ' + err.message);
      }
    };
    reader.readAsArrayBuffer(file);
    e.target.value = '';
  };

  // ⭐️ មុខងារដំណើរការ Bulk Import ចូល Supabase Database ⭐️
  const handleExecuteBulkImport = async () => {
    if (!bulkParsedRows || bulkParsedRows.length === 0) return;
    setBulkImportLoading(true);
    setBulkImportProgress({ current: 0, total: bulkParsedRows.length, status: 'កំពុងចាប់ផ្តើម...' });

    let inserted = 0;
    let updated = 0;
    let failed = 0;
    const errors = [];
    const lowStockItems = [];

    // បង្កើត Categories ថ្មីបើមិនទាន់មានក្នុង Database
    const existingCatNames = categories.map(c => (c.name || '').trim().toLowerCase());
    const newCatsToCreate = new Set();
    bulkParsedRows.forEach(item => {
      const cat = (item.category || '').trim();
      if (cat && !existingCatNames.includes(cat.toLowerCase())) {
        newCatsToCreate.add(cat);
      }
    });

    if (newCatsToCreate.size > 0) {
      try {
        const catPayload = Array.from(newCatsToCreate).map(c => ({ name: c, store_id: activeStore?.id || 'store_default_sabayluk' }));
        await supabase.from('categories').insert(catPayload);
        fetchCategories();
      } catch (e) {
        console.error('Error creating categories:', e);
      }
    }

    for (let i = 0; i < bulkParsedRows.length; i++) {
      const item = bulkParsedRows[i];
      setBulkImportProgress({
        current: i + 1,
        total: bulkParsedRows.length,
        status: `កំពុងបញ្ចូល: ${item.name} (${i + 1}/${bulkParsedRows.length})`
      });

      try {
        const existingProd = bulkImportMode === 'upsert'
          ? products.find(p => p.sku && p.sku.toLowerCase() === item.sku.toLowerCase())
          : null;

        const metaJson = JSON.stringify({
          images: item.image_url ? [item.image_url] : [],
          retail_discount: item.retail_discount || 0,
          wholesale_discount: item.wholesale_discount || 0
        });

        const productPayload = {
          store_id: activeStore?.id || 'store_default_sabayluk',
          name: item.name,
          sku: item.sku,
          category: item.category || 'ទូទៅ',
          category_name: metaJson,
          size: item.size || 'N/A',
          color: item.color || 'N/A',
          stock_qty: item.stock_qty || 0,
          cost_price: item.cost_price || 0,
          wholesale_price: item.wholesale_price || 0,
          wholesale_discount: item.wholesale_discount || 0,
          price: item.price || 0,
          retail_discount: item.retail_discount || 0,
          low_stock_alert: item.low_stock_alert || 5,
          image_url: item.image_url || '',
          images: item.image_url ? [item.image_url] : [],
          status: item.stock_qty > 0 ? 'In Stock' : 'Out of Stock'
        };

        if (existingProd) {
          // ធ្វើបច្ចុប្បន្នភាពទំនិញចាស់
          let { error: upErr } = await supabase
            .from('products')
            .update(productPayload)
            .eq('id', existingProd.id);

          if (upErr && (upErr.message?.includes('wholesale_price') || upErr.message?.includes('images') || upErr.code === 'PGRST204')) {
            delete productPayload.wholesale_price;
            delete productPayload.retail_discount;
            delete productPayload.wholesale_discount;
            delete productPayload.images;
            const retry = await supabase.from('products').update(productPayload).eq('id', existingProd.id);
            upErr = retry.error;
          }

          if (upErr) throw upErr;

          // កត់ត្រាប្រវត្តិចលនាស្តុក បើស្តុកមានការប្រែប្រួល
          if (item.stock_qty !== existingProd.stock_qty) {
            await supabase.from('stock_movements').insert([{
              product_id: existingProd.id,
              type: 'ADJUST',
              qty_change: item.stock_qty - (existingProd.stock_qty || 0),
              previous_qty: existingProd.stock_qty || 0,
              new_qty: item.stock_qty,
              reason: 'នាំចូលស្តុកតាម Excel/CSV (Bulk Import Update)'
            }]);
          }

          updated++;
        } else {
          // បញ្ចូលជាទំនិញថ្មី
          let insertData = { ...productPayload };
          let { data: newProd, error: inErr } = await supabase
            .from('products')
            .insert([insertData])
            .select()
            .single();

          if (inErr && (inErr.message?.includes('wholesale_price') || inErr.message?.includes('images') || inErr.code === 'PGRST204')) {
            delete insertData.wholesale_price;
            delete insertData.retail_discount;
            delete insertData.wholesale_discount;
            delete insertData.images;
            const retry = await supabase.from('products').insert([insertData]).select().single();
            newProd = retry.data;
            inErr = retry.error;
          }

          if (inErr) throw inErr;

          if (newProd && item.stock_qty > 0) {
            await supabase.from('stock_movements').insert([{
              product_id: newProd.id,
              type: 'IN',
              qty_change: item.stock_qty,
              previous_qty: 0,
              new_qty: item.stock_qty,
              reason: 'នាំចូលស្តុកទំនិញថ្មីតាម Excel/CSV (Bulk Import New)'
            }]);
          }

          inserted++;
        }

        // ត្រួតពិនិត្យស្តុកទាប
        if (item.stock_qty <= (item.low_stock_alert || storeSettings.lowStockThreshold || 5)) {
          lowStockItems.push(item);
        }
      } catch (err) {
        console.error('Error importing product:', item.name, err);
        failed++;
        errors.push(`${item.name}: ${err.message || 'Error'}`);
      }
    }

    setBulkImportLoading(false);
    setBulkImportResult({ inserted, updated, failed, errors });
    fetchProducts();

    // ជូនដំណឹងតាម Telegram បើមានទំនិញទើបនាំចូលសល់ស្តុកតិច
    if (lowStockItems.length > 0 && storeSettings.enableLowStockAlert && storeSettings.telegramBotToken && storeSettings.telegramChatId) {
      sendTelegramNotification({ action: 'low_stock', items: lowStockItems });
    }
  };

  // ⭐️ មុខងារផ្ញើសារតាម Telegram (Telegram Notification Dispatcher) ⭐️
  const sendTelegramNotification = async ({ action, items, message, stockData, order }) => {
    const token = storeSettings.telegramBotToken || activeStore?.settings?.telegramBotToken || '';
    const chat = storeSettings.telegramChatId || activeStore?.settings?.telegramChatId || '';

    try {
      const res = await fetch('/api/telegram', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          botToken: token || undefined,
          chatId: chat || undefined,
          storeId: activeStore?.id || 'store_default_sabayluk',
          storeSlug: activeStore?.slug || 'sabay-luk',
          storeName: storeSettings.storeName || activeStore?.name || 'SABAY LUK',
          storePhone: storeSettings.phone || activeStore?.phone || '096 720 5522',
          storeAddress: storeSettings.address || activeStore?.address || '',
          storeTelegram: (() => {
            const raw = (storeSettings.telegram || activeStore?.telegram || 'sabay_luk').replace(/^@/, '').trim();
            return raw.toLowerCase() === 'sabayluk' ? 'sabay_luk' : raw;
          })(),
          action,
          items,
          message,
          stockData,
          order
        })
      });

      const data = await res.json();
      return data;
    } catch (err) {
      console.error('Error sending telegram alert:', err);
      return { success: false, message: err.message };
    }
  };

  // ⭐️ មុខងារតេស្តការតភ្ជាប់ Telegram Bot (Test Telegram Connection) ⭐️
  const handleTestTelegramAlert = async () => {
    setTelegramTesting(true);
    setTelegramStatusMsg('កំពុងសាកល្បងផ្ញើសារទៅកាន់ Telegram...');

    // Auto-detect Telegram Bot Username ពេល test
    if (storeSettings.telegramBotToken && !storeSettings.telegramBotUsername) {
      try {
        const meRes = await fetch(`https://api.telegram.org/bot${storeSettings.telegramBotToken.trim()}/getMe`);
        const meData = await meRes.json();
        if (meData?.ok && meData?.result?.username) {
          const detectedUsername = meData.result.username;
          setStoreSettings(prev => ({ ...prev, telegramBotUsername: detectedUsername }));
          updateStoreSettingsImmediate({ telegramBotUsername: detectedUsername });
        }
      } catch (_) {}
    }

    const res = await sendTelegramNotification({ action: 'test' });
    setTelegramTesting(false);
    if (res.success) {
      setTelegramStatusMsg('✅ បានផ្ញើសារសាកល្បងទៅ Telegram ជោគជ័យ! សូមបើកមើលក្នុង Telegram។');
      alert('✅ បានផ្ញើសារសាកល្បងទៅ Telegram ជោគជ័យ! សូមបើក Telegram មើលសារ។');
    } else {
      setTelegramStatusMsg('❌ បរាជ័យក្នុងការផ្ញើសារ: ' + (res.message || 'សូមពិនិត្យមើល Token & Chat ID'));
      alert('❌ បរាជ័យក្នុងការផ្ញើសារ Telegram: ' + (res.message || 'សូមពិនិត្យមើល Token & Chat ID'));
    }
    setTimeout(() => setTelegramStatusMsg(''), 5000);
  };

  // ⭐️ មុខងារត្រួតពិនិត្យ និងផ្ញើ Telegram Low Stock Alert ដោយផ្ទាល់ដៃ (Manual Trigger) ⭐️
  const handleManualStockAlertCheck = async () => {
    const threshold = parseInt(storeSettings.lowStockThreshold, 10) || 5;
    const lowItems = products.filter(p => p.stock_qty <= (p.low_stock_alert || threshold));

    if (lowItems.length === 0) {
      alert(`🎉 អបអរសាទរ! មិនមានទំនិញណាមួយសល់ក្រោម ឬស្មើ ${threshold} ឬអស់ពីស្តុកឡើយ!`);
      return;
    }

    if (!storeSettings.telegramBotToken || !storeSettings.telegramChatId) {
      alert(`⚠️ រកឃើញទំនិញជិតអស់/អស់ស្តុកចំនួន ${lowItems.length} មុខ!\n\nដើម្បីទទួលបានសារស្វ័យប្រវត្តិតាម Telegram សូមកំណត់ Telegram Bot Token និង Chat ID ក្នុង Tab "🔌 API & Integrations"។`);
      setActiveTab('api');
      return;
    }

    if (confirm(`🚨 រកឃើញទំនិញជិតអស់/អស់ស្តុកចំនួន ${lowItems.length} មុខ!\n\nតើបងចង់ផ្ញើរបាយការណ៍សង្ខេបនេះទៅកាន់ Telegram ឥឡូវនេះដែរឬទេ?`)) {
      setTelegramTesting(true);
      const res = await sendTelegramNotification({ action: 'low_stock', items: lowItems });
      setTelegramTesting(false);
      if (res.success) {
        alert(`✅ បានផ្ញើរបាយការណ៍ស្តុកទាបចំនួន ${lowItems.length} មុខ ទៅ Telegram ជោគជ័យ!`);
      } else {
        alert('❌ បរាជ័យក្នុងការផ្ញើសារ: ' + res.message);
      }
    }
  };

  // ⭐️ មុខងារទាញយកកំណត់ត្រាចលនាស្តុកជា Excel/CSV (Stock Movements Export) ⭐️
  const exportStockMovementsToCSV = () => {
    if (stockMovements.length === 0) {
      alert('មិនមានទិន្នន័យចលនាស្តុកសម្រាប់នាំចេញទេ!');
      return;
    }
    const headers = [
      'កាលបរិច្ឆេទ', 'ម៉ោង', 'ឈ្មោះទំនិញ', 'SKU', 'ទំហំ_ពណ៌',
      'ប្រភេទចលនា', 'ចំនួនប្រែប្រួល', 'ស្តុកមុន', 'ស្តុកក្រោយ', 'មូលហេតុ'
    ];
    const rows = stockMovements.map(m => {
      const p = m.products || {};
      const v = m.product_variants || {};
      const d = m.created_at ? new Date(m.created_at) : new Date();
      const dateStr = d.toLocaleDateString();
      const timeStr = d.toLocaleTimeString();
      const variantStr = [v.size, v.color].filter(Boolean).join(' / ') || 'ទូទៅ';
      const typeLabel = m.type === 'PURCHASE' ? 'នាំចូល (Purchase)' : m.type === 'SALE' ? 'លក់ចេញ (Sale)' : 'កាត់ស្តុក (Adjustment)';
      const qtyChange = m.qty_change > 0 ? `+${m.qty_change}` : `${m.qty_change}`;

      return [
        `"${dateStr}"`,
        `"${timeStr}"`,
        `"${(p.name || '').replace(/"/g, '""')}"`,
        `"${(p.sku || '').replace(/"/g, '""')}"`,
        `"${variantStr.replace(/"/g, '""')}"`,
        `"${typeLabel}"`,
        `"${qtyChange}"`,
        `"${m.previous_qty || 0}"`,
        `"${m.new_qty || 0}"`,
        `"${(m.reason || '').replace(/"/g, '""')}"`
      ].join(',');
    });

    const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `Stock_Movements_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // ⭐️ មុខងារទាញយកបញ្ជីលក់ជា Excel/CSV (Orders Export) ⭐️
  const exportOrdersToCSV = () => {
    if (realOrders.length === 0) {
      alert('មិនមានទិន្នន័យការលក់សម្រាប់នាំចេញទេ!');
      return;
    }
    const headers = [
      'លេខវិក្កយបត្រ', 'កាលបរិច្ឆេទ', 'ឈ្មោះអតិថិជន', 'លេខទូរស័ព្ទ', 'ប្រភេទការលក់',
      'សរុបទឹកប្រាក់($)', 'បញ្ចុះតម្លៃ($)', 'វិធីសាស្ត្រទូទាត់', 'ស្ថានភាព', 'ចំនួនមុខទំនិញ'
    ];
    const rows = realOrders.map(o => {
      const itemsCount = Array.isArray(o.items) ? o.items.reduce((s, it) => s + (it.qty || 1), 0) : 1;
      return [
        `"${o.order_id || o.id}"`,
        `"${o.created_at ? new Date(o.created_at).toLocaleDateString() : ''}"`,
        `"${(o.customer_name || o.customer || 'អតិថិជនទូទៅ').replace(/"/g, '""')}"`,
        `"${(o.phone || o.phone_number || '').replace(/"/g, '""')}"`,
        `"${o.order_type || 'Storefront'}"`,
        `"${parseFloat(o.total_amount || 0).toFixed(2)}"`,
        `"${parseFloat(o.discount || 0).toFixed(2)}"`,
        `"${(o.payment_method || 'Cash').replace(/"/g, '""')}"`,
        `"${o.status || 'Completed'}"`,
        `"${itemsCount}"`
      ].join(',');
    });

    const csvContent = '\uFEFF' + [headers.join(','), ...rows].join('\n');
    const blob = new Blob([csvContent], { type: 'text/csv;charset=utf-8;' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.setAttribute('download', `Orders_Sales_${new Date().toISOString().slice(0, 10)}.csv`);
    document.body.appendChild(link);
    link.click();
    document.body.removeChild(link);
  };

  // ⭐️ មុខងារ Reset / សម្អាតទិន្នន័យតេស្តហាង (មានសុវត្ថិភាពខ្ពស់ ផ្ទៀងផ្ទាត់ Password ម្ចាស់ហាង និងបែងចែកទិន្នន័យដាច់ដោយឡែក ១០០%) ⭐️
  const handleExecuteReset = async () => {
    setResetErrorMsg('');

    // 1. ពិនិត្យលេខសម្ងាត់ម្ចាស់ហាង (Verify Store Owner Credentials)
    const inputPass = resetPasswordInput.trim();
    if (!inputPass) {
      setResetErrorMsg('សូមបញ្ចូលលេខសម្ងាត់ ឬ PIN របស់ម្ចាស់ហាងដើម្បីផ្ទៀងផ្ទាត់សុវត្ថិភាព!');
      return;
    }

    const storePin = (activeStore?.pin || activeStore?.password || '1234').toString().trim();
    const storeOwnerPass = (activeStore?.settings?.owner_password || activeStore?.settings?.pin || '').toString().trim();
    const staffPin = (currentStaff?.pin || currentStaff?.password || '').toString().trim();
    const storeStaffList = getStoreStaffList(activeStore);
    const ownerAccount = storeStaffList.find(s => s.role === 'ADMIN' || s.isOwner);
    const ownerAccountPin = (ownerAccount?.pin || ownerAccount?.password || '').toString().trim();

    const isPasswordValid = (
      inputPass === storePin ||
      inputPass === storeOwnerPass ||
      inputPass === staffPin ||
      inputPass === ownerAccountPin ||
      (isMasterOwner && (inputPass === '1234' || inputPass === (masterCredentials?.pin || '1234')))
    );

    if (!isPasswordValid) {
      setResetErrorMsg(`❌ លេខសម្ងាត់ម្ចាស់ហាងមិនត្រឹមត្រូវទេ! សូមបញ្ចូលលេខសម្ងាត់ ឬ PIN របស់ហាង [${activeStore?.name || ''}] របស់អ្នកឱ្យបានត្រឹមត្រូវ។`);
      return;
    }

    // 2. ពិនិត្យអក្សរបញ្ជាក់ពាក្យ RESET
    if (resetConfirmText.trim().toUpperCase() !== 'RESET') {
      setResetErrorMsg('សូមវាយពាក្យ "RESET" ឱ្យបានត្រឹមត្រូវដើម្បីបញ្ជាក់ការលុប!');
      return;
    }

    setIsResetting(true);
    const currentStoreId = activeStore?.id || 'store_default_sabayluk';
    const isFlagship = currentStoreId === 'store_default_sabayluk';

    try {
      // 🛒 ១. សម្អាតការបញ្ជាទិញ (Orders) សម្រាប់តែ Store នេះប៉ុណ្ណោះ (Never delete other stores)
      if (resetActionType === 'orders' || resetActionType === 'all') {
        let ordQuery = supabase.from('orders').select('id');
        if (isFlagship) {
          ordQuery = ordQuery.or(`store_id.eq.${currentStoreId},store_id.is.null`);
        } else {
          ordQuery = ordQuery.eq('store_id', currentStoreId);
        }
        const { data: ords } = await ordQuery;
        if (ords && ords.length > 0) {
          const ids = ords.map(o => o.id);
          await supabase.from('orders').delete().in('id', ids);
        }
        setRealOrders(prev => prev.filter(o => {
          const oStore = o.store_id || 'store_default_sabayluk';
          return oStore !== currentStoreId;
        }));
      }

      // 📋 ២. សម្អាតចលនាស្តុក (Stock Movements) សម្រាប់តែ Store នេះប៉ុណ្ណោះ
      if (resetActionType === 'movements' || resetActionType === 'all') {
        let prodQuery = supabase.from('products').select('id');
        if (isFlagship) {
          prodQuery = prodQuery.or(`store_id.eq.${currentStoreId},store_id.is.null`);
        } else {
          prodQuery = prodQuery.eq('store_id', currentStoreId);
        }
        const { data: prods } = await prodQuery;
        if (prods && prods.length > 0) {
          const prodIds = prods.map(p => p.id);
          await supabase.from('stock_movements').delete().in('product_id', prodIds);
        }
        setStockMovements([]);
      }

      // 👥 ៣. សម្អាតអតិថិជន (Customers) សម្រាប់តែ Store នេះប៉ុណ្ណោះ
      if (resetActionType === 'customers' || resetActionType === 'all') {
        localStorage.removeItem(`sabay_customers_${currentStoreId}`);
        if (isFlagship) {
          localStorage.removeItem('sabay_customers');
        }
        setCustomers([]);
      }

      // 📦 ៤. សម្អាតទំនិញ និង Variant (Products & Variants) សម្រាប់តែ Store នេះប៉ុណ្ណោះ
      if (resetActionType === 'products' || resetActionType === 'all') {
        let prodQuery = supabase.from('products').select('id');
        if (isFlagship) {
          prodQuery = prodQuery.or(`store_id.eq.${currentStoreId},store_id.is.null`);
        } else {
          prodQuery = prodQuery.eq('store_id', currentStoreId);
        }
        const { data: prods } = await prodQuery;
        if (prods && prods.length > 0) {
          const prodIds = prods.map(p => p.id);
          await supabase.from('product_variants').delete().in('product_id', prodIds);
          await supabase.from('stock_movements').delete().in('product_id', prodIds);
          await supabase.from('products').delete().in('id', prodIds);
        }
        setProducts(prev => prev.filter(p => {
          const pStore = p.store_id || 'store_default_sabayluk';
          return pStore !== currentStoreId;
        }));
      }

      // 🧹 ៥. សម្អាត POS Cart, Hold Orders & ចំណាយ Expenses សម្រាប់តែ Store នេះប៉ុណ្ណោះ
      if (resetActionType === 'all') {
        localStorage.removeItem(`sabay_pos_cart_${currentStoreId}`);
        localStorage.removeItem(`sabay_pos_hold_orders_${currentStoreId}`);
        localStorage.removeItem(`sabay_expenses_${currentStoreId}`);
        if (isFlagship) {
          localStorage.removeItem('sabay_pos_cart');
          localStorage.removeItem('sabay_pos_hold_orders');
          localStorage.removeItem('sabay_expenses');
          localStorage.removeItem('sabay_luk_expenses');
        }
        setPosCart([]);
        setHoldOrders([]);
        setExpenses([]);
      }

      // ទាញទិន្នន័យថ្មីសម្រាប់ Store នេះ
      if (fetchProducts) await fetchProducts(currentStoreId);
      if (fetchRealOrders) await fetchRealOrders(currentStoreId);
      if (fetchStockMovements) await fetchStockMovements(currentStoreId);

      setResetModalOpen(false);
      setResetConfirmText('');
      setResetPasswordInput('');
      setResetErrorMsg('');
      alert(`🎉 សម្អាតទិន្នន័យសម្រាប់ហាង [${activeStore?.name || 'Sabay Luk'}] បានជោគជ័យ ១០០%! ទិន្នន័យហាងដទៃទៀតត្រូវបានការពារមិនឱ្យប៉ះពាល់ឡើយ។`);
    } catch (err) {
      console.error('Reset error:', err);
      setResetErrorMsg('❌ មានបញ្ហាក្នុងការសម្អាតទិន្នន័យ: ' + err.message);
    } finally {
      setIsResetting(false);
    }
  };

  const handleKhqrUpload = async (e) => {
    const file = e.target.files?.[0];
    if (!file) return;
    try {
      const dataUrl = await compressImageToDataUrl(file, 'logo');
      if (dataUrl) {
        setStoreSettings(prev => ({ ...prev, khqrImageUrl: dataUrl }));
        setInvoiceSettings(prev => ({ ...prev, khqrImageUrl: dataUrl }));
      }
    } catch (err) {
      alert('❌ បរាជ័យក្នុងការ Upload KHQR: ' + err.message);
    }
  };

  // មុខងារ Save ការកំណត់វិក្កយបត្រ (រួមទាំងពន្ធ VAT និងការកំណត់ហាង - 100% Strict Cloud & Local Isolation)
  const handleSaveInvoiceSettings = async (e) => {
    if (e && e.preventDefault) e.preventDefault();
    if (guardDemoAction("កែប្រែការកំណត់វិក្កយបត្រ")) return;

    const storeId = activeStore?.id || 'store_default_sabayluk';
    const isDefault = storeId === 'store_default_sabayluk' || activeStore?.slug === 'sabay-luk';
    const isTenant = !isDefault;

    // Sanitize logo & QR against leakage
    let safeLogo = storeSettings.logoUrl || invoiceSettings.logoUrl || '';
    if (isTenant && (safeLogo === '/logo.png' || safeLogo.includes('/logo.png'))) safeLogo = '';

    let safeKhqr = storeSettings.khqrImageUrl || invoiceSettings.khqrImageUrl || '';
    if (isTenant && (safeKhqr === '/khqr-aba.jpg' || safeKhqr.includes('khqr-aba.jpg'))) safeKhqr = '';

    const cleanInvoice = {
      ...invoiceSettings,
      storeName: invoiceSettings.storeName || (isTenant ? (activeStore?.name || 'ហាងរបស់ខ្ញុំ') : 'SABAY LUK'),
      phone: invoiceSettings.phone || (isTenant ? (activeStore?.phone || '') : '096 720 5522'),
      address: invoiceSettings.address || (isTenant ? (activeStore?.address || '') : 'Phnom Penh, Cambodia'),
      logoUrl: safeLogo,
      khqrImageUrl: safeKhqr,
      exchangeRate: Number(invoiceSettings.exchangeRate || storeSettings.exchangeRate || 4100)
    };

    const cleanStoreSettings = {
      ...storeSettings,
      storeName: cleanInvoice.storeName,
      phone: cleanInvoice.phone,
      address: cleanInvoice.address,
      logoUrl: safeLogo,
      khqrImageUrl: safeKhqr,
      showInvoiceLogo: storeSettings.showInvoiceLogo !== false && cleanInvoice.showLogo !== false,
      showReceiptQr: storeSettings.showReceiptQr !== false,
      exchangeRate: cleanInvoice.exchangeRate,
      invoice: cleanInvoice
    };

    setInvoiceSettings(cleanInvoice);
    setStoreSettings(cleanStoreSettings);

    localStorage.setItem(`sabay_invoice_settings_${storeId}`, JSON.stringify(cleanInvoice));
    localStorage.setItem(`sabay_store_settings_${storeId}`, JSON.stringify(cleanStoreSettings));
    if (isDefault) {
      localStorage.setItem('sabay_invoice_settings', JSON.stringify(cleanInvoice));
      localStorage.setItem('sabay_store_settings', JSON.stringify(cleanStoreSettings));
    }
    setExchangeRate(cleanInvoice.exchangeRate);

    // Update activeStore in state and localStorage
    const nextActive = {
      ...activeStore,
      name: cleanInvoice.storeName,
      phone: cleanInvoice.phone,
      address: cleanInvoice.address,
      settings: { ...(activeStore?.settings || {}), ...cleanStoreSettings }
    };
    setActiveStore(nextActive);
    setActiveStoreState(nextActive);

    // Update registered stores
    const updatedStores = (registeredStores || []).map(s => {
      if (s.id === storeId) {
        return {
          ...s,
          name: cleanInvoice.storeName,
          phone: cleanInvoice.phone,
          address: cleanInvoice.address,
          settings: { ...(s.settings || {}), ...cleanStoreSettings }
        };
      }
      return s;
    });
    setRegisteredStores(updatedStores);
    saveLocalStores(updatedStores);

    // Sync to Supabase Cloud
    try {
      await supabase
        .from('stores')
        .update({
          name: cleanInvoice.storeName,
          phone: cleanInvoice.phone,
          address: cleanInvoice.address,
          settings: cleanStoreSettings,
          updated_at: new Date().toISOString()
        })
        .eq('id', storeId);
    } catch (err) {
      console.warn('Cloud sync error during invoice settings save:', err);
    }

    if (typeof window !== 'undefined') {
      window.dispatchEvent(new Event('storage'));
      window.dispatchEvent(new CustomEvent('sabay_store_changed', { detail: nextActive }));
    }
    setInvoiceSavedMsg('✅ រក្សាទុកទម្រង់វិក្កយបត្រ Logo និង QR Code ដាច់ដោយឡែកសម្រាប់ហាងនេះជោគជ័យ ១០០%!');
    setTimeout(() => setInvoiceSavedMsg(''), 3500);
  };

  // 🖨️ មុខងារតេស្តព្រីនវិក្កយបត្រសាកល្បង (Test Print Receipt)
  const handleTestPrintInvoice = () => {
    const widthCss = thermalPaperSize === '58mm' ? '54mm' : '76mm';
    const pageCss = thermalPaperSize === '58mm' ? '58mm auto' : '80mm auto';
    const fontSize = thermalPaperSize === '58mm' ? '10px' : '11px';

    const isLogoVisible = (storeSettings.showInvoiceLogo !== false && invoiceSettings.showLogo !== false) && storeSettings.logoUrl;
    const isTaxEnabled = normalizeEnableTax(storeSettings.enableTax);
    const taxRate = storeSettings.taxRate ?? 10;
    const taxMode = storeSettings.taxMode || 'exclusive';
    const taxLabel = storeSettings.taxLabel || `ពន្ធអាករ (VAT ${taxRate}%)`;
    const vatTin = storeSettings.vatTin || invoiceSettings.vatTin || '';

    const sampleSubtotal = 40.00;
    const sampleTax = isTaxEnabled ? (taxMode === 'inclusive' ? (sampleSubtotal * taxRate / (100 + taxRate)) : (sampleSubtotal * taxRate / 100)) : 0;
    const sampleTotal = isTaxEnabled && taxMode === 'exclusive' ? (sampleSubtotal + sampleTax) : sampleSubtotal;
    const sampleExchange = invoiceSettings.exchangeRate || storeSettings.exchangeRate || 4100;
    const sampleTotalKHR = Math.round(sampleTotal * sampleExchange);

    const testContent = `
      <div style="font-family: 'Courier New', Courier, monospace, 'Hanuman', 'Siemreap', sans-serif; width: ${widthCss}; margin: 0 auto; padding: 2.5mm; color: #000; font-size: ${fontSize}; line-height: 1.3;">
        <div style="text-align: center; margin-bottom: 8px;">
          ${isLogoVisible ? `<img src="${storeSettings.logoUrl}" style="height: 38px; max-width: 100%; object-fit: contain; margin: 0 auto 4px auto; filter: grayscale(100%); display: block;" />` : ''}
          <h2 style="font-size: 15px; font-weight: 900; text-transform: uppercase; margin: 0; line-height: 1.1;">${invoiceSettings.storeName || storeSettings.storeName || activeStore?.name || (activeStore?.id !== 'store_default_sabayluk' ? 'ហាងរបស់ខ្ញុំ' : 'SABAY LUK')}</h2>
          ${storeSettings.storeSlogan ? `<p style="font-size: 9px; margin: 2px 0 0 0; color: #555;">${storeSettings.storeSlogan}</p>` : ''}
          <p style="font-size: 9px; margin: 2px 0 0 0;">អាសយដ្ឋាន: ${invoiceSettings.address || storeSettings.address || activeStore?.address || 'ភ្នំពេញ, កម្ពុជា'}</p>
          <p style="font-size: 9px; font-weight: bold; margin: 2px 0 0 0;">ទូរស័ព្ទ: ${invoiceSettings.phone || storeSettings.phone || activeStore?.phone || ''}</p>
          ${vatTin ? `<p style="font-size: 9px; font-family: monospace; font-weight: bold; margin: 2px 0 0 0;">VATTIN: ${vatTin}</p>` : ''}
          <div style="border-bottom: 1px dashed #000; margin: 6px 0;"></div>
          <h3 style="font-size: 11px; font-weight: 900; text-transform: uppercase; margin: 0;">*** វិក្កយបត្រតេស្តព្រីន / TEST RECEIPT ***</h3>
        </div>

        <div style="font-size: 10px; margin-bottom: 6px;">
          <div style="display: flex; justify-content: space-between;"><span>លេខវិក្កយបត្រ:</span><b>ORD-TEST-PRINT</b></div>
          <div style="display: flex; justify-content: space-between;"><span>កាលបរិច្ឆេទ:</span><span>${new Date().toLocaleDateString('km-KH')} ${new Date().toLocaleTimeString()}</span></div>
          <div style="display: flex; justify-content: space-between;"><span>អ្នកគិតប្រាក់:</span><span>${invoiceSettings.cashierName || 'Admin'}</span></div>
          <div style="display: flex; justify-content: space-between;"><span>អតិថិជន:</span><b>អតិថិជនសាកល្បង (Test)</b></div>
        </div>

        <div style="border-bottom: 1px dashed #000; margin: 6px 0;"></div>
        <table style="width: 100%; border-collapse: collapse; font-size: inherit; margin-bottom: 6px;">
          <thead>
            <tr style="border-bottom: 1px dashed #000; font-size: 9px; font-weight: bold;">
              <th style="text-align: left; padding: 2px 0;">មុខទំនិញ (Item)</th>
              <th style="text-align: center; padding: 2px 0; width: 40px;">ចំនួន</th>
              <th style="text-align: right; padding: 2px 0; width: 60px;">តម្លៃសរុប</th>
            </tr>
          </thead>
          <tbody>
            ${(products && products.length > 0) ? (
              products.slice(0, 2).map(p => `
                <tr style="border-bottom: 1px dotted #ccc;">
                  <td style="padding: 3px 0;">
                    <b>${p.name}</b>
                    <div style="font-size: 8.5px; color: #555;">${p.size ? `Size: ${p.size}` : ''} @$${Number(p.price || 0).toFixed(2)}</div>
                  </td>
                  <td style="text-align: center; font-weight: bold; padding: 3px 0;">1</td>
                  <td style="text-align: right; font-weight: bold; padding: 3px 0;">$${Number(p.price || 0).toFixed(2)}</td>
                </tr>
              `).join('')
            ) : `
              <tr style="border-bottom: 1px dotted #ccc;">
                <td style="padding: 3px 0;">
                  <b>ទំនិញគំរូ (Sample Item)</b>
                  <div style="font-size: 8.5px; color: #555;">Standard @$10.00</div>
                </td>
                <td style="text-align: center; font-weight: bold; padding: 3px 0;">1</td>
                <td style="text-align: right; font-weight: bold; padding: 3px 0;">$10.00</td>
              </tr>
            `}
          </tbody>
        </table>

        <div style="border-bottom: 1px dashed #000; margin: 6px 0;"></div>
        <div style="font-size: 10px; line-height: 1.4;">
          <div style="display: flex; justify-content: space-between;"><span>តម្លៃសរុប (Subtotal):</span><b>${sampleSubtotal.toFixed(2)}</b></div>
          ${isTaxEnabled ? `
            <div style="display: flex; justify-content: space-between; color: #1d4ed8; font-weight: bold;">
              <span>${taxLabel}${taxMode === 'inclusive' ? ' (រួមបញ្ចូល)' : ''}:</span>
              <span>${taxMode === 'inclusive' ? `(${sampleTax.toFixed(2)})` : `+${sampleTax.toFixed(2)}`}</span>
            </div>
          ` : ''}
          <div style="display: flex; justify-content: space-between; font-size: 13px; font-weight: 900; padding-top: 4px; border-top: 1px solid #000; margin-top: 2px;">
            <span>ទឹកប្រាក់សរុប (TOTAL):</span>
            <span>${sampleTotal.toFixed(2)}</span>
          </div>
          <div style="display: flex; justify-content: space-between; font-size: 11px; font-weight: bold; color: #333;">
            <span>គិតជាប្រាក់រៀល (KHR):</span>
            <span>${sampleTotalKHR.toLocaleString()} ៛</span>
          </div>
        </div>

        <div style="border-bottom: 1px dashed #000; margin: 6px 0;"></div>
        <div style="display: flex; justify-content: space-between; font-size: 10px;">
          <span>វិធីទូទាត់ (Payment):</span>
          <b>Bakong KHQR / Cash</b>
        </div>

        ${(storeSettings.showReceiptQr !== false && storeSettings.khqrImageUrl) ? `
          <div style="margin: 6px 0; padding: 2px; text-align: center;">
            <img src="${storeSettings.khqrImageUrl}" style="width: 76px; height: 76px; margin: 0 auto; object-fit: contain; display: block;" />
            <p style="font-size: 9px; font-weight: 900; text-transform: uppercase; margin: 3px 0 0 0;">${storeSettings.bankAccountName || activeStore?.owner_name || activeStore?.name || (activeStore?.id !== 'store_default_sabayluk' ? 'ហាងរបស់ខ្ញុំ' : 'SABAY LUK')}</p>
          </div>
        ` : '<div style="border-bottom: 1px dashed #000; margin: 6px 0;"></div>'}

        <div style="text-align: center; font-size: 9px; margin-top: 6px;">
          <p style="font-weight: bold; margin: 0;">${invoiceSettings.thankYouMsg || 'សូមអរគុណ! សូមអញ្ជើញមកម្តងទៀត'}</p>
          <p style="font-size: 8px; color: #555; margin: 2px 0 0 0;">${invoiceSettings.policyNote || 'ទំនិញដែលទិញរួចមិនអាចប្តូរជាប្រាក់វិញបានទេ'}</p>
          <p style="font-size: 7.5px; color: #888; margin: 3px 0 0 0;">*** System Powered by Sabay Luk POS ***</p>
        </div>
      </div>
    `;

    const printWindow = window.open('', '_blank', 'height=650,width=450');
    if (!printWindow) {
      alert('សូមអនុញ្ញាត Popup ដើម្បីបើកផ្ទាំងព្រីន (Please allow popups for printing)');
      return;
    }
    printWindow.document.write(`
      <!DOCTYPE html>
      <html>
        <head>
          <meta charset="utf-8">
          <title>Test Receipt Print - Sabay Luk</title>
          <style>
            @page { size: ${pageCss}; margin: 0mm; }
            * { box-sizing: border-box; -webkit-print-color-adjust: exact; print-color-adjust: exact; }
            body { margin: 0; padding: 0; background: #fff; }
          </style>
        </head>
        <body>
          ${testContent}
          <script>
            function triggerPrint() {
              try {
                window.focus();
                window.print();
              } catch (e) {
                console.error('Print error', e);
              }
            }
            if (document.readyState === 'complete') {
              setTimeout(triggerPrint, 250);
            } else {
              window.addEventListener('load', function() { setTimeout(triggerPrint, 250); });
              setTimeout(triggerPrint, 1200);
            }
            window.onafterprint = function() { window.close(); };
          </script>
        </body>
      </html>
    `);
    printWindow.document.close();
  };

  // State សម្រាប់ Modal ជ្រើសរើស Size/Variant ពេលចុចលើទំនិញ
  const [variantModalOpen, setVariantModalOpen] = useState(false);
  const [selectedProductForVariant, setSelectedProductForVariant] = useState(null);
  const [currentProductVariants, setCurrentProductVariants] = useState([]);
  const [loadingVariants, setLoadingVariants] = useState(false);

  // States សម្រាប់ទូទាត់ប្រាក់ និងវិក្កយបត្រ
  const [paymentModalOpen, setPaymentModalOpen] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState('Cash');
  const [amountTendered, setAmountTendered] = useState('');
  const [receiptData, setReceiptData] = useState(null);
  const [thermalPaperSize, setThermalPaperSize] = useState('80mm'); // '80mm' | '58mm'
  const [customerName, setCustomerName] = useState('អតិថិជនទូទៅ');
  const [customerPhone, setCustomerPhone] = useState('');
  const [isProcessingPayment, setIsProcessingPayment] = useState(false);

  // ⭐️ របៀបលក់ក្នុង POS (Price Mode: 'retail' | 'wholesale') ⭐️

  const [posPriceMode, setPosPriceMode] = useState('retail'); // 'retail' = លក់រាយ, 'wholesale' = លក់បោះដុំ
  const [modalPriceMode, setModalPriceMode] = useState('retail');

  // ⭐️ States សម្រាប់ Dropdown រើសអតិថិជន (MODERN CUSTOMER SELECTOR DROPDOWNS) ⭐️
  const [modalCustomerDropdownOpen, setModalCustomerDropdownOpen] = useState(false);
  const [posCustomerDropdownOpen, setPosCustomerDropdownOpen] = useState(false);
  const [customerPickerSearch, setCustomerPickerSearch] = useState('');

  const selectCustomerForSale = (cust) => {
    if (!cust) {
      setCustomerName('អតិថិជនទូទៅ');
      setCustomerPhone('');
      setModalCustomerDropdownOpen(false);
      setPosCustomerDropdownOpen(false);
      return;
    }
    setCustomerName(cust.name);
    setCustomerPhone(cust.phone || '');
    if (cust.discount_percent > 0) {
      setDiscount(cust.discount_percent);
      setDiscountType('%');
    }
    if (cust.tier === 'WHOLESALE') {
      handleSwitchPriceMode('wholesale');
    }
    setModalCustomerDropdownOpen(false);
    setPosCustomerDropdownOpen(false);
  };

  // ⭐️ States សម្រាប់ពន្ធអាករក្នុង POS (POS TAX / VAT 10% CONTROLS) ⭐️
  const [posTaxActive, setPosTaxActive] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('sabay_pos_tax_active');
      if (saved !== null) return saved === 'true';
    }
    return true; // Default ON (10% VAT)
  });
  const [posTaxRate, setPosTaxRate] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('sabay_pos_tax_rate');
      if (saved !== null) return Number(saved) || 10;
    }
    return 10; // Default 10%
  });
  const [posTaxMode, setPosTaxMode] = useState(() => {
    if (typeof window !== 'undefined') {
      const saved = localStorage.getItem('sabay_pos_tax_mode');
      if (saved) return saved;
    }
    return 'exclusive'; // Default 'exclusive' (+10%)
  });


  const [isMobileCartOpen, setIsMobileCartOpen] = useState(false);
  const [zReportModalOpen, setZReportModalOpen] = useState(false);
  const [shiftStartingCash, setShiftStartingCash] = useState(() => {
    if (typeof window !== 'undefined') {
      return parseFloat(localStorage.getItem('sabay_shift_starting_cash')) || 50.00;
    }
    return 50.00;
  });
  const [actualCashInput, setActualCashInput] = useState('');
  const [actualKhqrInput, setActualKhqrInput] = useState('');
  const [shiftClosingNote, setShiftClosingNote] = useState('');
  const [shiftHistory, setShiftHistory] = useState(() => {
    if (typeof window !== 'undefined') {
      try {
        const saved = localStorage.getItem('sabay_shift_history');
        if (saved) return JSON.parse(saved);
      } catch (e) {}
    }
    return [];
  });



  // ⭐️ ស្ដារ និងចងចាំទិន្នន័យចុងក្រោយរបស់ប្រព័ន្ធ POS ពេលបិទបើកឡើងវិញ (LocalStorage Persistence) ⭐️
  useEffect(() => {
    if (typeof window === 'undefined') return;

    // ១. ស្ដារ Price Mode (លក់រាយ ឬ លក់បោះដុំ)
    const savedPriceMode = localStorage.getItem('sabay_pos_price_mode');
    if (savedPriceMode === 'wholesale' || savedPriceMode === 'retail') {
      setPosPriceMode(savedPriceMode);
    }

    // ២. ស្ដារ Category ដែលបានជ្រើសរើសចុងក្រោយ
    const savedCategory = localStorage.getItem('sabay_pos_category');
    if (savedCategory) {
      setPosCategory(savedCategory);
    }

    // ៣. ស្ដារទំនិញក្នុងកន្ត្រក (Cart Items) តាម Store ជាក់ស្តែង
    try {
      localStorage.removeItem('sabay_pos_cart');
      const curStore = getActiveStore();
      const storeId = curStore?.id || 'store_default_sabayluk';
      const savedCart = localStorage.getItem(`sabay_pos_cart_${storeId}`);
      if (savedCart) {
        const parsed = JSON.parse(savedCart);
        if (Array.isArray(parsed) && parsed.length > 0) {
          setPosCart(parsed);
        } else {
          setPosCart([]);
        }
      } else {
        setPosCart([]);
      }
    } catch (e) {
      console.error('Error loading saved pos cart:', e);
    }

    // ៤. ស្ដារឈ្មោះ និងលេខទូរស័ព្ទអតិថិជន
    const savedCustomerName = localStorage.getItem('sabay_pos_customer_name');
    if (savedCustomerName) setCustomerName(savedCustomerName);
    const savedCustomerPhone = localStorage.getItem('sabay_pos_customer_phone');
    if (savedCustomerPhone) setCustomerPhone(savedCustomerPhone);

    // ៥. ស្ដារការបញ្ចុះតម្លៃ (Discount)
    const savedDiscount = localStorage.getItem('sabay_pos_discount');
    if (savedDiscount != null && savedDiscount !== '') setDiscount(Number(savedDiscount) || 0);
    const savedDiscountType = localStorage.getItem('sabay_pos_discount_type');
    if (savedDiscountType === '%' || savedDiscountType === '$') setDiscountType(savedDiscountType);

    // ៦. ស្ដារបញ្ជីផ្អាកការលក់ (Hold/Park Orders)
    try {
      const savedHolds = localStorage.getItem('sabay_pos_hold_orders');
      if (savedHolds) {
        const parsedHolds = JSON.parse(savedHolds);
        if (Array.isArray(parsedHolds)) setHoldOrders(parsedHolds);
      }
    } catch (e) {}
  }, []);

  // ⭐️ រក្សាទុកស្វ័យប្រវត្តិនូវរាល់ការផ្លាស់ប្តូរ POS States ចូល LocalStorage ⭐️
  useEffect(() => {
    if (isMounted) {
      localStorage.setItem('sabay_pos_price_mode', posPriceMode);
      localStorage.setItem('sabay_pos_tax_active', posTaxActive);
      localStorage.setItem('sabay_pos_tax_rate', posTaxRate);
      localStorage.setItem('sabay_pos_tax_mode', posTaxMode);
    }
  }, [posPriceMode, posTaxActive, posTaxRate, posTaxMode, isMounted]);

  useEffect(() => {
    if (isMounted) {
      localStorage.setItem('sabay_pos_category', posCategory);
    }
  }, [posCategory, isMounted]);

  useEffect(() => {
    if (isMounted) {
      try {
        const storeId = activeStore?.id || 'store_default_sabayluk';
        localStorage.setItem(`sabay_pos_cart_${storeId}`, JSON.stringify(posCart));
        localStorage.removeItem('sabay_pos_cart');
      } catch (e) {}
    }
  }, [posCart, activeStore?.id, isMounted]);

  useEffect(() => {
    if (isMounted) {
      localStorage.setItem('sabay_pos_customer_name', customerName);
      localStorage.setItem('sabay_pos_customer_phone', customerPhone);
      localStorage.setItem('sabay_pos_discount', discount.toString());
      localStorage.setItem('sabay_pos_discount_type', discountType);
    }
  }, [customerName, customerPhone, discount, discountType, isMounted]);

  useEffect(() => {
    if (isMounted) {
      try {
        localStorage.setItem('sabay_pos_hold_orders', JSON.stringify(holdOrders));
      } catch (e) {}
    }
  }, [holdOrders, isMounted]);

  // មុខងារគណនាតម្លៃលក់ក្នុង POS (គិតទាំងតម្លៃបោះដុំ និងលក់រាយ)
  const getProductPosPrice = (product, mode = posPriceMode) => {
    if (!product) return 0;
    if (mode === 'wholesale') {
      const wholesaleVal = parseFloat(product.wholesale_price);
      if (!isNaN(wholesaleVal) && wholesaleVal > 0) {
        const discount = parseFloat(product.wholesale_discount) || 0;
        return Math.max(0, wholesaleVal - discount);
      }
    }
    // Fallback ទៅតម្លៃលក់រាយ
    const retailVal = parseFloat(product.price) || 0;
    const discount = parseFloat(product.retail_discount) || 0;
    return Math.max(0, retailVal - discount);
  };

  // មុខងារប្តូររបៀបលក់សរុប (Switch Global Price Mode)
  const handleSwitchPriceMode = (newMode) => {
    setPosPriceMode(newMode);
    // ធ្វើបច្ចុប្បន្នភាពតម្លៃទំនិញទាំងអស់ក្នុងកន្ត្រកភ្លាមៗ
    setPosCart(prev => prev.map(item => {
      const prod = products.find(p => p.id === item.id);
      if (!prod) return item;
      const newPrice = getProductPosPrice(prod, newMode);
      return {
        ...item,
        price: newPrice,
        priceMode: newMode
      };
    }));
  };

  // មុខងារប្តូរតម្លៃដុំ/រាយ សម្រាប់តែទំនិញនីមួយៗក្នុងកន្ត្រក (Toggle Single Item in Cart)
  const toggleItemPriceMode = (cartItemId) => {
    setPosCart(prev => prev.map(item => {
      if (item.cartItemId !== cartItemId) return item;
      const nextMode = item.priceMode === 'wholesale' ? 'retail' : 'wholesale';
      const prod = products.find(p => p.id === item.id);
      const newPrice = prod ? getProductPosPrice(prod, nextMode) : item.price;
      return {
        ...item,
        price: newPrice,
        priceMode: nextMode
      };
    }));
  };

  // State បន្ថែមសម្រាប់ Modal Option
  const [modalSelectedSize, setModalSelectedSize] = useState('');
  const [modalSelectedColor, setModalSelectedColor] = useState('');
  const [modalQty, setModalQty] = useState(1);

  // ១. ពេលចុចលើទំនិញក្នុង POS (ទាញទាំង Variants និង Fallback ទំនិញចាស់)
  const handleProductClick = async (product) => {
    if (product.stock_qty <= 0) {
      alert('❌ ផលិតផលនេះអស់ពីស្តុកហើយ (Out of Stock)!');
      return;
    }

    setSelectedProductForVariant(product);
    setModalQty(1);
    setModalPriceMode(posPriceMode);
    setModalSelectedColor(product.color || '');
    setLoadingVariants(true);
    setVariantModalOpen(true);

    try {
      // ក. សាកល្បងទាញយកពី product_variants
      const { data: variants } = await supabase
        .from('product_variants')
        .select('*')
        .eq('product_id', product.id)
        .order('size', { ascending: true });

      if (variants && variants.length > 0) {
        setCurrentProductVariants(variants);
        // រើសយក Size ដំបូងដែលមានស្តុក
        const firstInStock = variants.find(v => v.stock_qty > 0) || variants[0];
        setModalSelectedSize(firstInStock.size);
        if (firstInStock.color) setModalSelectedColor(firstInStock.color);
      } else {
        // ខ. ⭐️ SMART FALLBACK: បើទំនិញចាស់គ្មានក្នុង product_variants គឺទាញពី product.size ផ្ទាល់
        let parsedVariants = [];
        if (product.size && product.size !== 'N/A') {
          if (product.size.includes(':')) {
            // ទម្រង់ "39:5, 40:10"
            parsedVariants = product.size.split(',').map((pair, idx) => {
              const [sz, qty] = pair.trim().split(':');
              return {
                id: `legacy_${idx}`,
                size: sz,
                color: product.color || '',
                stock_qty: parseInt(qty) || product.stock_qty,
                isLegacy: true
              };
            });
          } else {
            // ទម្រង់ "39, 40, 41"
            parsedVariants = product.size.split(',').map((sz, idx) => ({
              id: `legacy_${idx}`,
              size: sz.trim(),
              color: product.color || '',
              stock_qty: product.stock_qty,
              isLegacy: true
            }));
          }
        }

        setCurrentProductVariants(parsedVariants);
        if (parsedVariants.length > 0) {
          setModalSelectedSize(parsedVariants[0].size);
        } else {
          setModalSelectedSize('');
        }
      }
    } catch (err) {
      console.error(err);
    } finally {
      setLoadingVariants(false);
    }
  };

  // ២. បញ្ជាក់ការបញ្ចូលទៅកន្រ្តកពី Modal (Full Option Add to Cart)
  const handleConfirmAddToCart = () => {
    if (!selectedProductForVariant) return;

    const matchedVariant = currentProductVariants.find(v => 
      v.size === modalSelectedSize && (modalSelectedColor ? (v.color || '').trim().toLowerCase() === modalSelectedColor.trim().toLowerCase() : true)
    ) || currentProductVariants.find(v => v.size === modalSelectedSize) || currentProductVariants[0];
    const variantId = matchedVariant && !matchedVariant.isLegacy ? matchedVariant.id : null;
    const maxStock = matchedVariant ? matchedVariant.stock_qty : selectedProductForVariant.stock_qty;

    if (maxStock <= 0) {
      alert('❌ ទំហំនេះអស់ពីស្តុកហើយ!');
      return;
    }

    if (modalQty > maxStock) {
      alert(`❌ ចំនួនលើសស្តុកដែលមាន (ស្តុកនៅសល់ ${maxStock})!`);
      return;
    }

    const activePrice = getProductPosPrice(selectedProductForVariant, modalPriceMode);
    const cartItemId = `${selectedProductForVariant.id}_${modalSelectedSize || 'nosize'}_${modalSelectedColor || 'nocolor'}_${modalPriceMode}`;

    setPosCart(prev => {
      const existing = prev.find(item => item.cartItemId === cartItemId);
      if (existing) {
        const newQty = existing.qty + modalQty;
        if (newQty > maxStock) {
          alert(`❌ មិនអាចបន្ថែមបានទេ! ចំនួនសរុបក្នុងកន្រ្តកលើសស្តុក (${maxStock})។`);
          return prev;
        }
        return prev.map(item => item.cartItemId === cartItemId ? { ...item, qty: newQty } : item);
      }

      return [...prev, {
        cartItemId,
        id: selectedProductForVariant.id,
        variantId: variantId,
        name: selectedProductForVariant.name,
        sku: selectedProductForVariant.sku,
        size: modalSelectedSize || 'N/A',
        color: modalSelectedColor || selectedProductForVariant.color || 'N/A',
        price: activePrice,
        priceMode: modalPriceMode,
        image_url: selectedProductForVariant.image_url,
        maxStock: maxStock,
        qty: modalQty
      }];
    });

    setVariantModalOpen(false);
    setSelectedProductForVariant(null);
  };

  // ២. បន្ថែមទំនិញចូលកន្រ្តក
  const addItemToPosCart = (product, variant) => {
    const activePrice = getProductPosPrice(product, posPriceMode);
    const cartItemId = variant ? `${product.id}_${variant.id}_${posPriceMode}` : `${product.id}_base_${posPriceMode}`;
    const maxStock = variant ? variant.stock_qty : product.stock_qty;

    if (maxStock <= 0) {
      alert('❌ ទំហំ ឬទំនិញនេះអស់ពីស្តុកហើយ!');
      return;
    }

    setPosCart(prev => {
      const existing = prev.find(item => item.cartItemId === cartItemId);
      if (existing) {
        if (existing.qty >= maxStock) {
          alert(`❌ មិនអាចបន្ថែមបានទេ! ស្តុកទំហំនេះមានត្រឹមតែ ${maxStock} ប៉ុណ្ណោះ។`);
          return prev;
        }
        return prev.map(item => item.cartItemId === cartItemId ? { ...item, qty: item.qty + 1 } : item);
      }

      return [...prev, {
        cartItemId,
        id: product.id,
        variantId: variant ? variant.id : null,
        name: product.name,
        sku: variant ? variant.sku : product.sku,
        size: variant ? variant.size : product.size,
        color: variant ? variant.color : product.color,
        price: activePrice,
        priceMode: posPriceMode,
        image_url: product.image_url,
        maxStock: maxStock,
        qty: 1
      }];
    });

    setVariantModalOpen(false);
    setSelectedProductForVariant(null);
    setPosSearch('');
  };

  // ⭐️ Handler ពេលម៉ាស៊ីនស្កេន ឬកាមេរ៉ាស្កេនបាកូដបានជោគជ័យ (Universal Scanner Hook - Auto Add & Beep) ⭐️
  const handleUniversalBarcodeScan = (scannedCode) => {
    if (!scannedCode) return;
    const query = scannedCode.trim().toLowerCase();
    
    // ស្វែងរកទំនិញតាម SKU, Barcode, ID, ឬឈ្មោះ ក្នុងហាងសកម្ម
    const matchedProduct = currentStoreProducts.find(p => 
      (p.sku && p.sku.toLowerCase() === query) ||
      (p.barcode && p.barcode.toLowerCase() === query) ||
      (p.id && p.id.toLowerCase() === query) ||
      (p.name && p.name.toLowerCase() === query)
    ) || products.find(p => p.sku && p.sku.toLowerCase() === query);

    if (matchedProduct) {
      if (scannerSoundEnabled) playScannerBeep();
      setToastNotification(`🎯 ស្កេនបាន: ${matchedProduct.name} (${matchedProduct.sku || ''})`);
      setTimeout(() => setToastNotification(null), 2500);

      // ប្រសិនបើបើក Option autoAddVariant ហើយទំនិញមានស្តុក ➔ បញ្ចូលកន្ត្រកភ្លាមៗ!
      if (scannerAutoAddVariant && matchedProduct.stock_qty > 0) {
        // បើគ្មាន Variant ច្រើន ឬជាទំនិញធម្មតា ➔ Add ចូលកន្ត្រកភ្លាមៗ
        addItemToPosCart(matchedProduct, null);
      } else {
        handleProductClick(matchedProduct);
      }
    } else {
      if (scannerSoundEnabled) playScannerErrorBeep();
      setToastNotification(`❌ រកមិនឃើញទំនិញដែលមានបាកូដ "${scannedCode}" ឡើយ!`);
      setTimeout(() => setToastNotification(null), 3500);
    }
  };

  // ៣. ស្កេនបាកូដ / SKU តាមក្តារចុច ឬកាំភ្លើងស្កេន USB/Bluetooth
  const handleBarcodeScan = (e) => {
    if (e.key === 'Enter' && posSearch.trim() !== '') {
        playScannerBeep();
      const query = posSearch.trim().toLowerCase();
      const matchedProduct = products.find(p => p.sku && (p.sku.toLowerCase() === query || p.name.toLowerCase().includes(query)));
      if (matchedProduct) {
        handleProductClick(matchedProduct);
      } else {
        alert('❌ រកមិនឃើញទំនិញក្នុងប្រព័ន្ធទេ!');
        setPosSearch('');
      }
    }
  };

  // ៤. បង្កើន/បន្ថយចំនួនក្នុងកន្រ្តក
  const updatePosQty = (cartItemId, delta) => {
    setPosCart(prev => prev.map(item => {
      if (item.cartItemId === cartItemId) {
        const newQty = item.qty + delta;
        if (newQty > item.maxStock) {
          alert(`❌ ចំនួនលើសស្តុកដែលមាន (នៅសល់ ${item.maxStock})!`);
          return item;
        }
        return newQty > 0 ? { ...item, qty: newQty } : item;
      }
      return item;
    }));
  };

  const removePosItem = (cartItemId) => setPosCart(prev => prev.filter(item => item.cartItemId !== cartItemId));
  const clearCart = () => setPosCart([]);

  // ៥. គណនាប្រាក់ ($ និង ៛) រួមទាំងពន្ធអាករ VAT 10% & Loyalty Discount Full Option
  const posSubtotal = posCart.reduce((sum, item) => sum + (item.price * item.qty), 0);
  const posPointsDiscount = (posUseLoyaltyPoints && posLoyaltyPointsToRedeem > 0)
    ? (Math.floor(posLoyaltyPointsToRedeem / 50) * 1.0)
    : 0;
  const baseDiscountVal = discountType === '%' ? posSubtotal * (Number(discount) / 100) : Number(discount);
  const posDiscountValue = baseDiscountVal + posPointsDiscount;
  const posAfterDiscount = Math.max(0, posSubtotal - posDiscountValue);

  // គណនាពន្ធអាករ VAT
  const effectiveTaxRate = posTaxActive ? (Number(posTaxRate) || 0) : 0;
  let posTaxAmount = 0;
  let posTotal = posAfterDiscount;

  if (effectiveTaxRate > 0) {
    if (posTaxMode === 'exclusive') {
      posTaxAmount = (posAfterDiscount * effectiveTaxRate) / 100;
      posTotal = posAfterDiscount + posTaxAmount;
    } else {
      // Inclusive: ពន្ធមានស្រាប់ក្នុងតម្លៃ
      posTaxAmount = posAfterDiscount - (posAfterDiscount / (1 + (effectiveTaxRate / 100)));
      posTotal = posAfterDiscount;
    }
  }

  const posTotalKHR = Math.round(posTotal * exchangeRate);
  const changeAmount = paymentMethod === 'Credit / ជំពាក់' ? 0 : (Number(amountTendered) - posTotal);

  // ⭐️ KEYBOARD SHORTCUT KEYS (HOTKEYS) សម្រាប់អ្នកកាន់បេឡា (Cashier Speed) ⭐️
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const handleKeyDown = (e) => {
      // ប្រសិនបើមិនមែននៅលើ Tab 'pos' ទេ មិនបាច់ដំណើរការ hotkeys ឡើយ
      if (activeTab !== 'pos') return;

      // ⭐️ ១. GLOBAL HARDWARE SCANNER GUN LISTENER (USB / Bluetooth Barcode Gun) ⭐️
      const currentTime = Date.now();
      const timeDiff = currentTime - lastBarcodeKeyTimeRef.current;
      lastBarcodeKeyTimeRef.current = currentTime;

      const activeEl = document.activeElement;
      const isMainSearch = activeEl && activeEl === searchInputRef.current;
      const isOtherInput = activeEl && activeEl !== searchInputRef.current && (activeEl.tagName === 'INPUT' || activeEl.tagName === 'TEXTAREA' || activeEl.tagName === 'SELECT');

      // បើមិនមែនកំពុងវាយក្នុង Modal inputs ផ្សេងទៀតទេ គឺចាប់សញ្ញាពីកាំភ្លើងស្កេន
      if (!isOtherInput) {
        if (e.key === 'Enter') {
          const buffer = barcodeGunBufferRef.current.trim();
          if (buffer.length >= 2) {
            e.preventDefault();
            barcodeGunBufferRef.current = '';
            handleUniversalBarcodeScan(buffer);
            return;
          }
          barcodeGunBufferRef.current = '';
        } else if (e.key.length === 1 && !e.ctrlKey && !e.altKey && !e.metaKey) {
          if (timeDiff > 120) {
            barcodeGunBufferRef.current = e.key;
          } else {
            barcodeGunBufferRef.current += e.key;
          }
        }
      }

      const isInput = isOtherInput || isMainSearch;

      // F2 ➔ ស្វែងរកទំនិញរហ័ស (Focus Quick Search / Barcode)
      if (e.key === 'F2') {
        e.preventDefault();
        if (searchInputRef && searchInputRef.current) {
          searchInputRef.current.focus();
          searchInputRef.current.select();
        }
        return;
      }

      // F4 ➔ ប្តូររវាងលក់រាយ ↔️ លក់បោះដុំ (Switch Retail / Wholesale)
      if (e.key === 'F4') {
        e.preventDefault();
        handleSwitchPriceMode(posPriceMode === 'wholesale' ? 'retail' : 'wholesale');
        return;
      }

      // F8 ➔ បើកផ្ទាំងទូទាត់ប្រាក់ (Checkout / Pay)
      if (e.key === 'F8') {
        e.preventDefault();
        if (posCart.length > 0 && !paymentModalOpen && !receiptData) {
          setAmountTendered(posTotal.toString());
          setPaymentModalOpen(true);
        }
        return;
      }

      // Space ➔ ចុច Checkout ពេលមិនស្ថិតនៅក្នុង input/textarea
      if (e.code === 'Space' && !isInput && !paymentModalOpen && !receiptData && !variantModalOpen && !zReportModalOpen) {
        if (posCart.length > 0) {
          e.preventDefault();
          setAmountTendered(posTotal.toString());
          setPaymentModalOpen(true);
        }
        return;
      }

      // F9 ➔ ព្រីនវិក្កយបត្រ (Print Receipt) ពេលផ្ទាំង Receipt កំពុងបើក
      if (e.key === 'F9') {
        e.preventDefault();
        const printBtn = document.getElementById('receipt-print-trigger-btn');
        if (printBtn) {
          printBtn.click();
        } else if (receiptData) {
          const printArea = document.getElementById('receipt-print-area');
          if (printArea) {
            const printContent = printArea.innerHTML;
            const printWindow = window.open('', '_blank', 'height=650,width=450');
            const widthCss = thermalPaperSize === '58mm' ? '54mm' : '76mm';
            const pageCss = thermalPaperSize === '58mm' ? '58mm auto' : '80mm auto';
            const fontSize = thermalPaperSize === '58mm' ? '10px' : '11px';
            printWindow.document.write(`
              <html>
                <head>
                  <title>វិក្កយបត្រ ${receiptData.orderId || ''}</title>
                  <style>
                    @page { size: ${pageCss}; margin: 0; }
                    body { font-family: monospace; width: ${widthCss}; margin: 0 auto; padding: 4mm 2mm; font-size: ${fontSize}; line-height: 1.25; color: #000; }
                    th, td { padding: 2px 0; }
                    .border-dashed { border-style: dashed; }
                    .border-b { border-bottom-width: 1px; }
                    .border-t { border-top-width: 1px; }
                    .border-black { border-color: #000; }
                  </style>
                </head>
                <body>
                  ${printContent}
                  <script>
                    window.onload = function() { window.focus(); window.print(); }; window.onafterprint = function() { window.close(); };
                  </script>
                </body>
              </html>
            `);
            printWindow.document.close();
          }
        }
        return;
      }

      // Esc ➔ បិទ Modal នានា
      if (e.key === 'Escape') {
        if (zReportModalOpen) setZReportModalOpen(false);
        else if (receiptData) setReceiptData(null);
        else if (paymentModalOpen) setPaymentModalOpen(false);
        else if (variantModalOpen) setVariantModalOpen(false);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [activeTab, posPriceMode, posCart, posTotal, paymentModalOpen, receiptData, variantModalOpen, zReportModalOpen, thermalPaperSize]);

  // ⭐️ គណនាស្ថិតិវេនលក់បច្ចុប្បន្ន (Z-Report Shift Calculation) ⭐️
  const getShiftReportStats = () => {
    // ស្វែងរក Orders ថ្ងៃនេះ
    const todayStr = new Date().toISOString().slice(0, 10);
    const todayOrders = (realOrders || []).filter(o => {
      const oDate = o.created_at ? o.created_at.slice(0, 10) : '';
      return oDate === todayStr && o.status !== 'Cancelled';
    });

    const cashOrders = todayOrders.filter(o => o.payment_method === 'Cash' || !o.payment_method);
    const khqrOrders = todayOrders.filter(o => o.payment_method && o.payment_method.toLowerCase().includes('khqr') || o.payment_method === 'Transfer' || o.payment_method === 'Bank');

    const systemCashSales = cashOrders.reduce((sum, o) => sum + (parseFloat(o.total_amount) || 0), 0);
    const systemKhqrSales = khqrOrders.reduce((sum, o) => sum + (parseFloat(o.total_amount) || 0), 0);
    const systemTotalSales = systemCashSales + systemKhqrSales;
    const expectedDrawerCash = shiftStartingCash + systemCashSales;

    const actualCash = actualCashInput !== '' ? parseFloat(actualCashInput) : expectedDrawerCash;
    const actualKhqr = actualKhqrInput !== '' ? parseFloat(actualKhqrInput) : systemKhqrSales;

    const cashDiff = actualCash - expectedDrawerCash;
    const khqrDiff = actualKhqr - systemKhqrSales;

    return {
      todayStr,
      orderCount: todayOrders.length,
      cashOrderCount: cashOrders.length,
      khqrOrderCount: khqrOrders.length,
      startingCash: shiftStartingCash,
      systemCashSales,
      systemKhqrSales,
      systemTotalSales,
      expectedDrawerCash,
      actualCash,
      actualKhqr,
      cashDiff,
      khqrDiff,
      todayOrders
    };
  };

  // មុខងារបិទបញ្ជីវេនលក់ (Close Shift / Save Z-Report)
  const handleSaveShiftClose = () => {
    const stats = getShiftReportStats();
    const newRecord = {
      id: 'Z-' + Date.now().toString().slice(-6),
      closedAt: new Date().toISOString(),
      closedBy: storeSettings.storeName || 'Cashier',
      startingCash: stats.startingCash,
      systemCashSales: stats.systemCashSales,
      systemKhqrSales: stats.systemKhqrSales,
      systemTotalSales: stats.systemTotalSales,
      expectedDrawerCash: stats.expectedDrawerCash,
      actualCash: stats.actualCash,
      actualKhqr: stats.actualKhqr,
      cashDiff: stats.cashDiff,
      khqrDiff: stats.khqrDiff,
      orderCount: stats.orderCount,
      notes: shiftClosingNote.trim()
    };

    const updated = [newRecord, ...shiftHistory];
    setShiftHistory(updated);
    if (typeof window !== 'undefined') {
      localStorage.setItem('sabay_shift_history', JSON.stringify(updated));
    }
    alert('✅ បានកត់ត្រាបិទបញ្ជីវេនលក់ប្រចាំថ្ងៃ (Z-Report) ដោយជោគជ័យ!');
    setShiftClosingNote('');
  };

  // ៦. ផ្អាកការលក់ (Hold/Park) និងបន្ត (Resume) រួមទាំងឈ្មោះអតិថិជន
  const parkOrder = () => {
    if (posCart.length === 0) return;
    setHoldOrders([...holdOrders, { 
      id: `ORD-${Date.now().toString().slice(-4)}`, 
      cart: posCart, 
      customer: customerName,
      phone: customerPhone,
      time: new Date().toLocaleTimeString() 
    }]);
    setPosCart([]);
    setCustomerName('អតិថិជនទូទៅ');
    setCustomerPhone('');
  };

  const resumeOrder = (index) => {
    const target = holdOrders[index];
    setPosCart(target.cart);
    setCustomerName(target.customer || 'អតិថិជនទូទៅ');
    setCustomerPhone(target.phone || '');
    setHoldOrders(holdOrders.filter((_, i) => i !== index));
  };

    // ⭐️ មុខងារបញ្ជាក់ការលក់ និងរក្សាទុកប្រវត្តិ History Full Option ⭐️
  const processPayment = async () => {
    if (guardDemoAction("កាត់ស្តុក ឬលក់ជាក់ស្តែង")) return;
    if (paymentMethod === 'Cash' && changeAmount < 0) return alert('❌ ទឹកប្រាក់ទទួលមិនគ្រប់គ្រាន់ទេ!');
    if (paymentMethod === 'Credit / ជំពាក់' && (!customerName || customerName === 'អតិថិជនទូទៅ')) {
      return alert('❌ សូមជ្រើសរើសអតិថិជនជាមុនសិន មុនពេលលក់ជំពាក់ (Credit Sale)!');
    }
    setIsProcessingPayment(true);

    try {
      const generatedOrderId = `ORD-${Date.now().toString().slice(-6)}`;
      const affectedLowStockItems = [];
      const stockAdjustments = [];
      const isCurrentlyOnline = typeof navigator !== 'undefined' ? navigator.onLine : true;

      // ១. កាត់ស្តុកចេញពី product_variants និង products
      for (const item of posCart) {
        if (item.variantId) {
          const { data: vData } = await supabase.from('product_variants').select('stock_qty').eq('id', item.variantId).single();
          const prevVQty = vData ? vData.stock_qty : item.maxStock;
          const newVQty = Math.max(0, prevVQty - item.qty);

          await supabase.from('product_variants').update({ stock_qty: newVQty }).eq('id', item.variantId);
        }

        const { data: pData } = await supabase.from('products').select('stock_qty, low_stock_alert, name, sku, category, price').eq('id', item.id).single();
        const prevPQty = pData ? pData.stock_qty : 0;
        const newPQty = Math.max(0, prevPQty - item.qty);

        stockAdjustments.push({ productId: item.id, qty: item.qty });

        // Update local products state immediately
        setProducts(prevProds => prevProds.map(p => p.id === item.id ? { ...p, stock_qty: newPQty, status: newPQty > 0 ? 'In Stock' : 'Out of Stock' } : p));

        if (isCurrentlyOnline) {
          try {
            await supabase.from('products').update({ 
              stock_qty: newPQty,
              status: newPQty > 0 ? 'In Stock' : 'Out of Stock'
            }).eq('id', item.id);
          } catch (e) {
            console.warn('Network error updating stock in cloud, recorded for sync:', e);
          }
        }

        // ពិនិត្យកម្រិតស្តុកទាប
        const alertThreshold = pData?.low_stock_alert || storeSettings.lowStockThreshold || 5;
        if (newPQty <= alertThreshold) {
          affectedLowStockItems.push({
            name: item.name,
            sku: item.sku,
            category: item.category,
            stock_qty: newPQty,
            low_stock_alert: alertThreshold,
            price: item.price
          });
        }

        // កត់ត្រាចូល stock_movements (បើ online)
        if (isCurrentlyOnline) {
          try {
            await supabase.from('stock_movements').insert([{
              product_id: item.id,
              variant_id: item.variantId,
              type: 'SALE',
              qty_change: -item.qty,
              previous_qty: prevPQty,
              new_qty: newPQty,
              reason: `លក់ចេញតាម POS វិក្កយបត្រ ${generatedOrderId} (Size: ${item.size || 'ទូទៅ'})`
            }]);
          } catch (mvtErr) {}
        }
      }

      // ២. ⭐️ រក្សាទុកប្រវត្តិពេញលេញចូលតារាង orders (Full Option History) ⭐️
      const resolvedCustomerName = customerName && customerName.trim() ? customerName.trim() : 'អតិថិជនទូទៅ';
      const resolvedCustomerPhone = customerPhone && customerPhone.trim() ? customerPhone.trim() : 'N/A';

      const orderPayload = {
        store_id: activeStore?.id || 'store_default_sabayluk',
        order_id: generatedOrderId,
        customer_name: resolvedCustomerName,
        phone: resolvedCustomerPhone,
        phone_number: resolvedCustomerPhone,
        address: 'POS មុខហាង',
        delivery_address: 'POS មុខហាង',
        total_amount: posTotal,
        subtotal: posSubtotal,
        discount: posDiscountValue,
        payment_method: paymentMethod,
        status: 'Completed',
        order_type: 'POS',
        created_at: new Date().toISOString(),
        items: [
          ...posCart.map(item => ({
            id: item.id,
            name: item.name,
            size: item.size || 'N/A',
            color: item.color || 'N/A',
            price: item.price,
            qty: item.qty,
            image_url: item.image_url
          })),
          ...(posTaxAmount > 0 ? [{
            is_tax_meta: true,
            tax_rate: effectiveTaxRate,
            tax_amount: posTaxAmount,
            tax_mode: posTaxMode,
            tax_label: storeSettings.taxLabel || 'ពន្ធអាករ (VAT 10%)',
            vat_tin: storeSettings.vatTin || invoiceSettings.vatTin || ''
          }] : []),
          {
            is_pos_meta: true,
            cashier_name: currentStaff?.name || 'Admin',
            cashier_id: currentStaff?.id || 'STAFF-1',
            tax_amount: posTaxAmount
          }
        ]
      };

      // ⭐️ សម្អាត Cloud Payload ឱ្យស្របតាម Schema របស់តារាង orders ក្នុង Supabase
      const VALID_ORDER_COLS = [
        'order_id', 'store_id', 'customer_name', 'phone', 'phone_number',
        'address', 'delivery_address', 'total_amount', 'subtotal', 'discount',
        'payment_method', 'status', 'order_type', 'items', 'created_at'
      ];
      const cloudPayload = {};
      VALID_ORDER_COLS.forEach(k => {
        if (orderPayload[k] !== undefined) cloudPayload[k] = orderPayload[k];
      });

      if (isCurrentlyOnline) {
        try {
          let { error: orderError } = await supabase.from('orders').insert([cloudPayload]);
          // Resilient retry បើសិន schema មិនទាន់ស្គាល់ column ណាមួយ
          if (orderError && orderError.message && orderError.message.includes('Could not find the') && orderError.message.includes('column')) {
            const match = orderError.message.match(/Could not find the '([^']+)' column/);
            if (match && match[1]) {
              delete cloudPayload[match[1]];
              const retry = await supabase.from('orders').insert([cloudPayload]);
              orderError = retry.error;
            }
          }
          if (orderError) throw orderError;
        } catch (netErr) {
          console.warn('Failed cloud save, queuing offline order:', netErr);
          queueOfflineOrder(orderPayload, stockAdjustments);
          setToastNotification('📡 បានកត់ត្រាការលក់ក្រៅបណ្តាញ (Offline Saved)! នឹង Sync ស្វ័យប្រវត្តិតាមក្រោយ។');
        }
      } else {
        queueOfflineOrder(orderPayload, stockAdjustments);
        setToastNotification('📡 បានកត់ត្រាការលក់ក្រៅបណ្តាញ (Offline Saved)! នឹង Sync ស្វ័យប្រវត្តិតាមក្រោយ។');
      }

      // Add to local realOrders state so UI reflects the new sale immediately on top without duplicate
      setRealOrders(prev => {
        const newOrder = {
          ...orderPayload,
          id: orderPayload.order_id || `ord_${Date.now()}`,
          customer: resolvedCustomerName,
          total: posTotal,
          payment: paymentMethod
        };
        const filteredPrev = prev.filter(p => String(p.order_id || p.id).trim() !== String(newOrder.order_id || newOrder.id).trim());
        return [newOrder, ...filteredPrev];
      });

      // ២.៥ ⭐️ គ្រប់គ្រងបំណុល (Debt Charge) និងពិន្ទុ Loyalty (Points Accrual & Redemption) ⭐️
      const matchedCust = customers.find(c => 
        (c.name && customerName && c.name.toLowerCase() === customerName.toLowerCase()) || 
        (c.phone && customerPhone && c.phone === customerPhone)
      );

      const isCreditSale = paymentMethod === 'Credit / ជំពាក់';
      const prevDebt = matchedCust ? (parseFloat(matchedCust.debt_balance) || 0) : 0;
      const newDebt = isCreditSale ? (prevDebt + posTotal) : prevDebt;

      const currentPts = matchedCust && matchedCust.loyalty_points != null ? Number(matchedCust.loyalty_points) : 0;
      const redeemedPoints = (posUseLoyaltyPoints && posLoyaltyPointsToRedeem > 0)
        ? Math.min(currentPts, posLoyaltyPointsToRedeem)
        : 0;
      const earnedPoints = matchedCust ? Math.floor(posTotal) : 0; // $1 = 1 point
      const updatedPts = matchedCust ? Math.max(0, currentPts - redeemedPoints + earnedPoints) : null;

      if (matchedCust) {
        const debtHist = [...(matchedCust.debt_history || [])];
        if (isCreditSale) {
          debtHist.unshift({
            id: `DH-${Date.now()}`,
            order_id: generatedOrderId,
            date: new Date().toISOString(),
            type: 'CHARGE',
            amount: posTotal,
            prev_balance: prevDebt,
            remaining_balance: newDebt,
            due_date: posDueDate || null,
            note: posDebtNote.trim() || `លក់ជំពាក់តាម POS #${generatedOrderId}`,
            recorded_by: currentStaff?.name || 'Cashier'
          });
        }

        const ptsHist = [...(matchedCust.points_history || [])];
        if (redeemedPoints > 0) {
          ptsHist.unshift({
            id: `LP-${Date.now()}-1`,
            order_id: generatedOrderId,
            date: new Date().toISOString(),
            type: 'REDEEMED',
            points: -redeemedPoints,
            prev_points: currentPts,
            remaining_points: currentPts - redeemedPoints,
            reason: `កាត់ពិន្ទុបញ្ចុះតម្លៃ POS #${generatedOrderId} (-$${(redeemedPoints / 50).toFixed(2)})`
          });
        }
        if (earnedPoints > 0) {
          ptsHist.unshift({
            id: `LP-${Date.now()}-2`,
            order_id: generatedOrderId,
            date: new Date().toISOString(),
            type: 'EARNED',
            points: earnedPoints,
            prev_points: currentPts - redeemedPoints,
            remaining_points: updatedPts,
            reason: `ទទួលបានពីការទិញទំនិញ POS #${generatedOrderId}`
          });
        }

        setCustomers(prev => prev.map(c => {
          if (c.id === matchedCust.id) {
            return {
              ...c,
              debt_balance: isCreditSale ? newDebt : (parseFloat(c.debt_balance) || 0),
              debt_history: isCreditSale ? debtHist : (c.debt_history || []),
              loyalty_points: updatedPts,
              points_history: ptsHist
            };
          }
          return c;
        }));
      }

      // ៣. ចងក្រងទិន្នន័យដើម្បីបង្ហាញ Receipt
      const receipt = {
        orderId: generatedOrderId,
        date: new Date().toLocaleString(),
        items: [...posCart],
        subtotal: posSubtotal,
        discount: posDiscountValue,
        taxAmount: posTaxAmount,
        taxRate: effectiveTaxRate,
        taxMode: posTaxMode,
        taxLabel: storeSettings.taxLabel || 'ពន្ធអាករ (VAT 10%)',
        vatTin: storeSettings.vatTin || invoiceSettings.vatTin || '',
        total: posTotal,
        totalKHR: posTotalKHR,
        method: paymentMethod,
        tendered: paymentMethod === 'Cash' ? Number(amountTendered) : posTotal,
        change: changeAmount > 0 ? changeAmount : 0,
        customer: resolvedCustomerName,
        phone: resolvedCustomerPhone,
        isCreditSale: isCreditSale,
        debtBalance: isCreditSale ? newDebt : prevDebt,
        dueDate: posDueDate || null,
        earnedPoints: earnedPoints,
        redeemedPoints: redeemedPoints,
        loyaltyBalance: updatedPts
      };

      setReceiptData(receipt);
      setPaymentModalOpen(false);
      setPosCart([]);
      setAmountTendered('');
      setDiscount(0);
      setCustomerName('អតិថិជនទូទៅ');
      setCustomerPhone('');
      setPosDueDate('');
      setPosDebtNote('');
      setPosUseLoyaltyPoints(false);
      setPosLoyaltyPointsToRedeem(0);

      // ៤. ⭐️ ធ្វើបច្ចុប្បន្នភាពទិន្នន័យស្តុក និងប្រវត្តិ Orders ភ្លាមៗ ⭐️
      fetchProducts();
      fetchRealOrders();

      // 🚨 ៤.១ ស្វ័យប្រវត្តិកម្មផ្ញើវិក្កយបត្រ PDF ចូល Telegram ពេលគិតលុយរួច (POS AUTO PDF INVOICE) ⭐️
      if (posEnableTelegramAlert) {
        sendTelegramNotification({
          action: 'send_invoice',
          order: {
            ...orderPayload,
            order_id: generatedOrderId,
            items: posCart
          }
        }).then(res => {
          if (res?.success) {
            setToastNotification('✈️ បានផ្ញើវិក្កយបត្រទៅ Telegram រួចរាល់!');
            setTimeout(() => setToastNotification(null), 3000);
          }
        }).catch(err => console.warn('Auto send POS invoice to Telegram error:', err));
      }

      // 🚨 ជូនដំណឹងស្វ័យប្រវត្តិតាម Telegram បើស្តុកធ្លាក់ដល់កម្រិតទាប (Low Stock Alert)
      if (affectedLowStockItems.length > 0 && storeSettings.enableLowStockAlert && storeSettings.telegramBotToken && storeSettings.telegramChatId) {
        sendTelegramNotification({ action: 'low_stock', items: affectedLowStockItems });
      }

    } catch (error) {
      console.error('POS Checkout Error:', error);
      alert('❌ មានបញ្ហាក្នុងការទូទាត់ប្រាក់: ' + error.message);
    } finally {
      setIsProcessingPayment(false);
    }
  };

  
  // ================= ផ្នែក Upload & Add New Product (រួមបញ្ចូល State, Draft & Reorder) =================
  const [name, setName] = useState('');
  const [sku, setSku] = useState(() => {
    if (typeof window !== 'undefined') {
      const sid = activeStore?.id || 'store_default_sabayluk';
      const storePrefix = getStoreSkuPrefix(activeStore);
      const savedSku = localStorage.getItem(`sabay_current_sku_${sid}`) || localStorage.getItem(`sabay_last_saved_sku_${sid}`);
      if (savedSku && savedSku.startsWith(storePrefix)) {
        return savedSku;
      }
      return `${storePrefix}1001`;
    }
    return 'SL-1001';
  });
