                  const delta = parseInt(loyaltyPointsDelta, 10) || 0;
                  const cur = loyaltyAdjustCustomer.loyalty_points || 0;
                  const fin = loyaltyAdjustType === 'ADD' ? cur + delta : Math.max(0, cur - delta);
